export const mod = (attr) => Math.floor(((attr ?? 10) - 10) / 2);

// Maestria == Treinamento (mesmo valor), por faixa de ND.
// Até o 21 a faixa é de 4 em 4 níveis; do 21 em diante, de 5 em 5
// (21, 26, 31, 36). Os dois últimos degraus vieram do autor em 2026-07-27.
export const maestria = (nd) => {
  if (nd >= 36) return 10;
  if (nd >= 31) return 9;
  if (nd >= 26) return 8;
  if (nd >= 21) return 7;
  if (nd >= 17) return 6;
  if (nd >= 13) return 5;
  if (nd >= 9) return 4;
  if (nd >= 5) return 3;
  return 2;
};

// Multiplicador de HP por Patamar, aplicado direto sobre a base.
// A planilha tinha um `×2` fixo + patamarMult {comum 1, desafio 1, calamidade 1,5, beyond 2},
// o que dava um efetivo de 2/2/3/4 (Comum empatado com Desafio). O `×2` era, na prática,
// o multiplicador do Desafio: foi absorvido aqui, e o Comum virou metade do Desafio.
export const HP_PATAMAR_MULT = { comum: 1, desafio: 2, calamidade: 3, beyond: 4 };

// Stats que a aba Cálculos permite sobrescrever (valor final, padrão StatField).
export const OVERRIDABLE = ["hp", "pe", "defesa", "cd", "rdGeral", "rdEspecifico", "rdAlma", "movimento", "atencao", "iniciativa"];

const INT = (x) => Math.floor(x); // INT() da planilha (ND > 0 → floor)

/**
 * As FAMÍLIAS de variável do DSL, completas.
 *
 * ⚠ Existe porque o `evalNumber` da 2.5.2 não trata identificador desconhecido:
 * a expressão inteira cai no fallback, calada. Sem isto, `2 + (esc_combatente
 * >= 8)` numa criatura sem Combatente daria 0 em vez de 2, e o Roubo de
 * Habilidade (Restringido 2°), que importa habilidade de outra classe, nunca
 * funcionaria. Montado uma vez, dos catálogos, e passado ao contexto.
 */
/* ⚠ MONTADO POR ÉPOCA DE ADDON, e não uma vez no import (2026-09-07).

   Ele era um `const` de módulo, avaliado quando este arquivo carrega. Os
   religadores de Addon dão `splice` nos catálogos DEPOIS disso, então o
   vocabulário ficava sendo uma fotografia do raw puro: nenhuma entrada de Addon
   entrava, e por isso `esc_<especialização de addon>` e `tem_<habilidade de
   addon>` não eram declarados a zero.

   O efeito disso é exatamente o que o comentário acima avisa: expressão que cita
   identificador não declarado cai no fallback INTEIRA e calada. Uma
   Especialização de Addon (família ligada desde 2026-08-20) não conseguia
   escalar com o próprio nível, e ninguém via erro nenhum.

   O cache pela `epocaAddons()` existe porque a lista tem ~700 ids e o
   `deriveAfty` roda a cada tecla do criador. A época só troca quando o conjunto
   de addons troca, que é a mesma dependência que o `useMemo` do builder usa. */
let vocCache = null;
let vocEpoca = -1;

function vocabularioDoMundo() {
  const agora = epocaAddons();
  if (vocCache && vocEpoca === agora) return vocCache;
  vocEpoca = agora;
  vocCache = {
    pericias: [],
    resistencias: AFTY_RESISTENCIAS.map((r) => r.value),
    // `tem_*` cobre Habilidade, Talento E Aptidão: os Estilos de Combate leem
    // `tem_tal_adepto_de_combate` para saber se vieram pelo Talento, e o
    // Revestimento Evoluído (Maldição) lê `tem_mal_revestimento` para saber sobre
    // o que ele está melhorando. Os prefixos de id não colidem entre os três.
    habilidades: [
      ...AFTY_HABILIDADES.map((h) => h.id),
      ...AFTY_TALENTOS.map((t) => t.id),
      ...AFTY_APTIDOES.map((a) => a.id),
      /* E as Características Amaldiçoadas (2026-10-12): a Regeneração Vampírica
         Aprimorada do pacote Vampiro aumenta a cura de uma característica da
         origem, que a lê por `tem_<id>`. */
      ...AFTY_CARACTERISTICAS_AMALDICOADAS.map((c) => c.id),
    ],
    especializacoes: AFTY_ESPECIALIZACOES.map((e) => e.id),
    // Toda booleana de escolha de Aptidão que pode existir, para nenhuma
    // expressão que a cite cair no fallback por ela não estar declarada.
    opcoesAptidao: AFTY_APTIDOES.flatMap((a) =>
      (a.opcoes?.valores ?? []).map((v) => `opt_${normalizarVariavel(a.id)}_${normalizarVariavel(v.id)}`)),
  };
  return vocCache;
}

/** O Acerto que os ENCANTAMENTOS de uma Ferramenta somam, sem a parcela do grau. */
const acertoDosEncantamentos = (fa) =>
  (fa?.fontesAcerto ?? []).reduce((soma, f) => soma + (Number(f?.valor) || 0), 0);

/**
 * @param creature ficha (só escolhas)
 * @param opcoes   ajustes de JOGO, que o CRIADOR nunca passa:
 *   • almaAtual — Integridade da Alma CORRENTE. Ver a nota do `almaMult` abaixo.
 *   • ultimoFeiticoDanoId — última manifestação de dano usada na Ficha Final.
 *   • rituais — melhorias escolhidas para o próximo uso de cada Feitiço.
 *   • usosRitualista — melhorias adicionais gastas desde o último descanso.
 *   • ritualAtual — Ritual aguardando teste, escolha ou conclusão na Ficha Final.
 *   • rituaisSemTeste — mapa de Feitiços cuja fonte dispensa Prestidigitação.
 *
 * ⚠ O REMENDO DE ADDON É DA FICHA (achado M05-F01, 2026-10-07). A derivação roda
 * dentro do escopo da criatura: o catálogo vê os acréscimos do mundo inteiro e só
 * os remendos dos pacotes que ESTA ficha carrega. Sem isto, no Encontro misto, o
 * `substitui` de um combatente mudava o número do vizinho. Ver `comEscopoDaFicha`.
 */
export function deriveAfty(creature, opcoes = {}) {
  return comEscopoDaFicha(creature, () => deriveAftyNoEscopo(creature, opcoes));
}

function deriveAftyNoEscopo(creature, opcoes = {}) {
  creature = comArmaBloodfeast(creature, opcoes.bloodfeast);
  const core = creature?.core ?? {};
  /* CONCESSÃO VINDA DA SESSÃO (Addons 8.3). Chega pelo `opcoes`, e não pela
     criatura, porque ela é estado de SESSÃO e nunca ficha: o mestre dá no meio
     do combate, ela vale para tudo, não gasta vaga nenhuma e morre quando a
     sessão acaba (decisões do autor, 2026-08-20). Cada família recebe a parte
     dela pelo CANAL DE CONCESSÃO do resolvedor. Ver `afty-concessao.js`. */
  // Com as herdadas: a Imitação da herdeira do Restringido mora sob o id clonado.
  const imitacao = resolveImitacao(creature, expandeHerdadas([
    ...(creature?.habilidades ?? []),
    ...agrupaConcedido(opcoes.concedido).habilidades,
  ]));
  const concessoesComImitacao = [...(opcoes.concedido ?? []), ...concessaoImitada(imitacao)];
  const concedido = agrupaConcedido(opcoes.concedido);
  if (temBloodfeast(creature) && !concedido.talentos.includes("tal_robustez_aprimorada")) concedido.talentos.push("tal_robustez_aprimorada");
  // Os Talentos que uma etapa de treino concede (2026-10-09). Ver `talentosDeTreino`.
  for (const id of talentosDeTreino(creature)) if (!concedido.talentos.includes(id)) concedido.talentos.push(id);
  for (const c of concessaoImitada(imitacao)) {
    if (!(creature?.habilidades ?? []).includes(c.id) && !concedido.habilidades.includes(c.id)) {
      concedido.habilidades.push(c.id);
    }
  }
  const escolhasConcedidas = escolhasDoConcedido(concessoesComImitacao);
  /* A TÉCNICA INATA E O FUNDAMENTO (DA-07, 2026-09-30). Com o Fundamento morto, a
     Técnica Inata fica BLOQUEADA de verdade: os efeitos do Funcionamento e das
     Passivas saem do Motor, e cada Feitiço sai marcado como indisponível. Nada é
     apagado da ficha. Fora de campo, a mesa bloqueia também o Funcionamento e
     as Passivas (decisão do autor, 2026-10-03). O criador não tem esse estado. */
  const tecnicaInata = estadoDaTecnicaInata(creature, opcoes.invocacoes ?? null);
  // O Funcionamento principal sai como "tecnica", os outros como "funcionamento:<id>".
  const daTecnicaInata = (e) => /^(funcionamento|feitico):|^tecnica$/.test(String(e?.origem ?? ""));
  const semTecnicaBloqueada = (lista) => (tecnicaInata.bloqueada ? lista.filter((e) => !daTecnicaInata(e)) : lista);
  /* A EXAUSTÃO DE TÉCNICA da Expansão (DA-16, 2026-10-08) é TRAVA, e não aviso.
     Enquanto ela corre, cada Feitiço sai marcado indisponível (a Técnica Máxima
     junto), e os efeitos dos Feitiços saem do Motor: os Passivos e os
     Auxiliares ligados. Aptidões, armas, ações básicas e Habilidades seguem.

     ⚠ O FUNCIONAMENTO BÁSICO FICA. A DA-16 manda suprimir "passivos da Técnica
     quando identificáveis", e se o Funcionamento conta como um é NOVA DECISÃO
     NECESSÁRIA (`a-fazer.md`). Mesmo caminho da Técnica Inata acima, com outro
     motivo na tela. */
  const exaustaoTecnica = (() => {
    const restantes = Math.max(0, Math.trunc(Number(opcoes.exaustaoTecnica?.restantes) || 0));
    if (!restantes) return null;
    return {
      restantes,
      total: Math.max(restantes, Math.trunc(Number(opcoes.exaustaoTecnica?.total) || 0)),
      fonte: String(opcoes.exaustaoTecnica?.fonte ?? ""),
      motivo: `Técnica Inutilizável · ${restantes} ${restantes === 1 ? "Rodada" : "Rodadas"}`,
    };
  })();
  const doFeitico = (e) => /^(feitico|feiticoAuxiliar):/.test(String(e?.origem ?? ""));
  const semFeiticoExausto = (lista) => (exaustaoTecnica ? lista.filter((e) => !doFeitico(e)) : lista);
  const origensDiretasDaAdaptacao = new Set(origensDiretasDasAdaptacoes(creature, opcoes.adaptacoes));
  const aplicarDiretoDaAdaptacao = (efeito) => {
    if (!efeito?.quando || !origensDiretasDaAdaptacao.has(efeito.origem)) return efeito;
    const direto = { ...efeito };
    delete direto.quando;
    return direto;
  };
  /* O que os Addons DESTA criatura destravam. Leitura direta da ficha, sem
     passar pelo Motor: é pergunta estrutural ("esta criatura pode ter Estilo?")
     e precisa estar respondida antes de quase tudo. Ver `LIBERACOES`. */
  const liberacoes = liberacoesDaCriatura(creature);
  /* A CARTEIRA (Addon, 2026-09-08). O extrato é livro-caixa puro e não emite
     efeito nenhum: ele só soma o que a pessoa anotou. Quem muda regra são as
     duas liberações, uma para o orçamento de Focos e outra para o Nível.

     ⚠ ELE SOBE PARA CÁ, ANTES DE TUDO, por causa do Nível. O Nível é a primeira
     coisa que a derivação calcula e a entrada de quase toda fórmula do sistema,
     então o extrato precisa estar pronto antes dele. Ficava lá embaixo, junto
     do orçamento de Focos, enquanto os Focos eram a única regra que ele movia.

     ⚠ E ELE É CALCULADO MESMO SEM O ADDON, de propósito. O que o `permite`
     controla é quem ENXERGA a aba, e não se a ficha guarda o extrato: uma ficha
     que perdeu o addon não pode devolver zero e deixar a pessoa achar que as
     linhas dela sumiram. É a mesma razão de a concessão continuar valendo sem a
     primitiva permitida (ver `asserts/t-primitivas.mjs`). */
  const carteiraAlimentaFocos = liberacoes.includes("carteiraFocos");
  const carteiraAlimentaNivel = liberacoes.includes("carteiraNivel");
  const carteira = resolveCarteira(creature, {
    alimentaFocos: carteiraAlimentaFocos,
    alimentaNivel: carteiraAlimentaNivel,
  });
  const a = creature?.attributes ?? {};
  const ov = creature?.statOverrides ?? {};
  const catalogoPericiasFicha = catalogoPericiasDaFicha(creature);
  const vocabularioDsl = {
    ...vocabularioDoMundo(),
    pericias: catalogoPericiasFicha.map((p) => p.id),
    // As `estilo_tecnica_<id>` de toda Técnica da Expansão, ligada ou não (2026-10-11).
    zeros: variaveisDasTecnicas(creature),
  };

  /* ---------- CONDIÇÕES (2026-09-21) ----------
     Da SESSÃO na Ficha Final e no Encontro (`opcoes.condicoes`), e da bancada no
     criador (`combate.condicoes`). A Ficha troca o `combate` da ficha pelo da
     sessão, então a bancada nunca vaza para a mesa.

     ⚠ ELAS NÃO ACUMULAM ENTRE SI (autor, 2026-09-21: Paralisado e Desprevenido
     dão -10 de Defesa, e não -13). Quem decide o vencedor de cada número é o
     `resolveCondicoes`, e o Motor recebe só as linhas vencedoras. As perdedoras
     entram no hover, riscadas, logo depois do estágio da Guarda.

     Os alvos concretos saem daqui porque as perícias dependem da ficha: um Ofício
     repetido ou uma perícia personalizada também sofre o -2 do Envenenado. */
  const estadoBloodfeast = opcoes.bloodfeast ?? creature?.combate?.bloodfeast;
  const listaCondicoes = opcoes.condicoes ?? creature?.combate?.condicoes ?? [];
  const condicoes = resolveCondicoes(temBloodfeast(creature) && estadoBloodfeast?.agua
    ? [...listaCondicoes, { nome: "Exposto" }, { nome: "Abalado" }] : listaCondicoes, {
    pericias: catalogoPericiasFicha.map((p) => ({ id: p.id, nome: p.nome })),
    trs: AFTY_RESISTENCIAS.map((r) => ({ id: r.value, nome: r.label })),
    ataques: AFTY_ATAQUES.map((x) => ({ id: x.id, nome: x.nome })),
  });

  /* ⚠ O SISTEMA SAI DA FICHA, e não de parâmetro nem de rota. A mesma tela de
     encontro deriva criatura e personagem lado a lado, então uma global daria a
     resposta errada para metade da lista, calada. Ver afty-sistema.js. */
  const sistema = sistemaDaFicha(creature);
  const ehJogador = (id) => regraDo(sistema, id) === "player";
  /* O pool exclusivo se parte em GRUPOS no jogador (divergência `poolExclusivo`).
     O grupo é carimbado no efeito, nas duas listas que chegam à disputa: o
     `efeitosTodos` e o `efeitosAtivos`. Ver `carimbarGrupoExclusivo`. */
  const poolEmGrupos = ehJogador("poolExclusivo");

  const tipo = tipoDaFicha(creature);
  // ⚠ O RESTRINGIDO NÃO TEM ENERGIA AMALDIÇOADA (autor, 2026-07-29). É a
  // definição da origem ("nascem com uma quantidade quase nula de energia").
  // Mas o RECURSO É O MESMO (autor, 2026-07-29): Ponto de Estamina e Ponto de
  // Energia são ambos PE, mesma pilha e mesmo valor, só com nome diferente na
  // boca do Restringido. Toda habilidade que diz "gaste PE" ele paga em
  // Estamina. O que a falta de energia amaldiçoada tira é a parte de APTIDÃO:
  // nenhum Nível de Aptidão e nenhuma Aptidão Amaldiçoada.
  // Segue o TIPO, e não a origem, porque o Tipo é quem dirige toda fórmula e a
  // origem Restringido já o força.
  /* ⚠ NO JOGADOR NÃO HÁ TIPO, então quem responde "esta ficha tem energia
     amaldiçoada" é a Especialização Restringido. A trava Origem ↔ Especialização
     é bidirecional desde 2026-08-03, então as duas leituras dão o mesmo
     resultado na criatura, e no jogador só a segunda existe.

     ⚠ LÊ A MÃE DA CLASSE (2026-09-28): a herdeira do Restringido, que a
     variação da origem traz, também é sem energia. Ver `especializacaoMae`. */
  /* ⚠ E A ORIGEM PODE DIZER (2026-10-09, `semEnergia`). O Não-Feiticeiro das
     Regras Opcionais não tem Energia Amaldiçoada com classe nenhuma (Lutador,
     Suporte ou Combatente), e usa Estamina. Ver `origemSemEnergia`. */
  const semEnergiaDaOrigem = origemSemEnergia(creature);
  const semEnergia = semEnergiaDaOrigem || (ehJogador("pvPePorEspecializacao")
    ? (creature?.especializacoes ?? []).some((e) => especializacaoMae(e?.id) === "restringido")
    : tipo === "restringido");
  // Nome do recurso na UI. O número é o mesmo dos outros Tipos.
  const recursoLabel = semEnergia ? "Estamina" : "Energia";
  /* ⚠ O JOGADOR NÃO TEM PATAMAR (autor, 2026-08-31: "Não existe PATAMAR para
     Jogadores, isso é algo exclusivo de criaturas"). O aparo entra AQUI, na
     definição, e não em cada leitor, pela mesma razão do teto de nível logo
     abaixo: o campo continua no objeto da ficha (uma importação o traz junto), e
     quem tem de ignorá-lo é o motor.

     ⚠ Guardar leitor a leitor foi o que produziu o bug. O campo saiu da TELA em
     2026-08-30 e cinco pontos seguiram lendo `patamar`: a Guarda, a Resistência
     Parcial e o multiplicador de PV foram guardados um a um, e o CONTADOR DE
     HABILIDADES e o DANO foram esquecidos. Um jogador de nível 20 com
     `patamar: "beyond"` no JSON tinha contador 18 em vez de 12, e o dado do dano
     subia de d8 para d12. Com o aparo na origem, leitor novo nasce certo.

     "comum" é o valor NEUTRO das fórmulas, e não uma escolha: bônus de contador
     zero, multiplicador de PV 1, coeficiente de dano 2/1. Quem o autor pediu
     para não aparecer "nem como zero" é a Guarda, e ela segue devolvendo `null`
     pela divergência dela. */
  const patamar = ehJogador("patamarDoJogador") ? "comum" : (core.patamar || "comum");
  // nivelDaFicha aplica o teto padrão de 30 do Player. Um Addon pode retirá-lo
  // para esta ficha; todos os leitores de nível seguem a mesma decisão.
  /* ⚠ COM A LIBERAÇÃO, O NÍVEL VEM DO XP E O CAMPO DA FICHA É IGNORADO. É
     substituição e não soma, pela mesma razão do orçamento de Focos: somar o
     campo com a tabela cobraria a mesma experiência duas vezes. O `core.nd`
     continua gravado e intacto, para desinstalar o addon devolver o nível que a
     pessoa tinha digitado. Ver `CARTEIRA_XP_POR_NIVEL`.

     ⚠ E A PERGUNTA É FEITA PELO `nivelDaFicha`, e não escrita aqui, mesmo com o
     extrato já na mão duas linhas acima. Escrever a mesma decisão em dois
     lugares foi exatamente o defeito de 2026-09-08: a regra morava só aqui, e
     os catálogos, que leem a ficha direto, continuavam no campo cru. Um leitor
     só para a regra, e o derive é mais um cliente dele. */
  const ndBruto = nivelDaFicha(creature);
  /* O TETO DA ORIGEM (2026-10-09, `nivelMaximo`): "um Não-Feiticeiro não pode
     elevar seu nível acima do nível 10". Entra no mesmo `nd` que todo o resto
     lê, pela mesma razão do teto de 30 do jogador. */
  const tetoDaOrigem = nivelMaximoDaOrigem(creature);
  const ndSemOrigem = ndBruto;
  const nd = tetoDaOrigem ? Math.min(tetoDaOrigem, ndSemOrigem) : ndSemOrigem;
  /* As Habilidades que a origem CONCEDE (`concedeHabilidades`, 2026-10-09): entram
     pela mesma porta da concessão de sessão, sem gastar vaga e sem pedir a
     classe. A Percepção do Invisível dá o Perceber o Ar do Restringido. */
  for (const id of habilidadesConcedidasPelaOrigem(creature, nd)) {
    if (!(creature?.habilidades ?? []).includes(id) && !concedido.habilidades.includes(id)) concedido.habilidades.push(id);
  }
  // Especializações precisam existir antes das Aptidões e dos Feitiços: as
  // Bases automáticas dependem do nível da classe, duas Bases do Suporte
  // concedem Aptidões e Adiantar a Evolução antecipa o acesso de Conjurador.
  const especializacoes = resolveEspecializacoes(creature);
  const nivelConjurador = especializacoes.escolhidas
    .find((e) => e.id === "conjurador")?.nivel ?? 0;
  /* O TETO DE NÍVEL DE FEITIÇO da origem (2026-10-09, `tetoNivelFeitico`): o
     Não-Feiticeiro só adquire até o Nível 2 do Estilo e do Fundamento Marcial,
     que no Afty são os Feitiços Passivo e Personalizado do Estilo Marcial. */
  const tetoFeiticoOrigem = tetoNivelFeiticoDaOrigem(creature);
  const acessoFeitico = tetoFeiticoOrigem == null
    ? nivelMaxFeitico(nd, nivelConjurador)
    : Math.min(tetoFeiticoOrigem, nivelMaxFeitico(nd, nivelConjurador));
  const habilidadesConcedidas = habilidadesConcedidasPelasEspecializacoes(
    especializacoes.escolhidas, sistema, pacotesDaFicha(creature),
  );
  /* ⚠ ORIGEM ESTRUTURAL, e não a gravada. O Gêmeo que copiou da Maldição em
     Verdadeiras Origens perde a trilha de Energia Reversa como uma Maldição de
     verdade (autor, 2026-08-29). Ver `origemEstrutural` em afty-origens.js. */
  const trilhasOrigem = trilhasDaCriatura(creature);
  // ---------- Aptidões Amaldiçoadas EFETIVAS ----------
  // As escolhidas na aba mais as CONCEDIDAS POR NOME pela origem ou pela
  // Especialização. Fecha aqui em cima porque quase tudo lê esta lista: o
  // `coletarEfeitosAptidao`, a Expansão de Domínio, a Cura, a bancada, o
  // `tem_*` do DSL e a UI.
  //
  // ⚠ O Restringido zera as duas metades: sem energia amaldiçoada não há
  // aptidão nenhuma, nem escolhida nem concedida.
  const aptidoesConcedidasOrigem = semEnergia ? [] : aptidoesConcedidasPelaOrigem(creature, nd);
  // A origem Maldição não possui a trilha de Energia Reversa. A concessão do
  // Suporte respeita essa trava já estabelecida e não reabre a categoria.
  const podeReceberEnergiaReversa = trilhasOrigem.some((t) => t.key === "er");
  const aptidoesConcedidasEspecializacao = semEnergia || !podeReceberEnergiaReversa
    ? []
    : aptidoesConcedidasPelasHabilidades(habilidadesConcedidas);
  // ⚠ A CONCESSÃO DA SESSÃO (Addons 8.3) ENTRA AQUI, no mesmo caixa das que a
  // origem e as Habilidades já concediam: as três são "vale para tudo e não
  // gasta vaga". O `semEnergia` continua valendo por cima de todas, porque um
  // Restringido não tem Aptidão nenhuma, nem escolhida nem dada pelo mestre.
  /* ⚠ E A DO ADDON (2026-09-12), no mesmo caixa pelo mesmo motivo. Ela pode
     depender de um item EQUIPADO, e por isso o inventário é lido aqui em cima,
     cru, bem antes do `resolveEquipamentos`. Ver `aptidoesConcedidasPorAddon`. */
  const aptidoesConcedidasAddon = semEnergia
    ? []
    : aptidoesConcedidasPorAddon(creature, { equipados: itensEquipados(creature) });
  /* E a do TALENTO (2026-10-11, Desabrochar do Conhecimento Herdado), também no
     mesmo caixa. Lê a lista crua dos Talentos, escolhidos e concedidos, porque
     o `resolveTalentos` só roda lá embaixo. Ver `aptidoesConcedidasPorTalentos`. */
  const aptidoesConcedidasTalento = semEnergia
    ? []
    : aptidoesConcedidasPorTalentos([
      ...(Array.isArray(creature?.talentos) ? creature.talentos : []),
      ...concedido.talentos,
    ]);
  const substituicaoEnergiaReversa = substituicaoEnergiaReversaPorAddon(creature);
  const aptidaoPermitidaPelaEstrutura = (id) => (
    !substituicaoEnergiaReversa || getAptidao(id)?.categoria !== "energia_reversa"
  );
  const aptidoesConcedidas = semEnergia ? [] : [...new Set([
    ...(temBloodfeast(creature) && getAptidao(creature?.bloodfeast?.anatomia)?.subcategoria === "mal_anatomia" ? [creature.bloodfeast.anatomia] : []),
    ...aptidoesConcedidasOrigem,
    ...aptidoesConcedidasEspecializacao,
    ...concedido.aptidoes,
    ...aptidoesConcedidasAddon.map((c) => c.id),
    ...aptidoesConcedidasTalento.map((c) => c.id),
  ])].filter(aptidaoPermitidaPelaEstrutura);
  const aptidoesEscolhidasRaw = semEnergia || !Array.isArray(creature?.aptidoesAmaldicoadas)
    ? []
    : creature.aptidoesAmaldicoadas;
  /* A Aptidão que a origem VETA na escolha (`aptidoesVetadas`, o Domínio
     Simples do Legado do Guerreiro, 2026-10-11) sai da conta quando marcada à
     mão, e continua gravada. A concedida pelo nome passa, porque é o caminho
     que a regra deixa aberto ("ao aprender com alguém"). */
  const vetadasDaOrigem = new Set(aptidoesVetadasDaOrigem(creature));
  const aptidoesEscolhidasFicha = aptidoesEscolhidasRaw
    .filter(aptidaoPermitidaPelaEstrutura)
    .filter((id) => !vetadasDaOrigem.has(id));
  // A concedida NÃO duplica quando o jogador também a marcou à mão.
  const aptidoesIds = [...new Set([...aptidoesEscolhidasFicha, ...aptidoesConcedidas])];
  // A ficha que o resto do motor enxerga já vem com a concedida dentro, para
  // nenhum leitor precisar lembrar de somar as duas listas.
  const creatureComAptidoes = aptidoesConcedidas.length
    || aptidoesEscolhidasFicha.length !== aptidoesEscolhidasRaw.length
    ? { ...creature, aptidoesAmaldicoadas: aptidoesIds }
    : creature;
  // ⚠ A ficha do criador é sempre montada com a alma ÍNTEGRA (autor,
  // 2026-07-29): o campo "Integridade da Alma" saiu do formulário, porque o
  // Máximo da Alma já diz tudo, e dano na alma é coisa de jogo, não de criação.
  // Consequência: `almaMult` passou a seguir o MÁXIMO, então a Melhoria de Alma
  // e a Consciência Absoluta da Alma agora rendem PV de verdade (o multiplicador
  // era 1 fixo enquanto o campo ficava no 100 padrão).
  // O valor CORRENTE existe só no jogo, em `combatState.almaCurrent`.
  const almaMaxBase = creature?.alma?.max ?? 100;
  // A Alma que o DSL enxerga (`alma_atual`). No criador é o máximo, em jogo é o
  // corrente, e é o que faz um `quando: "alma_atual < 50"` significar algo. Sai
  // aqui em cima porque o contexto do DSL é montado bem antes de `almaMax`
  // existir (ele depende do canal, que depende do contexto).
  const almaAtualDsl = opcoes.almaAtual != null
    ? Math.max(0, Math.trunc(Number(opcoes.almaAtual) || 0))
    : almaMaxBase;
  // Contadores de Origem: SEMPRE presentes no contexto, nunca gated por
  // `combate.ativo` — é o que diferencia de um estado de bancada. Ver
  // afty-contadores-origem.js.
  const origemContadoresVars = origemContadoresDslVars(creature);
  const qntPE = creature?.qntPE || "normal";

  const attrBonus = resolveOrigemAttrBonus(creature);
  const nivelAlloc = creature?.attrNivel ?? {};
  const desenv = resolveDesenvolvimento(creature);
  /* ⚠ NO JOGADOR O PONTO DO DESENVOLVIMENTO VAI PARA OS PONTOS DE NÍVEL
     (divergência `desenvolvimentoNoNivel`, autor, 2026-10-01). O mapa gravado
     segue subindo o LIMITE nos dois sistemas, e só na criatura sobe também o
     valor. No jogador o valor vira ponto livre no contador, `attrNivelExtra`. */
  const desenvSoLimite = ehJogador("desenvolvimentoNoNivel") && origemTemDesenvolvimento(core?.origem?.id);
  const desenvValor = desenvSoLimite ? {} : desenv;
  const nivelExtraDesenv = desenvSoLimite ? desenvolvimentoTotal(nd) : 0;
  // Pool que sobe SÓ o limite (Maldição). Irmão do desenvolvimento, e por isso
  // NÃO entra no `eff` lá embaixo: ele abre espaço, quem preenche é o jogador
  // com os pontos distribuíveis da origem.
  const limPool = resolveLimitePoolOrigem(creature);
  // Equipamento primeiro: os acessórios de atributo entram no cálculo do
  // efetivo. A CARGA não sai daqui, porque depende do mod de Força final.
  // BT antecipado só para as Cargas de Encantamento das Ferramentas (= BT).
  const bt = maestria(nd);                                          // Maestria == Treinamento
  const regrasAddon = regrasAftyDaCriatura(creature);
  const regrasVotos = regrasAftyDeVotosAtivos(creature, bt);
  const passivasSemCustoPeMaximo = regrasAddon.passivasSemCustoPeMaximo
    || regrasVotos.passivasSemCustoPeMaximo;
  // ⚠ Os dois abaixo leem a ficha CRUA, e não os catálogos já resolvidos, e é
  // por causa desta ordem: o equipamento é o primeiro passo, e Treinamentos e
  // Habilidades só são resolvidos bem mais abaixo. Nenhum dos dois depende de
  // stat, então a leitura crua dá o mesmo resultado.
  //   • Completo do Treino de Manejo de Arma: uma vaga LIVRE de encantamento na
  //     arma treinada (não desce o grau de cálculo).
  //   • Manejo Especial (Combatente 6°): um encantamento CONCEDIDO a toda arma
  //     equipada, também sem custo de grau.
  /* O catálogo do Espinho sai AQUI, e não junto do resolver lá embaixo, porque
     os itens que ele marca viram Grau Especial, e o equipamento é o primeiro
     passo do derive. Sem o pacote a configuração é vazia e nada é marcado. */
  const configEspinho = espinhoDaFicha(creature);
  const equip = resolveEquipamentos(creature, bt, {
    vagasEncantamento: vagasEncantamentoDeTreino(creature),
    // As do ESCUDO (Treino de Escudo do pacote Stark, 2026-10-11).
    vagasEncantamentoEscudo: vagasEncantamentoEscudoDeTreino(creature),
    encantamentosExtras: encantamentosDeManejoEspecial(creature),
    encantamentosAdicionais: encantamentosAdicionaisDeTreino(creature, sistema),
    /* O sistema decide onde a RD do escudo desemboca: RD Geral na criatura, RD
       Física no jogador. Ver `canalRdEscudo` e a divergência `rdEscudoFisico`. */
    sistema,
    /* A segunda Habilidade Única e os Acessórios Únicos só valem com o Addon
       Benção do Grão Mestre da Forja. Sem a liberação, o que está gravado na
       ficha continua lá e deixa de contar. */
    liberacoes,
    /* Os itens marcados pelo Espinho (uid → aprimorado): viram Grau Especial, e
       o aprimorado ganha a Habilidade Única do Espinho. Ver afty-espinho.js. */
    espinho: marcasDoEspinho(creature, configEspinho),
    // O nome e a pele do pacote, para o selo e o rótulo da Habilidade Única
    // dizerem "Lanterna Coletora de Almas" quando é ela (2026-10-12).
    espinhoIdentidade: { nome: configEspinho.nome, artigo: configEspinho.artigo, visual: configEspinho.visual },
  });

  // Limite EFETIVO por atributo = limite base (20 / poderes) + Desenvolvimento, teto 30.
  // O RESTRINGIDO eleva o limite dos FÍSICOS para 30: "Seu limite de atributo
  // para Força, Destreza e Constituição é 30 ao invés de 20" (Ápice Corporal
  // Humano). Vale o MAIOR entre o da ficha, o da origem e o do Tipo, para um
  // limite subido à mão nunca ser rebaixado.
  //
  // ⚠ Vem dos DOIS lados de propósito. A origem Restringido força o Tipo
  // Restringido, mas o Tipo pode ser escolhido sozinho na aba Informações, e o
  // autor confirmou (2026-07-29) que o limite é do Restringido, não de um
  // caminho específico até ele.
  const limBase = (creature?.attrLimite && typeof creature.attrLimite === "object") ? creature.attrLimite : {};
  const atributosAddon = atributosDosAddons(creature);
  /* ⚠ A VARIAÇÃO DO RESTRINGIDO NÃO LEVA O LIMITE DO TIPO (autor, 2026-09-28,
     sobre a Restrição Intelectual: *"Só INT vai a 30"*). O 30 dos físicos é o
     conteúdo do Ápice Corporal Humano, e a variação herda a identidade, não o
     conteúdo: ela declara o próprio `limiteAtributo`. */
  const variacaoDoRestringido = ehVariacaoDoRestringido(core?.origem?.id ?? null);
  const limTipo = tipo === "restringido" && !variacaoDoRestringido
    ? { forca: ATTR_LIMITE_MAX, destreza: ATTR_LIMITE_MAX, constituicao: ATTR_LIMITE_MAX }
    : {};
  // ⚠ Recebe a CRIATURA, e não o id: o limite do Gêmeo depende da morte do
  // irmão. Ele precisa estar aqui, no estágio 0, porque é aqui que o bônus de
  // atributo da própria origem é aparado.
  const limOrigem = { ...limiteAtributoDaOrigem(creature), ...limTipo };
  // Limite de ESTÁGIO 0: o que a ALOCAÇÃO respeita (base, pool de nível e bônus
  // de origem). O limite FINAL sai mais abaixo, somando o canal `limiteAtributo`
  // do Motor, que só existe depois de os catálogos serem resolvidos.
  //
  // ⚠ O `limiteExtra` de Addon (Atributo Fang) entra DEPOIS do teto, e sobe o
  // teto junto: o texto dele diz que o +1 vale "até mesmo caso o Atributo já
  // esteja em 30". Por isso todo teto deste arquivo soma `tetoExtra(key)`.
  const tetoExtra = (key) => atributosAddon.limiteExtra(key);
  const limiteBaseOf = (key) =>
    Number.isFinite(atributosAddon.limite(key)) ? atributosAddon.limite(key) : Math.min(
      Math.max(limBase[key] ?? ATTR_LIMITE_PADRAO, limOrigem[key] ?? 0)
        + (desenv[key] || 0) + (limPool[key] || 0),
      ATTR_LIMITE_MAX,
    ) + tetoExtra(key);
  const limitesAtributoBase = Object.fromEntries(ATTR_KEYS.map((key) => [key, limiteBaseOf(key)]));

  // Atributo EFETIVO = base + nível + Desenvolvimento + bônus de origem.
  // Atributos de ORIGEM NÃO passam o limite (salvo os que digam explicitamente — TODO).
  // base+nível+Desenvolvimento já cabem no limite por construção (o Desenvolvimento
  // eleva valor E limite juntos); o bônus de origem é limitado ao limite efetivo.
  // Acessório de atributo (Anéis do Conhecimento, Bracelete da Força...) é o
  // único bônus que PASSA o limite: o texto deles diz "podendo superar o seu
  // limite de atributo, até o máximo de 30". Por isso ele entra depois do
  // clamp do limite, contra o teto duro de 30.
  //
  // ⚠ O excedente do acessório é GUARDADO (`folgaEquip`), e não só somado: o
  // clamp do estágio 1 precisa saber quanto daquele valor está legitimamente
  // acima do limite, senão ele apararia o acessório de volta ao aparar o Motor.
  const folgaEquip = {};
  // Ponto de bônus PERDIDO no limite, por atributo. A convenção do projeto é a
  // origem ter prioridade e o ponto de nível voltar ao pool (o `nivMax` do
  // builder reserva o espaço), então a parcela de estágio 0 normalmente é zero.
  // A do estágio 1 (Motor) não é: Pináculo Físico num Restringido de Força 30 não
  // tem para onde ir. O builder avisa em vez de esconder.
  const perdaNoLimite = {};
  /* A soma CRUA de estágio 0, guardada antes de qualquer aparo.

     Ela existe porque o limite deste estágio ainda não é o limite final: o canal
     `limiteAtributo` do Motor só aparece depois que os catálogos são resolvidos,
     e o que for cortado aqui precisa poder VOLTAR quando ele chegar. Ver
     `attrBaseFinal`, logo depois do `attrLimiteEfetivo`. */
  const somaCrua = {};
  const eff = (key) => {
    const somado = (a[key] ?? 10) + atributosAddon.bonus(key) + (nivelAlloc[key] || 0) + (desenvValor[key] || 0) + (attrBonus[key] || 0);
    somaCrua[key] = somado;
    const dentroDoLimite = Math.min(somado, limiteBaseOf(key));
    perdaNoLimite[key] = somado - dentroDoLimite;
    const comEquip = Math.min(dentroDoLimite + (equip.attrBonus[key] || 0), ATTR_LIMITE_MAX + tetoExtra(key), atributosAddon.limite(key));
    folgaEquip[key] = comEquip - dentroDoLimite;
    return comEquip;
  };

  // Atributo e modificador BASE: tudo menos os efeitos de habilidade. É o que
  // os pré-requisitos e as expressões do Motor leem, para uma habilidade que
  // concede atributo não morder a própria conta.
  const attrBase = {
    forca: eff("forca"), destreza: eff("destreza"), constituicao: eff("constituicao"),
    inteligencia: eff("inteligencia"), sabedoria: eff("sabedoria"), presenca: eff("presenca"),
  };
  const modBase = Object.fromEntries(Object.entries(attrBase).map(([k, v]) => [k, mod(v)]));

  // Mod. Técnica = modificador do atributo escolhido para a Técnica/CD
  const tecnicaAttr = core.tecnicaAttr || "inteligencia";

  const grau = grauFeiticeiro(nd);                                 // grau do feiticeiro por faixa de ND

  // ---------- ESTÁGIO 0: fontes A MONTANTE do contexto ----------
  // Treinamentos, Habilidades Gerais e os campos "+ OUTROS" da ficha foram
  // ABSORVIDOS pelo Motor em 2026-07-27 (decisão do autor): emitem
  // `{ canal, expr }` como qualquer outra fonte, em vez dos agregadores
  // paralelos que tinham. Entram ANTES de tudo porque concedem atributo, NÍVEL
  // DE APTIDÃO e VAGAS DE ORÇAMENTO, coisas lidas antes de os stats existirem.
  // Por isso rodam com um contexto reduzido (ND, Maestria, grau, patamar, tipo
  // e os atributos base), que é tudo de que as expressões deles precisam.
  /* ⚠ A ficha de jogador NÃO TEM Habilidades Gerais (autor, 2026-08-30), então
     ela resolve uma ficha vazia em vez de a ficha real. Não basta esconder a
     aba: as Gerais CONCEDEM (vaga de Especialização, vaga de Aptidão, Focos de
     Treinamento) e uma ficha que guardasse Gerais de um sistema anterior
     continuaria recebendo tudo isso, calada. */
  const gerais = ehJogador("habilidadesGerais")
    ? resolveGerais({ ...creature, habilidadesGerais: [] }, { nd, maestria: bt, concedidos: [] })
    : resolveGerais(creature, { nd, maestria: bt, concedidos: concedido.gerais });
  // A parcela de nível da Jogada de Ataque, na régua do sistema. É a mesma conta
  // do `escalaFixa` de `resolveTestes` (afty-pericias.js), para o DSL enxergar.
  const escalaAtaque = ehJogador("escalaDosTestes") ? Math.floor(nd / 2) : Math.floor(nd / 1.5);
  // ORIGEM entra no montante junto do resto: ela concede vaga de habilidade, de
  // perícia, de feitiço e de aptidão, e vaga é lida antes de os stats existirem.
  // As escolhas aninhadas dela (Treinamentos de Clã, Empenho Implacável) saem
  // primeiro porque carregam efeito próprio.
  const escolhasOrigem = resolveEscolhasOrigem(creature, nd);
  /* As OPÇÕES ESCOLHIDAS NA ORIGEM viram booleanas da DSL (2026-10-12),
     `opcao_<id>`: 1 a escolhida, 0 toda opção que a origem oferece. Nasceu com
     o Vampiro da Máscara de Pedra, em que a Patente Experiente deixa ignorar uma
     Fraqueza, e a linha da Vulnerabilidade à Luz precisa saber qual. Por isso a
     escolha sobe para antes do contexto do montante: ele também lê as opções. */
  const opcoesOrigemDsl = {
    todas: escolhasDaOrigem(creature).flatMap((e) => (e.opcoes ?? []).map((o) => o?.id).filter(Boolean)),
    escolhidas: Object.values(escolhasOrigem.mapa ?? {}).flat(),
  };
  const ctxMontante = buildCriaturaDslContext({
    nd, bt, escalaAtaque, grauRank: grau.rank, patamar, tipo, almaAtual: almaAtualDsl,
    nivelFeiticoMax: acessoFeitico,
    origemContadoresVars,
    opcoesOrigem: opcoesOrigemDsl,
    irmaoMorto: !!creature?.core?.origem?.irmaoMorto,
    iniciativaIrmao: creature?.core?.origem?.iniciativaIrmao,
    attrEff: attrBase, mods: modBase, modTecnica: modBase[tecnicaAttr] ?? 0, tecnicaAttr,
    periciasProf: creature?.pericias,
    /* O escudo na mão já é conhecido aqui (o equipamento é o primeiro passo do
       derive), e o Treino de Escudo do pacote Stark lê `escudo_equipado` numa
       etapa, que roda neste estágio. Sem ele a variável valia zero e a Defesa
       nunca entrava (2026-10-11). */
    escudoEquipado: equip.entradas.some((e) => e.tipo === "escudo" && e.equipado),
    // O vocabulário entra AQUI TAMBÉM: o contexto reduzido não tem `esc_*` nem
    // `tem_*`, e sem eles declarados uma expressão que os citasse cairia inteira
    // no fallback, calada. Origem não escala com classe, então zero é a resposta
    // certa — mas ela precisa ser dada, não silenciada.
    vocabulario: vocabularioDsl,
    /* ⚠ SEM `marcas`, e é de propósito: o montante roda ANTES de Habilidades,
       Talentos e Aptidões serem resolvidos, então não há o que contar. O
       `contar()` devolve 0 aqui, do mesmo jeito que `tem_*` vale 0. */
  });
  // Nenhuma das cinco fontes do pool exclusivo alimenta o montante (elas dão
  // stat, não orçamento), mas a resolução entra aqui do mesmo jeito: sem ela um
  // exclusivo que aparecesse por engano sairia da soma e nunca voltaria.
  /* A lista do montante fica NOMEADA porque ela é lida duas vezes: aqui, no
     estágio 0, e no estágio 0c lá embaixo, que precisa dos mesmos efeitos com o
     Nível de Aptidão já no contexto. Ver `CANAIS_POS_APTIDAO`. */
  /* LOJA DE CATARSE (Addon, 2026-09-04). Resolvida ANTES do estágio 0 porque o
     que ela emite é vaga de orçamento, e vaga é lida antes de os stats
     existirem. Ver `resolveCatarse`. */
  const catarse = resolveCatarse(creature, { precos: precosDeCatarse(creature) });
  /* ESPINHO (Addon, 2026-09-30). Irmão da Catarse, e resolvido no mesmo ponto
     pelo mesmo motivo: o que ele emite é vaga de orçamento. O teto de cada item
     é DSL (`bt`, `bt / 2`) e por isso lê o contexto do montante, que já tem o
     BT e o ND. O inventário vai junto só para dar nome ao item marcado e achar
     o que sumiu. Ver `resolveEspinho`. */
  const espinho = resolveEspinho(creature, {
    config: configEspinho,
    // O `extra` é a Maestria anotada da Lanterna, que troca o `bt` só no teto.
    avaliar: (expr, extra) => evalNumberDsl(expr, extra ? { ...ctxMontante, ...extra } : ctxMontante, 0),
    inventario: (equip.entradas ?? [])
      .filter((x) => ESPINHO_TIPOS_ITEM.includes(x.tipo))
      .map((x) => ({ uid: x.uid, nome: x.def?.nome ?? x.refId, tipo: x.tipo })),
  });
  /* ⚠ O VISLUMBRE CELESTE É DE GRAÇA e não tem entrada de catálogo: quem tem o
     pacote tem os olhos. Por isso o portão é a primitiva, e ele é lido aqui em
     cima, antes do montante: a Compreensão do Jujutsu emite `pontosAptidao`, que
     é orçamento e é lido antes de os stats existirem. */
  const temVislumbre = primitivasDaCriatura(creature).includes("vislumbreCeleste");
  const temOlhinhosLu = primitivasDaCriatura(creature).includes("olhinhosLu");
  const olhosLu = estadoOlhinhosLu(creature);
  const efeitosOlhinhosLu = efeitosDosOlhinhosLu({ tem: temOlhinhosLu, ...olhosLu });
  /* ⚠ O ESTADO SAI DA CRIATURA CRUA, e não do `combate` resolvido, porque este
     bloco roda ANTES dele: os efeitos daqui são lidos no montante e no passe
     pós-aptidão, e a bancada de combate só nasce umas 600 linhas abaixo. É a
     mesma fonte, com o mesmo portão do `ativo`. Ver `olhosDescobertos`. */
  const vislumbreDescoberto = olhosDescobertos(creature);
  const efeitosVislumbre = efeitosDoVislumbre({
    tem: temVislumbre,
    descoberto: vislumbreDescoberto,
  });
  const olhosAgulha = resolveOlhosAgulha(creature, {
    tem: primitivasDaCriatura(creature).includes("olhosDeAgulha"),
    bt, nivelMax: acessoFeitico,
  });
  const efeitosAgulha = efeitosOlhosAgulha(olhosAgulha);

  /* ⚠ O QUE LÊ A BANCADA DESCE AO ESTÁGIO PRINCIPAL (autor, 2026-10-03). O
     `ctxMontante` não tem Simulação de Combate, e um `quando: "em_combate"` aqui
     valia zero com "Em Combate" ligado ou não: a Atenção do Instinto Sanguinário
     nunca somou. A regra vale para a lista inteira, e quem desce entra no
     `efeitosTodos` lá embaixo, UMA vez. Ver `separarEfeitosDeBancada`. */
  const { montante: efeitosMontante, bancada: efeitosMontanteDeBancada } = separarEfeitosDeBancada([
      // Vagas exclusivas de Talento, configuradas na cópia do Addon desta ficha.
      ...regrasAddon.fontesTalentosIniciais.map(({ id, nome, valor }) => ({
        canal: "vagasTalento", expr: String(valor), origem: id, nome,
      })),
      ...efeitosDeTreino(creature, opcoes.treinosAtivos, equip.entradas),
      ...efeitosRdEquipamentoDeTreino(creature, equip, bt, sistema),
      // Treino Especial entra ao lado da Linha de Treinamento porque é a mesma
      // família (Interlúdio) e emite a mesma classe de coisa: VAGA de orçamento,
      // lida antes de os stats existirem. Hoje só `vagasFeitico`.
      ...efeitosDeTreinoEspecial(creature, concedido.treinosEspeciais),
      ...coletarEfeitosOrigem(creature, escolhasOrigem, opcoes.treinosAtivos),
      ...coletarEfeitosMontante(creature, gerais, GERAL_BY_ID),
      /* ⚠ A LOJA DE CATARSE ENTRA NO MONTANTE, e não no estágio 2, porque o que
         ela emite é VAGA de orçamento: `vagasTalento`, `vagasHabilidade`,
         `vagasMelhoria` e companhia são lidas antes de os stats existirem, e um
         canal lido depois chegaria com o orçamento já fechado.

         ⚠ O TEXTO LIVRE VEM JUNTO, e ele pode emitir QUALQUER canal (é o Motor
         inteiro na mão do jogador). O `efMontante` é mesclado no agregado final,
         então um `danoBonus` escrito ali chega no lugar certo do mesmo jeito que
         os canais comuns da origem chegam. Ver a nota do `coletarEfeitosOrigem`.

         ⚠ E NENHUMA LINHA LEVA `exclusivo`: acumular com Técnica é a regra que
         o autor pediu. Ver o cabeçalho de afty-catarse.js. */
      ...catarse.efeitos,
      /* ⚠ O ESPINHO ENTRA NO MONTANTE pela mesma razão da Catarse: vaga de
         Talento, de Especialização e de Alto Nível fecha antes de os stats
         existirem. Sem `exclusivo` em linha nenhuma: acumular é a regra. */
      ...espinho.efeitos,
      /* Só a Compreensão do Jujutsu, que é VAGA e por isso é montante. Os dois
         blocos de benefício leem `cl` e um estado de combate, e nenhum dos dois
         existe ainda aqui: eles entram no bolo comum, mais abaixo. */
      ...efeitosVislumbre.filter((e) => e.canal === "pontosAptidao"),
      /* Votos Mecânicos emitem qualquer canal pelo mesmo Motor das outras
         fontes de texto livre. A quantidade ativa é o BT, e nenhuma linha
         leva `exclusivo`, então Benefícios e Malefícios acumulam normalmente.
         Ver afty-votos.js. */
      ...efeitosDeVotos(creature, bt),
      /* Modificações Corporais também não
         leva `exclusivo` em nenhuma linha — "capaz de acumular com
         Habilidades" é a regra que o autor pediu. Ver
         afty-modificacoes-corporais.js. */
      ...efeitosDeModificacoesCorporais(creature),
  ], ctxMontante);
  const efMontante = resolverExclusivos(aplicarEfeitos(efeitosMontante, ctxMontante));
  // Os canais que precisam ser lidos ANTES do contexto principal: dois
  // alimentam resolveNiveisAptidao (nível de aptidão é variável do DSL) e um
  // alimenta o orçamento de Habilidades de Especialização. O resto (hp, pe,
  // movimento, defesa, atributo, focos, vagas de perícia e de aptidão) entra
  // pelo caminho normal do Motor, mais abaixo.
  const treino = {
    aptidao: valorCanal(efMontante, "pontosAptidao"),
    aptidaoTrilha: efMontante.porAlvo.nivelAptidao || {},
  };
  /* ⚠ No jogador o nível de Classe é que dá a vaga, 1 a partir do SEGUNDO de
     cada uma. O canal continua somando por cima nos dois: ele é como o Talento
     Natural e os Addons dão vaga, e nada disso passa pela Habilidade Geral. */
  const vagasHabilidadePorClasse = ehJogador("vagasPorNivelDeClasse")
    ? vagasDeHabilidadePorClasse(especializacoes.escolhidas)
    : 0;
  const vagasHabilidade = valorCanal(efMontante, "vagasHabilidade") + vagasHabilidadePorClasse;
  // Vaga EXCLUSIVA de Talento (autor, 2026-08-03): o Talento Natural do Inato
  // dava vaga COMUM, e assim uma característica que o livro escreve como "um
  // Talento à escolha" pagava Habilidade de Especialização qualquer.
  const vagasTalento = valorCanal(efMontante, "vagasTalento");

  // ============================================================
  // CATÁLOGOS ESCOLHIDOS + MOTOR DE AUTOMAÇÃO
  // ============================================================
  // Resolvidos AQUI, antes dos stats, e não mais perto do fim: é o que permite
  // um efeito de habilidade alcançar HP, Defesa, CD e companhia. Nenhum destes
  // precisa de stat, só de ND, Maestria, atributos e origem.
  //
  // ⚠ Os atributos usados no pré-requisito são os BASE (attrEff, sem efeito
  // nenhum de habilidade). Sem essa regra, habilidade que concede atributo
  // morde a própria conta. Ver o topo de afty-efeitos.js.

  // ⚠ Os níveis de aptidão saem MAIS ABAIXO, depois das Habilidades: elas
  // também concedem trilha (Aptidões de Luta, Aptidões de Combate), e a
  // concessão precisa entrar antes de `dom/au/cl/bar/er` virarem variável.

  // Especializações não entram diretamente em nenhum stat (quem dirige
  // fórmula é o Tipo). Foram resolvidas no início porque agora também concedem
  // três Bases do Suporte pelo nível.

  // Talentos dividem o orçamento das Habilidades de Especialização, então saem
  // antes. O acesso deles lê ND, origem e atributos, nunca nível de classe.
  // ⚠ Este é um resolve PRELIMINAR: os ids e o gasto já são definitivos, mas o
  // `inacessiveis` é refeito mais abaixo, com o atributo já somado dos efeitos
  // PERMANENTES. Talento é o único catálogo cujo pré-requisito lê atributo.
  const origemId = creature?.core?.origem?.id ?? null;
  // Mais de uma quando o Gêmeo copia uma origem em Verdadeiras Origens.
  const origensQuali = origensQualificadas(creature);
  /* Os Talentos que chegam sem gastar vaga: os da sessão (Concessão do Mestre) e
     os que o Espinho concede pelo nome (o Determinado a Viver Adicional). O
     caminho é o mesmo, e a semântica também: não gasta vaga e não cobra
     pré-requisito. A diferença é só a fonte, e a do Espinho é FICHA. */
  const talentosConcedidos = [...(concedido.talentos ?? []), ...espinho.talentosConcedidos];
  const talentosPre = resolveTalentos(creature, {
    nd, maestria: bt, attrEff: attrBase, origemId, origensQualificadas: origensQuali,
    claId: creature?.core?.origem?.cla ?? null,
    especializacoes: especializacoes.escolhidas, aptidoes: aptidoesIds,
    feiticos: creature?.feiticos,
    limitesAtributo: limitesAtributoBase,
    concedidos: talentosConcedidos,
  });
  /* ============================================================ */
  /* UM TALENTO QUE CONCEDE VAGA DE TALENTO                        */
  /* ============================================================ */
  /* ⚠ ISSO NÃO PASSA PELO MONTANTE, e o efeito era emitido e jogado fora.
     O `efMontante` cobre Habilidade Geral e efeito manual da ficha, e um
     Talento não cabe lá: ele é escolhido depois, e o número de vagas já estava
     fechado quando o efeito dele aparecia no agregado final. Resultado: um
     Talento com `{ canal: "vagasTalento" }` aparecia certinho no hover de
     fontes e não mudava o orçamento em nada.

     O lugar certo é AQUI, entre o `talentosPre` (que diz quais Talentos a ficha
     tem) e o `resolveHabilidades` (que fecha o orçamento). Não há ciclo: o
     `resolveTalentos` não precisa do número de vagas para listar o que foi
     escolhido, e quem cobra o excedente é o `resolveHabilidades`.

     O primeiro caso é o Addon das Dez Sombras: as duas Mecânicas Únicas são
     Talentos que pagam a própria vaga, para saírem de graça sem virarem uma
     origem própria (autor, 2026-09-02). */
  const vagasTalentoDeTalento = valorCanal(
    resolverExclusivos(aplicarEfeitos(
      coletarEfeitos(talentosPre.escolhidas, TALENTO_EFEITOS, getTalento, talentosPre.vezes),
      ctxMontante,
    )),
    "vagasTalento",
  );
  const vagasTalentoTotal = vagasTalento + vagasTalentoDeTalento;

  /* ⚠ NO JOGADOR SÓ A CLASSE INICIAL TREINA ARMA E ESCUDO (divergência
     `treinoDaClasseInicial`, 2026-09-23): "Ao obter uma nova especialização, você
     não recebe novos treinamentos em perícias nem equipamentos". A inicial é a
     primeira da lista, a mesma régua do PV e do pacote de perícias. */
  const classesDoTreino = ehJogador("treinoDaClasseInicial")
    ? especializacoes.escolhidas.slice(0, 1)
    : especializacoes.escolhidas;
  const treinamentosEquipamento = treinamentosDasEspecializacoes(classesDoTreino);
  const treinoEscudo = resolveTreinoEscudo(classesDoTreino, talentosPre.escolhidas);
  // bt entra por causa do Roubo de Habilidade, cujo limite de repetições é o
  // Bônus de Treinamento. O último parâmetro são as vagas extras da Habilidade
  // Geral Especialização.
  const habilidades = resolveHabilidades(
    creature, especializacoes.escolhidas, talentosPre.gastos, bt, vagasHabilidade, vagasTalentoTotal,
    {
      nd,
      almaLivreEspecializacao: talentosPre.almaLivreEspecializacao,
      almaLivreNivelAjuste: getTalento("tal_alma_livre")?.nivelAlmaLivreAjuste ?? 0,
      concedidasSessao: concedido.habilidades,
      concedidasTreino: habilidadesConcedidasPorTreino(creature),
      vetadas: habilidadesVetadasPelaOrigem(creature),
      escolhasConcedidasSessao: escolhasConcedidas,
      imitadas: concessaoImitada(imitacao).map((c) => c.id),
      niveisHabilidadesConcedidas: imitacao.copia ? Object.fromEntries(concessaoImitada(imitacao).map((c) => [c.id, nd])) : {},
      // Vaga a mais numa escolha aninhada (Potencial Físico 4ª). Refecha no fim.
      vagasEscolha: efMontante.porAlvo.vagasEscolha || {},
      sistema,
    },
  );
  // Alto Nível (21+). Além do ND, cada trilha exige a Habilidade Geral
  // correspondente, que só DESTRAVA (não dá vaga).
  // Conhecimento Iluminado só promove perícias treinadas por outra fonte.
  const configuracaoEspecializacao = resolveConfiguracaoEspecializacao(creature, habilidades, expandeHerdadas(habilidades.efetivas));
  const profsAntesDoAltoNivel = resolverExclusivos(aplicarEfeitos([
    ...configuracaoEspecializacao.efeitos,
    ...efeitosMontante,
    ...coletarEfeitosCriatura({
      habilidades, talentos: talentosPre, sistema,
      catalogos: { habilidades: getHabilidade, talentos: getTalento, opcoes: { ...OPCAO_ESCOLHA_NOME, ...OPCAO_TALENTO_NOME } },
    }),
    ...coletarEfeitosAptidao(creatureComAptidoes, semEnergia),
    ...efeitosDaTecnica(creature),
  ].filter((e) => e.canal === "proficienciaPericia"), ctxMontante));
  const periciasTreinadasAntes = Object.keys(profsAntesDoAltoNivel.porAlvo.proficienciaPericia || {})
    .filter((id) => valorCanal(profsAntesDoAltoNivel, "proficienciaPericia", id) >= 1);
  const altoNivel = resolveAltoNivel(creature, {
    periciasTreinadas: periciasTreinadasAntes,
    niveisPorEspec: habilidades.niveisPorEspec,
    habilidades: habilidades.efetivas,
    /* ⚠ `undefined` no jogador, e não um objeto com os dois em `true`. O
       `avaliarAcessoAltoNivel` já lê a AUSÊNCIA como "os dois abertos", e passar
       um objeto seria dizer a mesma coisa por um caminho a mais. As duas trilhas
       ficam só com o ND 21 e 22, que é a regra do autor. */
    destravado: ehJogador("altoNivelSemGeral") ? undefined : gerais.destravado,
    concedidos: {
      melhoriasSuperiores: concedido.melhoriasSuperiores,
      lendarias: concedido.lendarias,
    },
    /* Vagas de Alto Nível vindas do Motor (Loja de Catarse, Addon, Habilidade).
       Leem o estágio MONTANTE pelo mesmo motivo que `vagasHabilidade` e
       `vagasTalento`: o orçamento fecha aqui, antes de as escolhas serem
       resolvidas, então um canal lido depois chegaria tarde. Foi exatamente o
       defeito do `vagasTalento` de Talento, consertado em 2026-09-02. */
    vagasMelhoria: valorCanal(efMontante, "vagasMelhoria"),
    vagasLendaria: valorCanal(efMontante, "vagasLendaria"),
  });
  /* ⚠ A VAGA DE ALTO NÍVEL COMPRADA CEDO É ALMA GASTA SEM USO, e o card avisa.
     A compra abre a vaga (regra da Catarse), mas a Melhoria continua pedindo o
     Nível 21, e na criatura também a Habilidade Geral. O aviso sai daqui, e não
     do afty-espinho, porque só o derive sabe o nível e o portão. Ele lê o CANAL
     do item, e não o id, para valer a qualquer item de pacote que abra a vaga. */
  const avisosEspinho = [...espinho.avisos];
  for (const trilha of [
    { canal: "vagasMelhoria", nivel: MELHORIA_NIVEL_INICIAL, chave: "melhorias", geral: "Melhoria Superior" },
    { canal: "vagasLendaria", nivel: LENDARIA_NIVEL_INICIAL, chave: "lendarias", geral: "Habilidade Lendária" },
  ]) {
    for (const item of espinho.itens) {
      if (item.qtd <= 0 || !item.efeitos.some((e) => e.canal === trilha.canal)) continue;
      if (nd < trilha.nivel) {
        avisosEspinho.push(`${item.nome}: requer ${rotuloDoNivel(sistema)} ${trilha.nivel}.`);
      } else if (!ehJogador("altoNivelSemGeral") && !gerais.destravado?.[trilha.chave]) {
        avisosEspinho.push(`${item.nome}: requer a Habilidade Geral ${trilha.geral}.`);
      }
    }
  }

  // Nível por especialização para o DSL: real (trava pré-requisito) e de
  // escalonamento (real + metade da outra classe, o que os efeitos escalam).
  const nivelEspec = {};
  for (const e of especializacoes.escolhidas) {
    const valor = { real: e.nivel ?? 0, escalonamento: e.nivelEscalonamento ?? e.nivel ?? 0 };
    nivelEspec[e.id] = valor;
    /* ⚠ A HERDEIRA RESPONDE TAMBÉM PELO NOME DA MÃE (2026-09-07). É a outra
       metade da herança de Especialização: as habilidades clonadas trazem as
       expressões do livro intactas, e elas citam `esc_conjurador`. Publicar o
       nível sob os dois nomes resolve as 21 expressões de uma vez, sem busca e
       troca em texto de DSL.

       Não colide com a mãe de verdade porque as duas não podem conviver na
       mesma ficha (`incompativeisIds`), e o `??=` deixa a própria mãe vencer
       caso um dia possam. */
    const mae = getEspecializacao(e.id)?.herdaDe;
    if (mae && !nivelEspec[mae]) nivelEspec[mae] = valor;
  }
  if (habilidades.almaLivre?.habilidadeId) {
    nivelEspec[habilidades.almaLivre.especializacaoId] = {
      real: habilidades.almaLivre.nivel,
      escalonamento: habilidades.almaLivre.nivel,
    };
  }

  // Efeitos de ficha das entradas escolhidas. O catálogo de efeitos ainda está
  // VAZIO (Fase 0 é só a infraestrutura): a passada de conteúdo é a Fase 2/3 de
  // docs/afty-efeitos-criatura.md.
  // ⚠ TRÊS ESTÁGIOS (autor, 2026-07-27). O efeito de ATRIBUTO entra primeiro e
  // todo o resto lê o atributo já somado ("Tenho força 14. Recebo +6 de Força
  // fico com Força 20. Depois eu recebo +5 de Defesa (Mod. Força)"), e o
  // atributo se parte em permanente e temporário porque só o PERMANENTE conta
  // para pré-requisito ("Se o Modificador de Força for temporário, não! Se for
  // permanente, sim!"). Ver o topo de afty-efeitos.js.
  // Armas carregadas e as Dedicadas (Lutador 2°). Sobem para cá porque a
  // dedicação EMITE efeito (nível de dano e a propriedade Marcial), e efeito
  // tem de entrar no mesmo bolo dos outros, antes dos estágios.
  //
  // ⚠ É "arma EQUIPADA" desde 2026-08-01, quando a arma ganhou botão de equipar
  // na aba Equipamentos. Antes era toda arma CARREGADA, porque não havia como
  // equipar uma. Com o Acerto por grau entrando na linha, carregar uma arma na
  // mochila não pode mais render número.
  const armasCarregadas = equip.entradas.filter((e) => e.tipo === "arma" && e.equipado);
  // Grau de CÁLCULO da Ferramenta: cada encantamento desce um degrau, e o rank 0
  // não é grau nenhum (vira "desarmado" na tabela de dano adicional).
  const grauCalcDaArma = (e) => (e.fa ? (grauDoRank(e.fa.rankCalculo)?.value ?? null) : null);
  // Faixas e Manoplas (grupo pugilato) não viram linha: são o Ataque Básico.
  const armasParaDano = armasCarregadas
    .filter((e) => e.def?.grupo !== "pugilato")
    .map((e) => ({
      id: e.def.id,
      nome: e.def.nome,
      grauArma: grauCalcDaArma(e),
      /* O dado impresso da arma, que só a ficha de jogador usa. Versátil ("o
         `/` da tabela") escolhe pelo MANEJO gravado na ficha: sem a marca, vale
         a de uma mão, que é a coluna da esquerda.

         ⚠ A TABELA TEM TRÊS FORMAS DE DANO, e a terceira quase passou batido. O
         Chicote Espinhento e a Kusarigama trazem `dano.dados` em ARRAY, que são
         dois dados de TIPOS diferentes (o "1d6/1d6" da tabela que não é
         versátil). Elas não têm `dano.dado`, então caíam no `1d3` do desarmado,
         caladas: o dano certo é a soma dos dois. Os TIPOS seguem só no texto
         especial da arma, como já seguiam antes desta mudança. */
      usarDadoArma: !!e.def.usarDadoArma,
      dadoArma: Array.isArray(e.def.dano?.dados)
        ? e.def.dano.dados.map((d) => d.dado).filter(Boolean).join(" + ")
        : ((e.duasMaos && e.def.dano?.duasMaos) ? e.def.dano.duasMaos : (e.def.dano?.dado ?? null)),
      versatil: !!(e.def.props?.versatil && e.def.dano?.duasMaos),
      duasMaos: !!e.duasMaos,
      // Acerto DESTA arma: +1 por grau da Ferramenta mais o que o encantamento
      // Precisa somar (autor, 2026-08-01). Fica na linha e não no Ataque da
      // categoria, senão o bônus vazaria para as outras armas.
      /* ⚠ O GRAU NÃO DÁ ACERTO NA FICHA DE JOGADOR (autor, 2026-08-31: "Grau da
         Arma não fornece +Acerto ou +Dano para Jogador. Só fornece os Bônus de
         Encantamentos como Potente que aumenta em 1 Dado"). O que sai é só a
         parcela do GRAU: as `fontesAcerto` continuam, porque elas são o
         encantamento Precisa, e encantamento vale nos dois sistemas. */
      /* ⚠ E O ZERO LEVAVA O ENCANTAMENTO JUNTO até 2026-09-12. O `acertoArma`
         da Ferramenta é o grau MAIS o Precisa, e zerar o campo inteiro tirava
         os dois do total, enquanto as `fontesAcerto` seguiam no hover. O hover
         então montava "Grau da Ferramenta −2" e "Precisa +2", que se anulavam, e
         o autor perguntou o que era aquele −2. No jogador sai só o grau. */
      acertoGrau: ehJogador("danoPorArma") ? acertoDosEncantamentos(e.fa) : (e.fa?.acertoArma ?? 0),
      fontesAcerto: e.fa?.fontesAcerto ?? [],
      ataqueId: e.ataqueId,
      fineza: !!e.def.props?.fineza,
      critico: e.def.critico ?? 20,
      distancia: e.def.categoria === "distancia" || e.def.categoria === "arremesso",
      /* ⚠ A CLASSE TREINA ESTA ARMA? Só a ficha de jogador usa, e é o que faz o
         Bônus de Treinamento entrar por ARMA em vez de por tipo de ataque:
         "Lutador tem Treinamento em Armas Simples. Logo, sempre que usando uma
         Arma Simples ele é considerado como Treinado" (autor, 2026-08-30).
         Arma fora do treino continua utilizável e só não soma o BT. */
      atributoAtaque: e.def.atributoAtaque,
      treinada: !!e.def.treinadaPadrao || armaTreinadaPor(e.def, treinamentosEquipamento.armas)
        || (
          talentosPre.escolhidas.includes("tal_mestre_das_armas")
          && creature?.talentosConfig?.tal_mestre_das_armas?.modo === "armas"
          && (creature?.talentosConfig?.tal_mestre_das_armas?.armas ?? []).includes(e.def.id)
        ),
      // Categoria e grupo alimentam os escopos de alvo (`cat:arremesso`,
      // `grupo:espada`), que é como o Combatente mira classes de arma inteiras.
      categoria: e.def.categoria ?? null,
      grupo: e.def.grupo ?? null,
      // Tipo de dano da arma (ct, im, pf), que é como os Especialistas em
      // Cortes, Concussão e Perfuração (Talentos) miram.
      tipoDano: tipoDanoDaArma(e.def, e.uid ?? e.def.id, opcoes.propriedadesArmas),
      tipoDanoBase: e.def.dano?.tipo ?? null,
      alcance: alcanceDaArma(e.def, bt, e.fa?.grau ?? null),
      alcanceBonusCorpo: e.def.props?.estendida ? 1.5 : 0,
      propriedades: propriedadesDaArma(e.def, e.fa),
      chaveArma: e.uid ?? e.def.id,
      avisosPropriedades: e.def.avisosPropriedades ?? [],
      criticoExtraDados: e.fa?.encantamentos?.some((x) => x.id === "enc_arma_destruidora" && x.atende) ? 1 : 0,
      elegivelDedicada: podeSerArmaDedicada(e.def),
    }));
  const tecnicasCombate = resolveTecnicasCombate(
    creature,
    catalogoDoTipo("arma", creature),
    habilidades.efetivas,
  );
  // O Ataque Básico só sobe de grau com Manoplas ou Faixas (autor, 2026-07-27).
  // Sem elas é Desarmado, que não soma nada. Com as duas vale o grau mais alto,
  // e é o grau de CÁLCULO que compara, porque é ele que vira número.
  //
  // ⚠ UM item define o Ataque Básico, e não a soma deles (2026-08-20). O grau
  // sempre foi o maior, e agora o resto do item (encantamento, Fineza) vem do
  // MESMO item, porque somar dois pares de Manoplas empilharia encantamento de
  // duas armas num golpe só. Item sem Ferramenta entra na disputa com rank 0:
  // ele não muda grau nenhum, mas pode receber encantamento do Manejo Especial,
  // que vale para toda arma manejada.
  const pugilato = armasCarregadas
    .filter((e) => e.def?.grupo === "pugilato")
    .sort((x, y) => ((y.fa?.rankCalculo ?? 0) - (x.fa?.rankCalculo ?? 0))
      || ((y.fa ? 1 : 0) - (x.fa ? 1 : 0)))[0] ?? null;
  const grauBasico = pugilato ? grauCalcDaArma(pugilato) : null;
  // ⚠ Mesma regra do Acerto por grau das armas: some na ficha de jogador.
  // ⚠ Sai só o GRAU, e o encantamento fica: ver a nota do `acertoGrau` das armas.
  const acertoGrauBasico = ehJogador("danoPorArma")
    ? acertoDosEncantamentos(pugilato?.fa)
    : (pugilato?.fa?.acertoArma ?? 0);
  // As fontes do Acerto que NÃO são o grau (o encantamento Precisa). Sem elas o
  // hover jogava o bônus todo dentro de "Grau da Ferramenta".
  const fontesAcertoBasico = pugilato?.fa?.fontesAcerto ?? [];
  const propriedadesBasico = pugilato ? propriedadesDaArma(pugilato.def, pugilato.fa) : [];
  const anatomiaArmaNatural = anatomiasEscolhidas(creature).includes("arma_natural");
  const propriedadesNaturais = {
    ...(anatomiaArmaNatural || aptidoesIds.includes("mal_armas_naturais") ? { fineza: true } : {}),
    ...(anatomiaArmaNatural ? { energica: true } : {}),
  };
  for (const p of propriedadesDaArma({ props: propriedadesNaturais })) {
    if (!propriedadesBasico.some((x) => x.id === p.id)) propriedadesBasico.push(p);
  }
  const criticoExtraDadosBasico = pugilato?.fa?.encantamentos?.some(
    (x) => x.id === "enc_arma_destruidora" && x.atende) ? 1 : 0;
  // O escopo do item, para o efeito de encantamento com `alvoItem` alcançar a
  // linha do Ataque Básico. Sem isto, Potente e Poderosa numas Faixas eram
  // descartados calados e o encantamento ainda cobrava o degrau de grau.
  // ⚠ Só o id: "arma", a categoria e o grupo ficam de fora de propósito, porque
  // o livro diz que Faixas NÃO são armas.
  const escoposBasicoExtra = pugilato?.def?.id ? [pugilato.def.id] : [];
  // Fineza do item que define o golpe (Soco Inglês). A propriedade estava na
  // tabela e não chegava em lugar nenhum: o básico só olhava o canal.
  const finezaBasico = propriedadesBasico.some((p) => p.id === "fineza");
  // A escolha da sessão e da ficha precede a escolha de um item criado antigo.
  const ataqueBasicoSalvo = opcoes.ataqueBasicoId ?? creature?.ataqueBasicoId;
  const ataqueIdBasico = ataqueBasicoSalvo != null
    ? (ataqueBasicoSalvo === "amaldicoado" ? "amaldicoado" : "corpo")
    : (podeEscolherAtaqueDaArma(pugilato?.def) && pugilato?.ataqueId === "amaldicoado" ? "amaldicoado" : "corpo");
  /* As linhas de dano que carregam a Sintonizada. Mesmo recorte do Destruidora:
     a arma equipada que não é pugilato vira linha própria, e do pugilato só vale
     o item que DEFINE o Ataque Básico. Ver `aplicarSintonizadaNoDano`. */
  const sintonizadas = armasCarregadas
    .filter((e) => e.fa?.encantamentos?.some((x) => x.id === SINTONIZADA_ID && x.atende))
    .filter((e) => e.def?.grupo !== "pugilato" || e === pugilato)
    .map((e) => ({ entradaId: e.def?.grupo === "pugilato" ? "basico" : e.def.id, tipo: e.fa.sintonizadaTipo ?? null }));
  const dedicadas = resolveArmasDedicadas(creature, armasParaDano, habilidades.efetivas);

  const bloodfeast = resolveBloodfeast(creature, { bt, nd, modCon: modBase.constituicao, sessao: estadoBloodfeast, aptidoes: aptidoesIds });
  const efeitosTodos = carimbarGrupoExclusivo([
    /* Os do montante que leem a bancada (a Atenção em combate do Instinto
       Sanguinário, e qualquer origem, Treino ou texto livre com estado de
       combate). Saíram da lista de lá, então entram só aqui. */
    ...efeitosMontanteDeBancada,
    ...efeitosBloodfeast(bloodfeast, Object.keys(TIPOS_DANO)),
    ...efeitosAgulha,
    // Os dois blocos do Vislumbre Celeste. O `quando` de cada um lê o estado
    // "Olhos Descobertos", então os dois convivem e só um vale por vez.
    ...efeitosVislumbre.filter((e) => e.canal !== "pontosAptidao"),
    ...efeitosOlhinhosLu,
    ...coletarEfeitosCriatura({
      habilidades, talentos: talentosPre, altoNivel,
      // As Melhorias Superiores do jogador têm números próprios.
      sistema,
      caracteristicasAmaldicoadas: creature?.caracteristicasAmaldicoadas,
      // As respostas de quem pede escolha (atributo, perícia, tipo de dano).
      caracteristicasAmaldicoadasAlvos: creature?.caracteristicasAmaldicoadasAlvos,
      catalogos: {
        habilidades: getHabilidade, talentos: getTalento,
        // Um mapa só para as opções dos dois catálogos: os ids não colidem
        // (prefixo `lut_`/`cmb_`/`res_` contra `tal_`).
        opcoes: { ...OPCAO_ESCOLHA_NOME, ...OPCAO_TALENTO_NOME },
        // Com o sistema, o hover diz "Melhoria de Classe de Armadura" no jogador.
        altoNivel: (id) => getMelhoriaSuperior(id, sistema, creature) || getHabilidadeLendaria(id, creature) || getHabilidadeApice(id),
      },
    }).map(aplicarDiretoDaAdaptacao).map((e) => efeitoDaImitacao(e, imitacao, nd))
      .map((e) => expandeHerdadas([e.origem]).includes("res_restrito_pelos_ceus") && configuracaoEspecializacao.defesaAtributo
        ? { ...e, expr: `min(mod_${configuracaoEspecializacao.defesaAtributo}, nd)` } : e),
    // Direcionados por uma escolha que mora FORA do card da habilidade (a
    // marcação na linha de dano). Mesmo padrão do efeitosDeTreino.
    ...efeitosArmasDedicadas(dedicadas, habilidades.efetivas.includes("lut_um_com_a_arma")),
    ...efeitosDeTalentosConfigurados(creature),
    ...configuracaoEspecializacao.efeitos,
    // Funcionamento Básico da técnica: os únicos efeitos ESCRITOS pelo jogador,
    // porque a técnica é única no mundo e nenhum catálogo a cobre. Entram no
    // mesmo bolo, e os filtros de estágio abaixo roteiam pelo canal.
    ...semTecnicaBloqueada(efeitosDaTecnica(creature)),
    ...efeitosDosBuffsNativos(),
    ...efeitosArmasTransformaveis(armasTransformaveis(creature, catalogoDoTipo("arma", creature), bt)),
    // Passivos / Características criados pelo jogador usam o mesmo Motor, mas
    // entram na família exclusiva própria dos Feitiços Passivos.
    ...semFeiticoExausto(semTecnicaBloqueada(efeitosDosPassivos(creature))),
    // Buffs de MESA, escritos na Ficha Final durante o jogo. Mesmo shape do
    // Funcionamento Básico, e por isso entram na mesma linha. Só existem quando
    // a Ficha injeta `buffsSessao`: o criador nunca os vê.
    ...efeitosDaSessao(creature),
    /* As CONDIÇÕES, já com a disputa resolvida: uma linha por número, só a
       vencedora. Entram aqui, e não numa lista própria mais abaixo, porque o
       Condenado mexe no `custoPE`, que precisa chegar no passe pós-aptidão do
       Domínio Simples, e o resto (Defesa, TR, perícia, acerto, iniciativa) é
       estágio 2 comum. */
    ...condicoes.efeitos,
    ...efeitosDasAdaptacoes(creature, opcoes.adaptacoes),
    ...efeitosDharma(creature, opcoes.dharma),
    // Habilidade Única da Ferramenta equipada, a primeira das cinco fontes do
    // pool exclusivo a chegar no Motor. Já vem com o valor resolvido no contexto
    // do item (a expressão dela lê `grau`) e com `exclusivo` carimbado.
    ...equip.efeitosUnica,
    // Encantamentos das Ferramentas equipadas. Passaram a entrar pelo Motor em
    // 2026-08-01, no lugar de somarem em escalar: era o teto de sete canais que
    // mantinha metade deles como texto morto. Sem `exclusivo`, porque
    // encantamento soma normal e não é fonte do pool exclusivo.
    ...equip.efeitosEncantamento,
    // O texto ESPECIAL da arma equipada, quando ele é número. Hoje só as
    // Manoplas ("seu dano desarmado aumenta em 1 nível para cada 2 no seu
    // modificador de força"), que estavam sem efeito nenhum até 2026-08-08.
    ...efeitosEspeciaisDeArma(armasCarregadas),
    // Aptidões Amaldiçoadas (2026-07-30). As de bancada leem `au` e `cl`, que
    // são variáveis do contexto principal, então caem todas no estágio 2.
    ...coletarEfeitosAptidao(creatureComAptidoes, semEnergia),
    /* AUXÍLIOS DAS INVOCAÇÕES ligados na mesa (2026-08-31). Um Shikigami em
       campo pode gastar a ação dele para dar Defesa, Acerto ou RD ao dono, e
       isso passou a mexer no número de verdade. Ver `efeitosDeInvocacao`.

       ⚠ ENTRA AQUI, e não perto de `derived.invocacoes` lá embaixo, porque a
       Defesa e a RD Geral do dono fecham ANTES daquele ponto: somar depois
       daria um número que a ficha mostra e o hover não explica. O valor não
       depende de stat nenhum do dono, então não há laço. */
    ...efeitosDeInvocacao(creature, {
      nd, bt,
      // ⚠ É O ND. Ver a nota em `derived.invocacoes`, mais abaixo.
      nivelControlador: nd,
      sessaoInvocacoes: opcoes.invocacoes,
    }),
  ], poolEmGrupos);

  // Estágio 0b: os canais que ALIMENTAM o contexto principal. Só nível de
  // aptidão por ora, porque `dom/au/cl/bar/er` são variáveis do DSL e uma
  // habilidade que concede trilha tem de entrar antes de o contexto existir.
  // Mesma regra do estágio de atributo: dentro dele um efeito não vê o irmão.
  const efPreContextoBase = resolverExclusivos(aplicarEfeitos(
    efeitosTodos.filter(ehPreContexto),
    ctxMontante,
  ));

  // A expansão só pode conceder os +2 depois de sabermos quais trilhas já têm
  // ao menos Nível 1 sem ela. Esta primeira resolução não vai para a saída, ela
  // existe apenas para a expansão não habilitar o próprio bônus numa trilha 0.
  const mapasAptidao = (preContexto) => {
    const concedidas = { ...treino.aptidaoTrilha };
    for (const [k, v] of Object.entries(preContexto?.porAlvo?.nivelAptidao || {})) {
      concedidas[k] = (concedidas[k] || 0) + v;
    }
    const limites = {};
    for (const fonte of [efMontante.porAlvo.limiteAptidao, preContexto?.porAlvo?.limiteAptidao]) {
      for (const [k, v] of Object.entries(fonte || {})) limites[k] = (limites[k] || 0) + v;
    }
    return { concedidas, limites };
  };
  const mapasSemDominio = mapasAptidao(efPreContextoBase);
  const aptidaoSemDominio = semEnergia
    ? resolveNiveisAptidao(null, {}, null)
    : resolveNiveisAptidao(
      creature?.aptidoes,
      mapasSemDominio.concedidas,
      mapasSemDominio.limites,
      trilhasOrigem,
    );
  const efPreContextoDominio = resolverExclusivos(aplicarEfeitos(
    efeitosDeAptidaoDoDominio(creature, {
      aptidoesEscolhidas: aptidoesIds,
      niveisAptidao: aptidaoSemDominio.efetivo,
    }),
    ctxMontante,
  ));
  const efPreContexto = mesclarEfeitos(efPreContextoBase, efPreContextoDominio);

  // ---------- LIMITE EFETIVO DE ATRIBUTO (final) ----------
  // Agora sim: limite de estágio 0 (20 / ficha / Origem / Desenvolvimento) mais o
  // canal `limiteAtributo`, que chega de dois lugares. Do `efMontante` vem o
  // Treino de Atributo Completo, e do `efPreContexto` vêm as fontes que dizem
  // "o valor E o limite" (Incremento de Atributo, Quebra de Limites e o
  // Aperfeiçoamento de Atributo).
  const limiteMotorDe = (key) =>
    (efMontante.porAlvo.limiteAtributo?.[key] || 0) + (efPreContexto.porAlvo.limiteAtributo?.[key] || 0);
  // Teto do sistema por atributo: 30 para todo mundo, 32 onde o Aperfeiçoamento
  // de Atributo bateu. É o ÚNICO `furaTeto` do sistema, e ele vale tanto para o
  // limite quanto para o valor (o autor confirmou em 2026-07-29 que a Lendária
  // sobe as DUAS coisas em 2, então num atributo de limite 30 ela leva a 32).
  const tetoSistemaDe = (key) =>
    Math.min(atributosAddon.limite(key), (furaTetoEm(efPreContexto, key) || furaTetoEm(efMontante, key)
      ? ATTR_LIMITE_ABSOLUTO
      : ATTR_LIMITE_MAX) + tetoExtra(key));
  const attrLimiteEfetivo = Object.fromEntries(
    ATTR_KEYS.map((k) => [k, Number.isFinite(atributosAddon.limite(k))
      ? atributosAddon.limite(k) : Math.min(limiteBaseOf(k) + limiteMotorDe(k), tetoSistemaDe(k))]),
  );

  /* ---------- O QUE O LIMITE DE ESTÁGIO 0 CORTOU, DEVOLVIDO ---------- */
  /* ⚠ O LIMITE SUBIA E O VALOR NÃO (autor, 2026-08-31): *"Feitiço que aumenta
     Limite de Atributo está aumentando o limite, porém, quando você tenta subir
     o atributo ele é travado em 20 ainda."*

     O `eff()` roda no estágio 0, onde o único limite conhecido é o
     `limiteBaseOf` (20, mais Origem, Desenvolvimento e pool de Maldição). Tudo o
     que ele apara vira `perdaNoLimite` e nunca mais volta, porque o estágio 1 só
     SOMA o canal `atributo` por cima do resultado já cortado. Uma ficha com o
     limite em 26 pelo Motor mostrava Limite 26, Efetivo 20 e o aviso "2 pontos
     de bônus perdidos no limite 26", que é o próprio código dizendo que estava
     aparando por um número diferente do que exibia.

     Aqui a conta de estágio 0 é REFEITA contra o limite final. Não é um segundo
     aparo: é o mesmo, agora com o limite certo na mão. A perda é reescrita em
     vez de somada, senão o ponto cortado no estágio 0 seria contado duas vezes.

     ⚠ O `attrBase` NÃO é corrigido, e é de propósito. Ele é o atributo que o
     contexto do Motor e os pré-requisitos enxergam, e ele existe ANTES do canal
     `limiteAtributo` por construção: corrigi-lo aqui exigiria resolver os
     catálogos de novo com o valor novo, e uma habilidade cujo requisito é o
     atributo que ela mesma libera fecharia o laço. O valor final da ficha sai do
     `attrPermanente` logo abaixo, e é esse que a tela e os stats leem. */
  const attrBaseFinal = {};
  for (const k of ATTR_KEYS) {
    const dentro = Math.min(somaCrua[k] ?? 0, attrLimiteEfetivo[k]);
    perdaNoLimite[k] = (somaCrua[k] ?? 0) - dentro;
    const comEquip = Math.min(dentro + (equip.attrBonus[k] || 0), tetoSistemaDe(k));
    folgaEquip[k] = comEquip - dentro;
    attrBaseFinal[k] = comEquip;
  }

  // Níveis de aptidão por trilha: alocado (pago) + concedido (grátis,
  // direcionado). A concessão vem de dois lados, Treinamento e Habilidade.
  const mapasComDominio = mapasAptidao(efPreContexto);
  // TETO por trilha: 5 mais o canal `limiteAptidao`. Chega dos mesmos dois
  // lugares do nível, porque as regras que quebram o teto emitem os dois canais
  // juntos (as duas Habilidades que dão "+1 podendo passar de 5", e a Expansão
  // de Domínio, que dá +2 em Aura, Controle e Leitura e Energia Reversa).
  // Restringido não tem Nível de Aptidão nenhum: entra com a alocação vazia e
  // sem concessão, para as variáveis `dom/au/cl/bar/er` do DSL saírem zeradas
  // junto. Uma ficha que trocou de Tipo depois de alocar não fica mentindo.
  // Trilhas que a ORIGEM tem: a Maldição não possui Energia Reversa.
  const aptidao = semEnergia
    ? resolveNiveisAptidao(null, {}, null)
    : resolveNiveisAptidao(
      creature?.aptidoes,
      mapasComDominio.concedidas,
      mapasComDominio.limites,
      trilhasOrigem,
    );

  // ---------- Estágio 0c: os canais que leem o Nível de Aptidão ----------
  // Um passe só, e ele existe por um encaixe: `imbuicoesEstilo` precisa da
  // variável `dom`, que o pré-contexto ainda não tem, e precisa estar pronto
  // antes do `resolveEstilos` logo abaixo, que o estágio 2 não alcança.
  // Ver `CANAIS_POS_APTIDAO` em afty-efeitos.js.
  const ctxComAptidao = { ...ctxMontante, ...(aptidao.efetivo ?? {}) };
  /* ⚠ AS DUAS LISTAS. A fonte mais óbvia deste canal é uma Linha de
     Treinamento, e as Linhas entram pelo MONTANTE, não pelo `efeitosTodos`.
     Filtrar só o segundo deixava o Completo do Treino de Novo Estilo das
     Sombras sem efeito nenhum, calado. */
  const efPosAptidao = resolverExclusivos(aplicarEfeitos(
    [...efeitosMontante, ...efeitosTodos].filter(ehPosAptidao),
    ctxComAptidao,
  ));

  // ---------- SIMULAÇÃO DE COMBATE ----------
  // Bancada de balanceamento (autor, 2026-07-28). Vira variável de DSL, e as
  // habilidades com `quando` ligam e desligam sozinhas. Os tetos dependem da
  // ficha, por isso saem daqui e não do módulo de combate.
  // `empolgacaoMaxima` sai do estágio 0b junto do nível de aptidão, e por isso
  // já está resolvido aqui: ele troca a tabela de dados de Empolgação, e a
  // média do dado é o que as Manobras de Empolgação somam.
  /* ⚠ O COMBATENTE LÊ O ESCALONAMENTO (2026-09-23). A Precisão Definitiva ("A
     cada quatro níveis, você pode gastar 1 ponto a mais") é EFEITO de habilidade,
     e o livro manda a multiclasse contar "seu nível da Multiclasse + Metade do
     seu Nível em outras Especializações para efeitos de habilidades". Era o
     nível real: um Combatente 4 / Lutador 8 (escalonamento 8) ficava com teto 2
     em vez de 3, enquanto o Revigorar, com a mesma frase, já lia o
     escalonamento. É a mesma fonte do `esc_combatente` do DSL, Alma Livre
     incluída. O Restringido não faz multiclasse, então o real dele é o mesmo. */
  const nivelCmb = nivelEspec.combatente?.escalonamento ?? 0;
  const nivelRes = habilidades.niveisPorEfeito?.restringido ?? 0;

  // ---------- Expansão de Domínio ----------
  // ⚠ Os efeitos escolhidos entram numa SEGUNDA lista, e não no `efeitosTodos`
  // lá de cima, por ordem de declaração: seus valores saem das tabelas
  // indexadas pelo DOM, e o `aptidao` só existe aqui. O benefício básico dos
  // níveis de Aptidão já entrou no pré-contexto acima.
  const efeitosDominio = semEnergia ? [] : efeitosDoDominio(creature, {
    dom: aptidao.efetivo?.dom ?? 0,
    aptidoesEscolhidas: aptidoesIds,
    // O Motor opcional do Efeito Especial só escreve nos canais permitidos (DA-20).
    canalPermitido: canalPermitidoEmExpansao,
  });
  const beneficiosRitualDominio = semEnergia
    ? {}
    : beneficiosRitualDoDominio(creature, aptidoesIds);
  // A Amplificação de Técnica para os Especiais de dano (2026-10-08, E-10).
  const amplificacaoDominio = semEnergia ? null : amplificacaoDeTecnica(creature, {
    dom: aptidao.efetivo?.dom ?? 0,
    aptidoesEscolhidas: aptidoesIds,
  });
  // ---------- Novo Estilo da Sombra (Sem Técnica) ----------
  // Entra na mesma SEGUNDA lista do Domínio, e pelo mesmo motivo: as vagas de
  // imbuição no Domínio Simples são o Nível de Aptidão em Domínio, que só existe
  // a partir daqui.
  //
  // ⚠ Os efeitos saem daqui com a quantidade imbuída como VARIÁVEL do DSL, e por
  // isso não dependem do `resolveCombate` lá embaixo: a linha é estática e o
  // valor só é lido quando as expressões rodam, com o contexto já montado.
  /* ⚠ A VAGA EXCLUSIVA DE ESTILO É LIDA AQUI, ANTES DA EMISSÃO (2026-10-04).
     As Técnicas da Expansão têm progressão própria, e a `vagasEstilo` soma
     nela. Técnica além da progressão não pode dar benefício nenhum (DA-07), e
     para saber isso ANTES de emitir os efeitos o total precisa estar fechado
     aqui, e não no orçamento lá embaixo, onde o canal era lido até hoje.

     O contexto é o do passe pós-Aptidão mais o nível por especialização: o
     Especialista em Estilo escreve a vaga com `esc_conjurador`, e no contexto do
     montante as `esc_*` valem zero. O orçamento das Técnicas `legacy` usa este
     MESMO número, para as duas regras nunca contarem a vaga de jeitos diferentes. */
  const efVagasEstilo = resolverExclusivos(aplicarEfeitos(
    [...efeitosMontante, ...efeitosTodos].filter((e) => e?.canal === "vagasEstilo"),
    { ...ctxComAptidao, ...varsDeEspecializacao(nivelEspec) },
  ));
  const estiloCtx = {
    // A MÃE, e não a origem gravada: o Liberto (variação de Addon) tem o Estilo
    // porque é um Sem Técnica. Ver `origemMae`.
    origemId: origemMae(core?.origem?.id ?? null),
    nd,
    dom: aptidao.efetivo?.dom ?? 0,
    // Addon com `libera: ["estiloSombras"]` solta a trava de ORIGEM. O piso de
    // Nível 4 continua valendo (autor, 2026-08-21).
    liberado: liberacoes.includes("estiloSombras"),
    // Vagas de imbuição ALÉM do Nível de Aptidão em Domínio. Sai do
    // pré-contexto porque a régua é lida aqui, antes do contexto principal
    // existir. Ver `CANAIS_PRE_CONTEXTO` em afty-efeitos.js.
    imbuicoesExtras: valorCanal(efPosAptidao, "imbuicoesEstilo"),
    // As parcelas do mesmo canal, para o hover do limite de efeitos de cada
    // Técnica da Expansão.
    partesImbuicao: detalhesDoCanal(efPosAptidao, "imbuicoesEstilo").map((x) => ({ label: x.nome, valor: x.valor })),
    // O interruptor do Domínio existe sem Técnica nenhuma para quem tem a
    // Aptidão (2026-10-04, E-03).
    temDominioSimples: aptidoesIds.includes(DOMINIO_SIMPLES_APTIDAO),
    vagasEstilo: valorCanal(efVagasEstilo, "vagasEstilo"),
    partesVagasEstilo: detalhesDoCanal(efVagasEstilo, "vagasEstilo").map((x) => ({ label: x.nome, valor: x.valor })),
    // As Aptidões da ficha, para as modificações de Aptidão das Técnicas da
    // Expansão. A Técnica guarda só a referência, e o catálogo responde aqui.
    aptidoesPossuidas: aptidoesIds,
    categoriaDaAptidao: (id) => getAptidao(id)?.categoria ?? null,
    efeitosDaAptidao: (id) => APTIDAO_EFEITOS[id] ?? getAptidao(id)?.efeitos ?? [],
    nomeDaAptidao: (id) => getAptidao(id)?.nome ?? id,
    niveis: aptidao.efetivo ?? {},
    // O Nível em que o Estilo destrava, quando a origem o baixa (o Legado do
    // Guerreiro do pacote Stark, 2026-10-11). Sem o campo, o 4 do livro.
    ...(estiloNdMinimoDaOrigem(creature) ? { ndMinimo: estiloNdMinimoDaOrigem(creature) } : {}),
    /* As Habilidades, para o `requer` das Técnicas de pacote, e as OPÇÕES
       escolhidas nelas: o Estilo do Interceptador é opção do Repertório do
       Especialista, e não Habilidade (relato do autor, 2026-10-11, a Cobertura
       da Vanguarda saía inválida com o Estilo escolhido). */
    habilidadesPossuidas: [
      ...(habilidades.efetivas ?? []),
      ...Object.values(habilidades.escolhas?.mapa ?? {}).flat(),
    ],
    nomeDaHabilidade: (id) => getHabilidade(id)?.nome ?? OPCAO_ESCOLHA_NOME[id] ?? id,
  };
  const estilo = resolveEstilos(creature, estiloCtx);
  const efeitosEstilo = efeitosDoEstilo(creature, estiloCtx);

  // ---------- Domínio Simples: área e custo em PE ----------
  // ⚠ DEPOIS do `resolveEstilos`, e não antes, porque o custo cresce com as
  // imbuições: o remendo do Addon cobra 1 PE a mais por Técnica imbuída para
  // erguer, e 1 PE por rodada a cada duas para sustentar. `gastoVagas` é a
  // combinação que está no ar AGORA, lida da bancada ou da sessão.
  //
  // A entrada do catálogo vai inteira, e não só o id: ela pode ter sido
  // remendada por um Addon, e é o remendo que traz o modelo de sustentação.
  const dominioSimples = resolveDominioSimples({
    def: getAptidao(DOMINIO_SIMPLES_APTIDAO),
    tem: aptidoesIds.includes(DOMINIO_SIMPLES_APTIDAO),
    dom: aptidao.efetivo?.dom ?? 0,
    imbuicoes: estilo.gastoVagas,
    // Os dois leitores vêm de fora para o módulo não importar `afty-efeitos.js`
    // e fechar um ciclo com o catálogo de Aptidões. Ver o cabeçalho de lá.
    canal: (id) => valorCanal(efPosAptidao, id),
    fontes: (id, alvo = null) => (id === "custoPE"
      ? detalhesDeCustoPe(efPosAptidao, alvo) : detalhesDoCanal(efPosAptidao, id, alvo))
      .map((x) => ({ label: x.nome, valor: x.valor })),
  });
  const efeitosComDominio = (efeitosDominio.length || efeitosEstilo.length)
    ? [...efeitosTodos, ...efeitosDominio, ...efeitosEstilo]
    : efeitosTodos;

  // Resumo pronto para a aba Habilidades: cada expansão com os números que o
  // card mostra. A UI não recalcula nada, ela só exibe.
  const resumoDominios = (() => {
    const domNivel = aptidao.efetivo?.dom ?? 0;
    const barNivel = aptidao.efetivo?.bar ?? 0;
    const paredesResistentes = aptidoesIds.includes("paredes_resistentes");
    /* ⚠ OS SEIS SAEM DO PASSE PÓS-APTIDÃO, e não do `canal()` do estágio
       principal, que só nasce umas 300 linhas abaixo daqui. É o mesmo passe do
       `imbuicoesEstilo`, e pelo mesmo motivo: eles dependem de `dom` e `bar` e
       precisam estar prontos antes deste resumo. Ver CANAIS_POS_APTIDAO. */
    const canalDominio = (id) => valorCanal(efPosAptidao, id);
    const bonusArea = canalDominio("areaDominio");
    const bonusPvParede = canalDominio("pvParede");
    const bonusEfeitos = canalDominio("efeitosDominio");
    /* ⚠ 2026-10-08 (Técnica Máxima e Expansão de Domínio). O Acerto Garantido só
       vale com a Aptidão e nunca na Incompleta (DA-14), a Sem Barreiras custa 25
       sempre e a oficial não tem domo nem número de área (DA-11), o custo passa
       pelo canal `custoPE` com escopo `dominio` (E-08), e a validação (DA-17)
       segura a abertura da Expansão com ERRO. */
    const temAcertoGarantido = aptidoesIds.includes("acerto_garantido");
    const tetoEfeitos = maxEfeitos(domNivel, bonusEfeitos);
    // As Condições que existem de verdade, para o Efeito Ambiental. Só as três
    // forças que a tabela de Expansão libera.
    const condicoesValidas = {
      fraca: [...(CONDICOES_CATALOGO.fraca ?? [])],
      media: [...(CONDICOES_CATALOGO.media ?? [])],
      forte: [...(CONDICOES_CATALOGO.forte ?? [])],
    };
    // Os nomes dos Feitiços, para o Acerto Garantido que aponta para eles.
    const nomesFeiticos = Object.fromEntries((Array.isArray(creature?.feiticos) ? creature.feiticos : [])
      .filter((f) => f?.id)
      .map((f) => [f.id, f.nome?.trim() || "Feitiço Sem Nome"]));
    const lista = listaDominios(creature).map((d) => {
      const versao = resolveVersaoDominio(d, aptidoesIds);
      const legacy = ehDominioLegacy(d);
      const comAG = acertoGarantidoValido(d, versao, temAcertoGarantido);
      const custoBase = custoDominio(versao, comAG);
      const custo = custoEmPe(custoBase, efPosAptidao, "dominio");
      const domo = temDomo(versao, legacy);
      const validacao = validarDominio(d, {
        dom: domNivel, versao, maxEfeitos: tetoEfeitos, temAcertoGarantido, condicoesValidas,
        nomesFeiticos, canalPermitido: canalPermitidoEmExpansao,
      });
      return {
        ...d,
        versao,
        legacy,
        custo: custo.valor,
        custoBase,
        duracao: duracaoDominio(domNivel, versao),
        area: areaDominio(versao, bt, false, bonusArea, { legacy }),
        temDomo: domo,
        pvBarreira: domo ? pvBarreira(barNivel, nd, paredesResistentes, bonusPvParede) : null,
        acertoGarantidoValido: comAG,
        // O Acerto Garantido estruturado, pronto para a Ficha (Etapa 8). `null` quando não vale.
        acertoGarantidoResumo: resumoAcertoGarantido(d, versao, temAcertoGarantido, { nomesFeiticos }),
        exaustaoTecnica: exaustaoTecnicaDaVersao(versao, comAG),
        // A Contestação desta Expansão: meia área e o dano por rodada na barreira do outro.
        contestacao: contestacaoDoDominio(versao, { dom: domNivel, bt, bonusArea }),
        validacao,
        valida: !validacao.some((v) => v.nivel === "erro"),
        vagasUsadas: vagasUsadas(d.efeitos),
        /* ⚠ ERA `texto`, um parágrafo pronto, até 2026-09-11. As duas telas
           passaram a desenhar estrutura, e o parágrafo repetia em prosa a
           área, a duração e o PV dos campos logo acima. O corpo não carrega
           número nenhum: quem desenha número lê os campos. */
        corpo: corpoDoDominio(d, { dom: domNivel, versao, temAcertoGarantido, nomesFeiticos }),
        /* O custo tem duas parcelas quando o Acerto Garantido está ligado, e
           o hover precisa dizer qual é qual. Depois vêm as do `custoPE`, com o
           sinal da conta: a redução tira, o aumento (Condenado) soma. */
        partesCusto: [
          { label: `Expansão ${rotuloVersao(versao)}`, valor: DOMINIO_CUSTO_BASE[versao] ?? 0 },
          ...(custoBase > (DOMINIO_CUSTO_BASE[versao] ?? 0) ? [{ label: "Acerto Garantido", valor: CUSTO_ACERTO_GARANTIDO }] : []),
          ...custo.partes.map((p) => ({ label: p.label, valor: -p.valor })),
        ],
      };
    });
    /* A BARREIRA da aptidão Técnicas de Barreira, que é irmã do domo e nunca teve
       tela: PV e RD de CADA parede, e quantas cabem. O domo continua valendo
       `PAREDES_NO_DOMO × pvDaParede`, então melhorar a parede melhora os dois. */
    const pvUnidade = pvDaParede(barNivel, nd, paredesResistentes, bonusPvParede);
    const partesPvParede = [
      { label: paredesResistentes ? "Base (Paredes Resistentes)" : "Base", valor: 5 + (paredesResistentes ? 5 : 0) },
      { label: paredesResistentes
        ? "Nível de Aptidão em Barreira × ND"
        : "Nível de Aptidão em Barreira × metade do ND",
        valor: paredesResistentes ? barNivel * nd : barNivel * Math.floor(nd / 2) },
      ...detalhesDoCanal(efPosAptidao, "pvParede").map((x) => ({ label: x.nome, valor: x.valor })),
    ];
    const barreira = {
      pvParede: pvUnidade,
      rdParede: rdDaParede(canalDominio("rdParede")),
      maxParedes: maxParedes(canalDominio("maxParedes")),
      /* ⚠ A CORTINA vale 3 paredes (autor, 2026-08-26). Ela é aptidão própria e
         não tinha número nenhum: o texto dela diz o custo e a área, e nunca a
         vida. Só aparece para quem tem a aptidão. */
      pvCortina: pvCortina(barNivel, nd, paredesResistentes, bonusPvParede),
      temCortina: aptidoesIds.includes("cortina"),
      /* ⚠ A aptidão é o que faz a Barreira EXISTIR. Sem ela os números acima
         valem, mas não há o que erguer, e a tela não mostra o card. */
      tem: aptidoesIds.includes("tecnicas_de_barreira"),
      partesPvParede,
      /* A Cortina é três paredes, então o hover dela é o da parede com a
         multiplicação no fim, e não uma conta paralela. */
      partesPvCortina: [
        ...partesPvParede,
        { label: `× ${PAREDES_NA_CORTINA} paredes`, texto: `× ${PAREDES_NA_CORTINA}` },
      ],
      /* O domo (e o Totem, que usa a mesma conta) é doze paredes: o hover dele
         é o da parede com a multiplicação no fim, igual ao da Cortina. Ele
         mora aqui e não em cada expansão porque não depende de nenhuma. */
      partesPvDomo: [
        ...partesPvParede,
        { label: `× ${PAREDES_NO_DOMO} paredes`, texto: `× ${PAREDES_NO_DOMO}` },
      ],
      partesRdParede: detalhesDoCanal(efPosAptidao, "rdParede").map((x) => ({ label: x.nome, valor: x.valor })),
      partesMaxParedes: [
        { label: "Técnicas de Barreira", valor: PAREDES_BASE },
        ...detalhesDoCanal(efPosAptidao, "maxParedes").map((x) => ({ label: x.nome, valor: x.valor })),
      ],
    };
    /* O CONFLITO DE DOMÍNIO (autor, 2026-08-26). Ele é da CRIATURA e não de cada
       expansão, então mora no resumo: quem confronta é o feiticeiro, e o número
       existe desde que ele tenha Nível de Aptidão em Domínio. */
    const conflitoBase = conflitoDeDominio({
      dom: domNivel, nd, bonus: canalDominio("conflitoDominio"),
    });
    /* ⚠ O +2 DA EXPANSÃO JÁ ATIVA (2026-10-08, E-13). É um dos efeitos de abrir
       ("Um aumento de +2 em testes de Confronto de Domínio") e era só texto. Vale
       com a Expansão no ar, que é quem recebe o confronto de outro domínio. */
    const expansaoNoAr = expansaoDominioNoAr(creature, aptidoesIds);
    const conflito = {
      ...conflitoBase,
      bonus: conflitoBase.bonus + (expansaoNoAr ? 2 : 0),
      partes: [
        ...conflitoBase.partes,
        ...detalhesDoCanal(efPosAptidao, "conflitoDominio").map((x) => ({ label: x.nome, valor: x.valor })),
        ...(expansaoNoAr ? [{ label: "Expansão Ativa", valor: 2 }] : []),
      ],
    };
    return {
      domNivel,
      barNivel,
      paredesResistentes,
      temAcertoGarantido: aptidoesIds.includes("acerto_garantido"),
      maxEfeitos: maxEfeitos(domNivel, bonusEfeitos),
      ativoId: dominioEmUso(creature, aptidoesIds)?.id ?? null,
      /* A Expansão ABERTA na sessão, com a fase (Etapa 10). Difere do `ativoId`,
         que é a ESCOLHIDA e existe fora de combate também: com uma Expansão só,
         ela é sempre a escolhida, aberta ou não. */
      aberta: (() => {
        const fase = faseDoDominio(creature);
        const d = fase ? dominioEmUso(creature, aptidoesIds) : null;
        return d ? { id: d.id, fase } : null;
      })(),
      beneficiosRitualAtivos: beneficiosRitualDominio,
      amplificacaoTecnica: amplificacaoDominio,
      barreira,
      conflito,
      lista,
    };
  })();

  const estadosConjurador = estadosCombateConjurador({
    habilidades: habilidades.efetivas,
    tecnicas: tecnicasCombate,
    armas: armasParaDano,
    feiticos: creature?.feiticos,
    // Para esconder o Feitiço cujo efeito não existe no nível dele.
    nd,
  });
  const estadosAptidoes = estadosCombateAptidoes({
    aptidoesIds,
    au: aptidao.efetivo?.au ?? 0,
    cl: aptidao.efetivo?.cl ?? 0,
  });
  // O teto de faixa escrito como expressão ("bt") é lido no contexto do montante.
  const estadosAddon = estadosCombateDeAddon(creature, acessoFeitico, {
    avaliar: (expr) => evalNumberDsl(expr, ctxComAptidao, 0),
  });
  const estadosVislumbre = estadosDoVislumbre({ tem: temVislumbre });
  const estadosCeu = estadosManipulacaoCeu(creature);

  /* ---------- TETO DE PER DA ENERGIA REVERSA ----------
     ⚠ ERA A MESMA CONTA ESCRITA TRÊS VEZES: os efeitos de `curaPontos` na
     linha de Cura, o `fluxoPER` daqui e o `max` da faixa no afty-combate.js. O
     Treino de Energia Reversa (1ª) nunca entrou em nenhuma, e o autor viu o teto
     parado em 8 onde a conta dava 9 (2026-09-16).

     Agora as três leem os MESMOS efeitos. Este é um passe próprio, e não a
     leitura do `ef` final, porque a bancada apara o PER da sessão ANTES do
     estágio 2 existir: a Regeneração do Fluxo Constante lê `fluxo_per`. As duas
     listas entram porque a Linha de Treinamento vem pelo montante. */
  const tetoPERDaCura = Math.max(0, Math.trunc(valorCanal(
    aplicarEfeitos(
      [...efeitosMontante, ...efeitosTodos].filter((e) => e?.canal === "curaPontos"),
      ctxComAptidao,
    ),
    "curaPontos",
    "cura_energia_reversa",
  )));

  const combate = resolveCombate({ ...creature, combate: { ...creature?.combate,
    adrenalinaAtletismo: configuracaoEspecializacao.atletismo } }, {
    apiceId: altoNivel.apiceId,
    dominios: resumoDominios.lista,
    // Com as especializações: o degrau lê o escalonamento. Ver `degrausBrutalidade`.
    brutalidadePE: degrausBrutalidade({ habilidades, especializacoes }),
    brutalidadePilha: bt,
    empolgacaoMaxima: valorCanal(efPreContexto, "empolgacaoMaxima") > 0,
    devastacaoPilha: bt,
    precisaoPE: 1 + Math.floor(nivelCmb / 4),
    pistoleiroEmperrar: habilidades.efetivas.includes("cmb_pistoleiro_avancado") ? 6 : 2,
    ataqueConcentrado: tetoAtaqueConcentrado(habilidades.efetivas),
    // Com as herdadas: a herdeira do Restringido tem a Restrição Definitiva sob o id clonado.
    adrenalinaAtletismo: expandeHerdadas(habilidades.efetivas).includes("res_restricao_definitiva") ? 8 : 4,
    cacadorFeiticeiros: 1 + Math.floor(nivelRes / 5),
    corpoDeAco: 1 + (nivelRes >= 10 ? 1 : 0) + (nivelRes >= 15 ? 1 : 0),
    // Tetos das faixas das Aptidões: os dois dependem do Nível de Aptidão em
    // Controle e Leitura, que só existe depois do resolveNiveisAptidao.
    cobrirSePE: 2 + 2 * (aptidao.efetivo?.cl ?? 0),
    estimuloTeste: aptidao.efetivo?.cl ?? 0,
    // O Fluxo Constante segue "as mesmas regras da cura básica", então o teto
    // dele é o da linha de Cura. Ver `tetoPERDaCura`, logo acima.
    fluxoPER: tetoPERDaCura,
    // Regeneração Corporal (Maldição): "a quantidade máxima de pontos que podem
    // ser gastos passa a ser igual ao seu bônus de treinamento por rodada", que
    // a Regeneração Ampliada dobra. Irmão do fluxoPER, com PE no lugar de PER.
    regeneracaoPE: aptidoesIds.includes("mal_regeneracao_ampliada") ? 2 * bt : bt,
    // "gastar pontos de energia amaldiçoada igual a metade do seu bônus de
    // treinamento". O teto do contador é quanto ele pode gastar de uma vez.
    conhecimentoAplicado: Math.floor(bt / 2),
    adeptoFeiticariaReducoesUsadas: bt,
    tempestadeIdeiasUsos: Math.floor(bt / 2),
    // Interruptores que vêm da FICHA, e não do catálogo de estados, porque são
    // instâncias: uma por Habilidade Única ativa, e uma por Técnica de Estilo
    // que precisa de gatilho (toda Modificação de Domínio Simples, mais a
    // Técnica Especial com linha ativa).
    /* ⚠ CADA FONTE CARIMBA A SUB-ABA DELA (2026-09-17). Estes estados nascem
       aqui e não têm `requer*` nenhum, então sem o carimbo todos caíam no mesmo
       balde de "Outros" e a aba Buffs virava uma lista só. O `dono` é a porta
       que `donoDoEstado` (ficha-estados.js) consulta antes de qualquer outra
       coisa, e quem já declara o próprio (os Addons) passa intacto. */
    estadosExtras: [
      ...comDonoDeBancada(equip.estadosUnica, SUB_OUTROS),
      // O Talismã do Ápice, do livro ou criado: um estado só, por ficha.
      ...(equip.temApice ? comDonoDeBancada([ESTADO_APICE_DEF], SUB_OUTROS) : []),
      // Técnica: o que se ATIVA. Estilo, Domínio, Feitiço Auxiliar e Transformação.
      ...comDonoDeBancada(estilo.estados, SUB_TECNICA),
      ...comDonoDeBancada(estadosConjurador, SUB_TECNICA),
      ...comDonoDeBancada(estadosAptidoes, SUB_APTIDOES),
      ...estadosAddon,
      ...comDonoDeBancada(estadosVislumbre, SUB_OUTROS),
      ...comDonoDeBancada(estadosDosOlhinhosLu({ tem: temOlhinhosLu }), SUB_OUTROS),
      ...estadosCeu,
      // Só existe com uma arma equipada que tenha a Sintonizada.
      ...(sintonizadas.length
        ? comDonoDeBancada([{ id: ESTADO_SINTONIZADA, label: "Sintonizada", tipo: "bool" }], SUB_OUTROS)
        : []),
      /* O teto de aliados sai do GRAU DE FEITICEIRO, verbatim do livro, e por
         isso os nativos são montados aqui em vez de virem prontos: Quarto Grau
         não pode ter aliado nenhum, e nesse caso as linhas deles nem entram.
         O dono de cada um já vem de lá: Comidas e Ferreiro são Interlúdio, e
         Aliados e Alma são Outros. */
      ...estadosNativosExtras(grau.rank),
    ],
  });
  const auxiliaresAtivos = resolveAuxiliaresAtivos(creature, combate, estadosConjurador, {
    nd,
    // O acesso inteiro, para a Técnica Máxima ligada sair na escala dela
    // (2026-10-08). Sem o nível de Conjurador o Adiantar Evolução ficaria de fora.
    nivelConjurador,
    habilidades: habilidades.efetivas,
  });
  const aurasDesabilitadas = new Set(aptidoesAuraDesabilitadas(
    {
      ...creature,
      aptidoes: { ...creature?.aptidoes, au: aptidao.efetivo?.au ?? 0 },
      combate: { ...creature?.combate, concentrarAura: combate.concentrarAura },
    },
    aptidoesIds,
  ));
  /* ⚠ CARIMBADO DE NOVO, e não por engano: o Estilo, a Expansão de Domínio e os
     Auxiliares ligados chegam aqui sem ter passado pelo `efeitosTodos`. O que já
     tinha carimbo recebe o mesmo grupo outra vez. */
  const efeitosAtivos = carimbarGrupoExclusivo([
    ...efeitosComDominio.filter((e) => !aurasDesabilitadas.has(e.origem)),
    ...efeitosCombateAmaldicoado(tecnicasCombate, combate, habilidades.efetivas, bt),
    ...semFeiticoExausto(auxiliaresAtivos.efeitos),
  ], poolEmGrupos);
  // Expressões que leem `dados_dano_final` só podem ser avaliadas quando cada
  // linha de dano já sabe quantos dados vai rolar. Elas não entram no agregado
  // geral e viajam cruas até o calculador de Feitiços.
  const efeitosLinhaDano = efeitosAtivos.filter(efeitoUsaDadosDanoFinal);
  const efeitosConcentrados = efeitosLinhaDano.filter((e) => efeitoDeAtaqueConcentrado(e, (id) => expandeHerdadas([id])));

  /* MARCAS da ficha, para o `contar()` do DSL (Addons fase 0, 8.1 do
     docs/afty-addons.md). Sai das MESMAS três listas que alimentam o `tem_*`
     logo abaixo, então o que a criatura "tem" é a mesma coisa nas duas.
     Montado UMA vez: o `montarCtx` roda três vezes (os estágios do motor) e o
     conjunto de entradas não muda entre eles. */
  /* ⚠ As marcas DECLARADAS pelos addons entram todas, mesmo valendo zero, e só
     depois vêm as que a criatura realmente tem. Sem isto, uma marca que o addon
     declara mas a ficha ainda não usa simplesmente NÃO APARECERIA no seletor
     `{ }`, e não haveria como escrever a expressão dela antes de pegar a
     primeira habilidade. É a mesma política já documentada para o `tem_*`: a
     família grande mostra o que não é zero, mas o que é zero continua alcançável.
     A ordem importa, porque o `marcasDeEntradas` abaixo sobrescreve com a
     contagem de verdade. */
  const marcasFicha = Object.assign(
    Object.fromEntries(marcasDeclaradas().map((m) => [m.marca, 0])),
    marcasDeEntradas([
    ...habilidades.efetivas.map((id) => {
      const h = getHabilidade(id);
      return h && { tags: h.tags, familia: "habilidade", especializacaoId: h.especializacaoId };
    }),
    ...(talentosPre.escolhidas ?? []).map((id) => {
      const t = getTalento(id);
      return t && { tags: t.tags, familia: "talento" };
    }),
    ...aptidoesIds.map((id) => {
      const a = getAptidao(id);
      return a && { tags: a.tags, familia: "aptidao" };
    }),
  ]),
  );

  /* QUANTAS INVOCAÇÕES ESTÃO EM CAMPO (2026-09-30, Etapa 7). Só existe com mesa
     (Ficha e Encontro, `opcoes.invocacoes`); no criador é `null`. Lê o Controle
     Sintonizado (+1 em acerto e dano por invocação em campo) e o Concentrar Poder
     (só com uma em campo). A Quimera conta 1 (decisão do autor). */
  /* Hoste Amaldiçoada (autor, 2026-10-03): o par conta como uma nos dois
     limites. Só agrupamos duas Hostes com vínculo recíproco e ambas em campo.
     Quando uma sai, a outra volta a ocupar a vaga por seu próprio id. */
  const hordasDaMesa = (Array.isArray(creature?.hordas) ? creature.hordas : [])
    .filter((h) => !(h?.hoste && h.parId && h.id > h.parId
      && contaInvocacoesEmCampo(opcoes.invocacoes, [`horda:${h.id}`]) > 0
      && (creature.hordas ?? []).some((par) => par?.id === h.parId
        && par.hoste && par.parId === h.id
        && contaInvocacoesEmCampo(opcoes.invocacoes, [`horda:${par.id}`]) > 0)));
  const idsHordasDaMesa = hordasDaMesa.map((h) => `horda:${h?.id}`);
  const hordasEmCampo = opcoes.invocacoes
    ? contaInvocacoesEmCampo(opcoes.invocacoes, idsHordasDaMesa) : null;
  const idsDaMesa = [
    ...(Array.isArray(creature?.invocacoes) ? creature.invocacoes : []).map((i) => i?.id),
    ...(Array.isArray(creature?.quimeras) ? creature.quimeras : []).map((q) => `quimera:${q?.id}`),
    /* As Hordas e os Corpos de Múltiplos Núcleos contam como UMA invocação em
       campo cada (2026-10-01, Etapa 9). O Mecha não entra: as duas Marionetes
       dele seguem ativas, e é assim que ele conta como duas. */
    ...idsHordasDaMesa,
    ...(Array.isArray(creature?.multiplosNucleos) ? creature.multiplosNucleos : []).map((g) => `nucleos:${g?.id}`),
  ].filter(Boolean);
  const invocacoesEmCampo = opcoes.invocacoes ? contaInvocacoesEmCampo(opcoes.invocacoes, idsDaMesa) : null;

  /* O PACOTE DA CLASSE INICIAL e o TR que ele dá, só no jogador. Montados AQUI,
     antes do contexto do Motor, e não junto do `resolveTestes` lá embaixo: o
     "Caso já seja" da Força Imparável e da Resiliência Melhorada lê o
     `prof_tr_*`, e o TR que a Classe treina é "já treinado" (autor,
     2026-10-03). Nenhum dos dois depende de stat, só das Especializações e dos
     campos da ficha, então subir não abre laço. */
  const pacoteInicial = ehJogador("pacoteDaClasseInicial")
    ? pacoteInicialDaFicha(especializacoes.escolhidas)
    : undefined;
  /* O TR que a Classe inicial deu, com a faixa, e o Teste de Resistência Mestre
     por cima (2026-09-23). */
  const trDaClasse = ehJogador("pacoteDaClasseInicial")
    ? resistenciasDaClasse(pacoteInicial, creature, { comMestre: ehJogador("trMestreDoJogador") })
    : undefined;

  const montarCtx = (attrs, mods) => buildCriaturaDslContext({
    nd, bt, escalaAtaque, grauRank: grau.rank, patamar, tipo, almaAtual: almaAtualDsl, invocacoesEmCampo,
    nivelFeiticoMax: acessoFeitico,
    origemContadoresVars,
    opcoesOrigem: opcoesOrigemDsl,
    irmaoMorto: !!creature?.core?.origem?.irmaoMorto,
    iniciativaIrmao: creature?.core?.origem?.iniciativaIrmao,
    attrEff: attrs, mods, modTecnica: mods[tecnicaAttr] ?? 0, tecnicaAttr,
    aptidao: aptidao.efetivo, nivelEspec, periciasProf: creature?.pericias,
    resistenciasProf: creature?.resistenciasProf, combate,
    faixasTrDaClasse: trDaClasse?.faixas,
    aptidaoOpcoes: semEnergia ? {} : creature?.aptidaoOpcoes,
    rdEscudoBase: equip.rdEscudoBase,
    escudoEquipado: equip.entradas.some((e) => e.tipo === "escudo" && e.equipado),
    fontesTreinoEscudo: treinoEscudo.fontes,
    /* O manejo atual, para o "enquanto estiver desarmado ou empunhando uma arma
       marcial" virar condição de verdade. `armasParaDano` já exclui o pugilato,
       que é o Ataque Básico e não uma arma na mão, então lista vazia É estar
       desarmado. A Arma Dedicada entra pela lista da ficha, e não pelo canal
       `propMarcial`, que só existe depois dos efeitos. */
    desarmado: armasParaDano.length === 0,
    /* Faixas continuam no grupo Pugilato do catálogo, mas o Adepto de Briga
       funciona com elas. Outro item do grupo equipado desliga o talento,
       mesmo quando também há Faixas equipadas.
       ⚠ "Faixas" aqui não é mais o id do livro: a arma CRIADA com Dano
       Desarmado e "Faixas" no nome também é Faixas, e quem responde isso é o
       `ehFaixas` (afty-equipamentos.js), lido também pelo `itensEquipados`. */
    armaPugilato: !!pugilato,
    outroPugilato: armasCarregadas.some(
      (e) => e.def?.grupo === "pugilato" && !ehFaixas(e.def)),
    armaMarcial: armasParaDano.some((a) => (
      (a.propriedades ?? []).some((p) => p.id === "marcial")
      || (dedicadas.escolhidas ?? []).includes(a.id)
    )),
    // `tem_*` inclui Talentos e Aptidões escolhidos, não só as Habilidades.
    // ⚠ A lista de aptidões respeita o `semEnergia`: um Restringido não tem
    // Aptidões, e `tem_*` não pode dizer que tem.
    habilidadesEscolhidas: [
      ...habilidades.efetivas,
      ...(talentosPre.escolhidas ?? []),
      ...aptidoesIds,
      // As Características Amaldiçoadas que o catálogo ainda conhece (2026-10-12).
      ...(Array.isArray(creature?.caracteristicasAmaldicoadas) ? creature.caracteristicasAmaldicoadas : [])
        .filter((id) => getCaracteristicaAmaldicoada(id)),
    ],
    vocabulario: vocabularioDsl,
    marcas: marcasFicha,
  });
  // Soma um canal de atributo sobre uma base, aparando nos TRÊS tetos do sistema
  // (ver o topo de afty-atributos.js).
  //
  // ⚠ ATÉ 2026-07-29 ISTO APARAVA EM 30, e não no limite do atributo. Era o bug
  // que deixava 36 efeitos do Motor mais o Treino de Atributo furarem o 20
  // calados. O limite do atributo é o teto normal, o 30 é o do sistema, e só o
  // Aperfeiçoamento de Atributo (`furaTeto`) chega ao 32.
  //
  // O acessório de atributo entra pela `folgaEquip`: o texto dele diz "podendo
  // superar o seu limite de atributo, até o máximo de 30", então ele levanta o
  // teto DAQUELE atributo pelo tanto que já contribuiu, sem levantar o do Motor.
  //
  // ⚠ O teto NUNCA DERRUBA o que já estava acima dele: como esta função roda
  // duas vezes (permanente e depois temporário), aparar cru no segundo passo
  // desfaria um furaTeto legítimo do primeiro. O que o teto impede é SUBIR além
  // dele, não estar além dele.
  // ⚠ NÃO há caminho separado para o `furaTeto` (revisto em 2026-07-29). Ele
  // deixou de ser "esta parcela fura o teto" e passou a ser "o teto DESTE
  // atributo é 32", porque o Aperfeiçoamento sobe o limite junto do valor. Com o
  // limite subindo, a parcela cabe pelo caminho normal, e a carona que a versão
  // anterior evitava virou o comportamento certo: quem levanta o limite levanta
  // para toda fonte, igual ao Incremento de Atributo e à Quebra de Limites.
  /* ⚠ O LIMITE QUE A LINHA ATIVA LEVANTA (2026-09-07). O `limiteMotorDe` lá em
     cima lê só os estágios MONTANTE e PRÉ-CONTEXTO, que rodam antes de a
     Simulação de Combate existir, então um canal `limiteAtributo` vindo de um
     Feitiço Auxiliar ativo nunca chegava nele: o +12 de Força somava e parava
     no limite de 20, calado.

     A saída é a MESMA do acessório de atributo, descrita no bloco acima: em vez
     de reabrir o limite de estágio 0, a parcela levanta o TETO DESTE ESTÁGIO
     pelo tanto que ela mesma declara. O `tetoSistemaDe` continua sendo a última
     palavra, então "supera o seu limite, até o máximo de 30" cai exatamente no
     30 sem ninguém escrever 30 em lugar nenhum.

     ⚠ Sai do `efeitosAtivos`, que é a lista da bancada e da sessão. Uma ficha
     em repouso não tem nada aqui, e o limite volta ao 20 quando o Feitiço cai. */
  /* ⚠ PASSA PELO `resolverExclusivos`, e não pelo `aplicarEfeitos` cru. A linha
     do Feitiço Auxiliar é do POOL EXCLUSIVO, e efeito exclusivo sai da soma e
     espera a disputa: ler `porAlvo` antes de resolver devolve objeto vazio, que
     foi exatamente o primeiro jeito que eu escrevi isto e que não levantava
     limite nenhum, calado.

     De brinde, a disputa por `(canal, alvo)` já é a regra do autor: dois
     Feitiços no MESMO atributo ficam com o maior, e em atributos diferentes
     valem os dois. */
  const limiteAtivoCom = (ctx) => resolverExclusivos(aplicarEfeitos(
    efeitosAtivos.filter((e) => e?.canal === "limiteAtributo"),
    ctx,
  ));
  const limiteAtivoPor = limiteAtivoCom(montarCtx(attrBase, modBase)).porAlvo.limiteAtributo || {};

  /* O teto que cada atributo REALMENTE usou, para o hover não mentir. Sem ele o
     rótulo "Perdido no limite 20" apareceria numa Força que chegou a 30, que é
     o defeito de "número certo com detalhamento errado" já nomeado na Defesa
     por atributo. */
  const tetoAplicado = {};
  /* ⚠ O `limAtivo` só chega no estágio TEMPORÁRIO (2026-10-12, Zodíaco da H
     Corp: *"Caso ele já esteja em 30, quebra o limite chegando em 32"*). Ele
     traz o limite ativo avaliado sobre o atributo PERMANENTE, que é o que
     "já esteja em 30" pergunta, e o `furaTeto` das linhas ativas que valeram.
     O estágio permanente segue como era: o limite ativo sobe o teto até o 30
     e nunca fura, para nenhuma fonte permanente pegar carona no 32. */
  const somarAtributo = (partida, res, limAtivo = null) => {
    const out = {};
    for (const k of Object.keys(partida)) {
      const total = valorCanal(res, "atributo", k);
      const limiteAtivo = limAtivo ? (limAtivo.porAlvo.limiteAtributo?.[k] || 0) : (limiteAtivoPor[k] || 0);
      const tetoSistema = limAtivo && furaTetoEm(limAtivo, k)
        ? Math.min(atributosAddon.limite(k), ATTR_LIMITE_ABSOLUTO + tetoExtra(k))
        : tetoSistemaDe(k);
      const teto = Math.min(
        attrLimiteEfetivo[k] + (folgaEquip[k] || 0) + limiteAtivo,
        tetoSistema,
      );
      tetoAplicado[k] = teto;
      out[k] = Math.min(partida[k] + total, Math.max(teto, partida[k]));
      perdaNoLimite[k] = (perdaNoLimite[k] || 0) + (partida[k] + total - out[k]);
    }
    return out;
  };

  // Estágio 1a: atributo PERMANENTE, lendo o BASE. Dentro deste estágio um
  // efeito de atributo não vê o irmão, o que evita o laço A→B→A. O Treino de
  // Atributo (estágio 0) entra aqui junto, porque também é permanente.
  const efAttrPerm = resolverExclusivos(mesclarEfeitos(
    { porAlvo: { atributo: efMontante.porAlvo.atributo || {} } },
    aplicarEfeitos(efeitosAtivos.filter(ehAtributoPermanente), montarCtx(attrBase, modBase)),
  ));
  // Este é o atributo que os PRÉ-REQUISITOS enxergam.
  /* Parte do `attrBaseFinal`, e não do `attrBase`: o segundo ainda está aparado
     pelo limite de estágio 0. Ver a nota do `attrBaseFinal`. */
  const attrPermanente = somarAtributo(attrBaseFinal, efAttrPerm);
  const modPermanente = Object.fromEntries(Object.entries(attrPermanente).map(([k, v]) => [k, mod(v)]));

  // Talentos de novo, agora com o atributo permanente: só o `inacessiveis` muda.
  const talentos = resolveTalentos(creature, {
    nd, maestria: bt, attrEff: attrPermanente, origemId, origensQualificadas: origensQuali,
    claId: creature?.core?.origem?.cla ?? null,
    especializacoes: especializacoes.escolhidas, aptidoes: aptidoesIds,
    feiticos: creature?.feiticos,
    limitesAtributo: limitesAtributoBase,
    concedidos: talentosConcedidos,
  });

  // Estágio 1b: atributo TEMPORÁRIO, por cima do permanente. Resulta no
  // atributo FINAL, que é o que a ficha mostra e o que os stats usam.
  // ⚠ O `efAttrPerm.aplicado` viaja para cá porque `atributo` é o ÚNICO canal que
  // o motor resolve em dois estágios. Sem ele, uma Habilidade Única permanente de
  // +6 de Força e um Feitiço Auxiliar temporário de +4 na mesma Força somariam
  // 10, quando a regra do pool exclusivo manda ficar com 6.
  const efAttrTemp = resolverExclusivos(
    aplicarEfeitos(
      efeitosAtivos.filter(ehAtributoTemporario),
      montarCtx(attrPermanente, modPermanente),
    ),
    efAttrPerm.aplicado,
  );
  const attrEff = somarAtributo(
    attrPermanente,
    efAttrTemp,
    limiteAtivoCom(montarCtx(attrPermanente, modPermanente)),
  );
  /* O TALISMÃ DO ÁPICE (autor, 2026-09-14): "Vira 30, se possuir a Habilidade
     Lendaria que aumenta em +2. Fica como 32." O atributo escolhido sobe até o
     TETO DO SISTEMA dele, que já é 30 ou 32 com o Aperfeiçoamento de Atributo, e
     nunca desce. Entra DEPOIS dos dois estágios porque é temporário e vale sobre
     tudo, e ANTES dos modificadores, que são o que o resto da ficha lê. A parcela
     vai para o hover, senão as fontes somariam menos que o número grande. */
  const apiceDelta = {};
  const atributoApice = equip.temApice ? atributoDoApice(combate) : null;
  if (atributoApice) {
    const alvo = Math.max(attrEff[atributoApice], tetoSistemaDe(atributoApice));
    apiceDelta[atributoApice] = alvo - attrEff[atributoApice];
    attrEff[atributoApice] = alvo;
  }
  const modFor = mod(attrEff.forca);
  const modDes = mod(attrEff.destreza);
  const modCon = mod(attrEff.constituicao);
  const modInt = mod(attrEff.inteligencia);
  const modSab = mod(attrEff.sabedoria);
  const modPre = mod(attrEff.presenca);
  const modByAttr = { forca: modFor, destreza: modDes, constituicao: modCon, inteligencia: modInt, sabedoria: modSab, presenca: modPre };
  const modTecnica = modByAttr[tecnicaAttr] ?? 0;
  const maxForDex = Math.max(modFor, modDes);                       // Z8:Z9
  const maxAllMods = Math.max(modFor, modDes, modCon, modInt, modSab, modPre); // Z8:Z13
  // A carga desceu para DEPOIS do agregado de efeitos (`ef`), logo abaixo: o
  // canal `espacosCarga` sobe o limite, e ele só existe com tudo mesclado.

  // Estágio 2: todo o resto, com o contexto REMONTADO nos atributos finais. É
  // aqui que "Defesa igual ao Mod. Força" enxerga a Força 20.
  // `efMontante` entra inteiro no agregado para os `detalhes` da UI mostrarem a
  // linha de treino como origem. O canal de atributo dele já foi consumido no
  // estágio 1a, então sai daqui para não somar duas vezes.
  const efMontanteSemAtributo = { ...efMontante, porAlvo: { ...efMontante.porAlvo } };
  delete efMontanteSemAtributo.porAlvo.atributo;
  // Os quatro primeiros já voltaram do `resolverExclusivos` com a lista vazia e
  // os vencedores somados, então a disputa que sobra aqui é só a do estágio 2. E
  // ela não precisa do `aplicado` dos estágios anteriores: `atributo` é o único
  // canal que roda antes daqui, e o filtro `ehEstagio2` justamente o exclui.
  /* O `custoPE` entra uma vez pelo `ehEstagio2`, com o contexto final.
     O passe pós-Aptidão conserva a leitura antecipada do Domínio Simples.
     O montante já entra pelo `efMontanteSemAtributo`. */
  const efSemCrescimento = resolverExclusivos(mesclarEfeitos(
    efMontanteSemAtributo, efPreContexto, efAttrPerm, efAttrTemp,
    aplicarEfeitos(efeitosAtivos.filter(ehEstagio2), montarCtx(attrEff, modByAttr)),
  ));

  // Crescimento Corporal é a única Aptidão que pode aparecer duas vezes e cada
  // aquisição escolhe o sentido da mudança. O efeito-base dela guarda somente
  // os PV (uma vez); os degraus são produzidos aqui, um por aquisição.
  //
  // O aumento próprio desta Aptidão para em Enorme (+2), conforme o texto. Esse
  // teto é calculado SÓ sobre os passos da Aptidão; outras fontes de tamanho
  // continuam somando depois. Assim uma passiva +1 não é absorvida pelo teto e
  // pode levar uma criatura Enorme por Crescimento Corporal a Colossal.
  const crescimentoId = "mal_crescimento_corporal";
  const crescimentoVezes = semEnergia ? 0 : (creature?.aptidoesAmaldicoadas ?? [])
    .filter((id) => id === crescimentoId).length;
  const crescimentoOpcoes = creature?.aptidaoOpcoesRepetidas?.[crescimentoId] ?? [];
  let passoComCrescimento = 0;
  const efeitosCrescimento = [];
  for (let indice = 0; indice < crescimentoVezes; indice++) {
    const direcao = crescimentoOpcoes[indice] === "diminuir" ? "diminuir" : "aumentar";
    const podeAplicar = direcao === "diminuir" ? passoComCrescimento > -2 : passoComCrescimento < 2;
    if (!podeAplicar) continue;
    const valor = direcao === "diminuir" ? -1 : 1;
    passoComCrescimento += valor;
    efeitosCrescimento.push({
      canal: "tamanho",
      expr: String(valor),
      origem: crescimentoId,
      nome: `Crescimento Corporal (${indice + 1}ª aquisição: ${direcao === "diminuir" ? "Diminuir" : "Aumentar"})`,
    });
  }
  const efSemTamanho = efeitosCrescimento.length
    ? mesclarEfeitos(
      efSemCrescimento,
      aplicarEfeitos(efeitosCrescimento, montarCtx(attrEff, modByAttr)),
    )
    : efSemCrescimento;

  // ---------- Tamanho (autor, 2026-08-08) ----------
  // A criatura parte de Médio e SÓ o Motor a tira de lá: tamanho não é escolha
  // de ficha, é consequência de uma Aptidão ou poder que diga que o corpo mudou.
  //
  // ⚠ TERCEIRA LISTA de efeitos, pelo mesmo motivo do Domínio e do Estilo: a
  // régua de Atletismo e Furtividade DEPENDE do tamanho, e o tamanho depende do
  // canal `tamanho`, que só fecha com o estágio 2 pronto. Resolver o tamanho
  // primeiro e mesclar a régua depois quebra o laço, e é seguro porque a régua
  // escreve num canal (`bonusPericia`) que nada do `tamanho` lê de volta.
  //
  // Entram como EFEITO, e não como número somado à mão, para o hover de fontes
  // mostrar "Colossal −10" na linha da Furtividade em vez de um −10 sem dono.
  const degrausTamanho = Math.trunc(valorCanal(efSemTamanho, "tamanho"));
  const tamanho = tamanhoPorDegraus(degrausTamanho);
  const efeitosTamanho = [];
  for (const pericia of ["atletismo", "furtividade"]) {
    if (!tamanho[pericia]) continue;
    efeitosTamanho.push({
      canal: "bonusPericia", alvo: pericia, expr: String(tamanho[pericia]),
      origem: "tamanho", nome: tamanho.label,
    });
  }
  const efSemGuarda = efeitosTamanho.length
    ? mesclarEfeitos(efSemTamanho, aplicarEfeitos(efeitosTamanho, montarCtx(attrEff, modByAttr)))
    : efSemTamanho;

  /* ---------- GUARDA INABALÁVEL (Calamidade e Beyond) ----------
     ⚠ QUARTA LISTA de efeitos, pelo mesmo motivo das três de cima (Domínio,
     Estilo e Tamanho): o bônus da Guarda SOMA na Defesa e nos cinco TRs, e ele
     mesmo sai de dois canais (`guardaBonus` e `guardaVida`) que só fecham com o
     estágio 2 pronto. Ler os canais e depois mesclar o resultado quebra o laço.

     Entra como EFEITO, e não como número somado à mão na fórmula da Defesa, por
     três motivos que valem os cinco TRs de uma vez:
       • o hover de fontes mostra "Guarda Inabalável +5" com dono, em vez de um
         +5 órfão no meio da conta;
       • o TR ROLADO na aba de Perícias já sai certo, porque `resolveTestes`
         recebe este mesmo `ef`;
       • um `bonusTR` sem `alvo` vale para os cinco (ver `valorCanalEscopos`),
         então "aumento em TRs" não vira lista de cinco escrita à mão.

     ⚠ O CORRENTE vem da SESSÃO, pelo `opcoes.guarda`, e não da ficha: quantos
     golpes já foram desgastados, se um Raio Negro a encerrou e quanta Vida
     Temporária resta são estado de mesa. Sem sessão (o criador, o Preview) a
     Guarda aparece com o TETO e sem bônus aplicado, que é a criatura em
     repouso: fora de combate não há guarda erguida. */
  /* ⚠ O PLAYER SÓ TEM GUARDA PELO ADDON (Ascendendo Além dos Céus, opcional
     do autor em 2026-10-12): *"Você recebe as Mecânicas de Guarda Alta.
     Seguindo os cálculos de uma criatura de mesmo ND."* A criatura de mesmo ND
     é a Calamidade, então o Patamar da ficha de Player não entra na conta. */
  const guardaDoAddon = ehJogador("guardaInabalavel") && regrasAddon.guardaComoCalamidade;
  const patamarGuarda = guardaDoAddon ? "calamidade" : patamar;
  // Função, e não valor: o PATAMAR_LABEL só nasce no bloco das fontes, lá embaixo.
  const rotuloGuarda = () => guardaDoAddon
    ? `${regrasAddon.fontesGuardaComoCalamidade[0]?.nome ?? "Addon"} (Calamidade)`
    : `Patamar (${PATAMAR_LABEL[patamar] ?? patamar})`;
  const guardaBonusBase = patamarGuarda === "calamidade" ? 5 : patamarGuarda === "beyond" ? 10 : 0;
  const guardaVidaBase = patamarGuarda === "calamidade" ? 5 * nd : patamarGuarda === "beyond" ? 10 * nd : 0;
  const guardaBonusMax = Math.max(0, guardaBonusBase + valorCanal(efSemGuarda, "guardaBonus"));
  const guardaVidaMax = Math.max(0, guardaVidaBase + valorCanal(efSemGuarda, "guardaVida"));
  /* ⚠ `null` no jogador, e não o objeto com `ativa: false`. Os dois esconderiam
     a Guarda da tela, porque todo leitor checa `guarda?.ativa`, mas o autor
     pediu que ela NÃO EXISTA na ficha de jogador, e um objeto de Guarda numa
     ficha que não tem Guarda é convite para alguém ler `bonusMax` dele um dia. */
  const guarda = ehJogador("guardaInabalavel") && !guardaDoAddon ? null : (() => {
    const ses = opcoes.guarda ?? {};
    const inteiroNaoNeg = (v) => Math.max(0, Math.trunc(Number(v)) || 0);
    const golpes = inteiroNaoNeg(ses.golpes);
    const vida = inteiroNaoNeg(ses.vida);
    const PASSO = 2;   // "reduzido em 2 a cada ataque ou habilidade que ele sofra"
    if (guardaBonusBase <= 0) {
      return {
        ativa: false, noAr: false, bonus: 0, bonusMax: 0,
        vida: 0, vidaMax: 0, golpes: 0, passoPorGolpe: PASSO, motivo: null,
      };
    }
    /* ⚠ O BÔNUS ZERADO PELOS GOLPES TAMBÉM QUEBRA (autor, 2026-08-26, segunda
       passada), e quebrar leva o PV Temporário junto. Antes eu havia tratado o
       desgaste como coisa separada da quebra, e é a mesma: moer o bônus até zero
       é o caminho normal de derrubar a Guarda, e é o que faz a característica
       "exigir trabalho em equipe". Dá 3 golpes no Calamidade e 5 no Beyond.

       A ordem dos motivos é a de quem chegou primeiro no caso comum, e ela põe
       os golpes ANTES da Vida de propósito: quando são eles que quebram, a Vida
       é destruída junto, e nomear "Vida Temporária" ali contaria a consequência
       em vez da causa.

       Sem sessão nenhuma a Vida é zero e a Guarda sai fora do ar, que é o certo:
       ela é erguida no início da rodada, e não na ficha. */
    const moido = PASSO * golpes >= guardaBonusMax;
    const motivo = ses.condicao ? String(ses.condicao)
      : ses.encerrada ? "Raio Negro"
      : moido ? "Bônus Zerado"
      : vida <= 0 ? "Vida Temporária" : null;
    return {
      ativa: true,
      noAr: motivo == null,
      /* A escada da planilha, indexada pelo contador de golpes: 5, 3, 1, 0 no
         Calamidade e 10, 8, 6, 4, 2, 0 no Beyond. ⚠ Os números NÃO mudaram com a
         regra nova: o degrau em que a escada chega a zero é justamente o degrau
         em que a Guarda quebra, então o `max(0, ...)` e a quebra dão o mesmo. */
      bonus: motivo == null ? Math.max(0, guardaBonusMax - PASSO * golpes) : 0,
      bonusMax: guardaBonusMax,
      vida, vidaMax: guardaVidaMax,
      golpes, passoPorGolpe: PASSO, motivo,
    };
  })();
  const efeitosGuarda = guarda?.bonus > 0
    ? [
      { canal: "defesa", expr: String(guarda.bonus), origem: "guarda", nome: "Guarda Inabalável" },
      // Sem `alvo`: `valorCanalEscopos` soma o `porCanal` em todo escopo, então
      // um efeito só cobre Reflexos, Fortitude, Vontade, Astúcia e Integridade.
      { canal: "bonusTR", expr: String(guarda.bonus), origem: "guarda", nome: "Guarda Inabalável" },
    ]
    : [];
  let ef = efeitosGuarda.length
    ? mesclarEfeitos(efSemGuarda, aplicarEfeitos(efeitosGuarda, montarCtx(attrEff, modByAttr)))
    : efSemGuarda;
  /* As CONDIÇÕES QUE PERDERAM a disputa entram só no `detalhes`, marcadas como
     suplantadas: não somam em nada (`contaNoTotal` as pula) e o hover as mostra
     riscadas, dizendo por que o -3 do Desprevenido não está na Defesa. */
  if (condicoes.suplantados.length) {
    ef = { ...ef, detalhes: [...(ef.detalhes ?? []), ...condicoes.suplantados] };
  }
  const canal = (id, alvo = null) => valorCanal(ef, id, alvo);

  /* ⚠ O CUSTO EM PE DOS ESTADOS É REDUZIDO SÓ NA EXIBIÇÃO, e por isso esta é uma
     CÓPIA. O `combate` original é montado lá em cima, antes de o Motor rodar,
     porque os estados alimentam o contexto do DSL: a redução depende dos
     efeitos, e os efeitos dependem dos estados. Reduzir na origem morderia o
     próprio rabo.

     O número do custo não entra em conta nenhuma do motor, ele é o que a pessoa
     LÊ antes de gastar. Então a ordem certa é montar o estado, rodar o Motor, e
     só então dizer quanto aquele estado custa hoje. Ver o canal `custoPE`. */
  /* O resumo do Vislumbre Celeste para o card, já resolvido: a UI não recalcula
     nada. O estado sai do `combate`, e não da criatura crua, porque é a bancada
     (ou a sessão da Ficha) que diz se os olhos estão descobertos AGORA. */
  /* ⚠ OS DOIS ESTADOS SAEM DA MESMA FONTE QUE OS EFEITOS, e não do `combate`
     resolvido. O `resolveCombate` zera tudo com a bancada desligada, e uma
     Condição Corporal não liga e desliga com a iniciativa: o card mostraria o
     bloco coberto enquanto o Motor aplica o descoberto. Ver `olhosDescobertos`. */
  const vislumbre = resolveVislumbre({
    tem: temVislumbre,
    cl: aptidao.efetivo?.cl ?? 0,
    descoberto: vislumbreDescoberto,
    fadiga: fadigaAtual(creature),
    grauOrdem: grauFeiticeiro(nd).ordem,
    nd,
  });

  const combateExibicao = {
    ...combate,
    estadosExtras: (combate.estadosExtras ?? []).map((e) => {
      if (e?.custoPE == null) return e;
      const custo = custoEmPe(e.custoPE, ef, "aptidao");
      return custo.valor === e.custoPE
        ? e
        : { ...e, custoPE: custo.valor, custoPEBase: e.custoPE, reducoesCustoPE: custo.partes };
    }),
  };
  const manipulacaoCeu = resolveManipulacaoCeu(creature, combateExibicao, aptidoesIds);

  // Funcionamento Básico da técnica, RESOLVIDO linha a linha, só para o editor
  // mostrar quanto cada expressão vale enquanto o jogador digita. É reavaliação,
  // não segunda aplicação: quem entra na conta é o `efeitosTodos` acima. Roda com
  // o contexto FINAL, então uma expressão que lê `mod_forca` vê a Força fechada.
  const ctxTecnica = montarCtx(attrEff, modByAttr);
  /* O MÁXIMO DE USOS de cada habilidade com contador (2026-09-23), no contexto
     FINAL, porque as fórmulas leem atributo fechado ("modificador de Força,
     Destreza ou Sabedoria"). Quem gasta e devolve é a sessão, e o Descansar zera
     tudo. Ver `usos` no catálogo de afty-habilidades.js. */
  const usosHabilidades = Object.fromEntries(
    (habilidades.efetivas ?? [])
      .map((id) => [id, getHabilidade(id)?.usos])
      .filter(([, u]) => u?.expr)
      .map(([id, u]) => [id, {
        max: Math.max(0, Math.trunc(evalNumberDsl(u.expr, ctxTecnica, 0))),
        recarga: u.recarga ?? "descanso",
        /* A chave da sessão leva a recarga na frente quando ela é `cena`,
           `rodada` (2026-09-28) ou `manual` (2026-10-12), a mesma convenção do
           `mesa` logo abaixo. As do Combatente são de descanso e seguem com
           `hab:<id>`. */
        chave: RECARGAS_COM_PREFIXO.includes(u.recarga) ? `${u.recarga}:hab:${id}` : `hab:${id}`,
        ...(String(u.rotulo ?? "").trim() ? { rotulo: String(u.rotulo).trim() } : {}),
      }]),
  );
  /* O MONTADOR DO GOLPE ESPECIAL (2026-09-24). O derive só diz se a ficha tem
     o Golpe e o Autossuficiente, com as herdadas como a aba Buffs: o custo e o
     pagamento são da sessão (afty-golpe-especial.js e ficha-sessao.js). */
  const comHerdadas = expandeHerdadas(habilidades.efetivas ?? []);
  const golpeEspecial = {
    disponivel: comHerdadas.includes("cmb_golpe_especial"),
    // "recebe 3 PE temporários para serem usados no ataque. Uma vez por cena,
    // você pode escolher transformar esse valor em 6."
    autossuficiente: comHerdadas.includes("cmb_autossuficiente"),
  };
  // Resultados de mesa são números consultáveis, sem inventar canais de stat.
  for (const t of estilo.conhecidas) {
    t.resultadosCalculados = (t.resultados ?? []).map((r) => ({
      label: r.label,
      valor: evalNumberDsl(r.expr, ctxTecnica, 0) * (r.porImbuicao ? t.vezes : 1),
    }));
  }
  /* ---------- CONTADOR E NÚMEROS DE MESA EM TODA ENTRADA (2026-09-28) ----------
     O `usos` que a Habilidade tinha e os `resultados` que a Técnica de Estilo
     tinha, estendidos a Talento, característica de origem e OPÇÃO de escolha
     aninhada. Nasceram com a Fórmula de Combate Entrópica, que é quase toda de
     coisa que age em aliado ou inimigo ("o aliado recebe metade do seu BT"): o
     número não é da ficha, mas o jogador precisa dele pronto na mesa (plano
     aprovado: "linha com a CD, o BT e o dado já calculados, mais um contador de
     usos"). A Habilidade ganha só os `resultados`, porque o contador dela já
     existe em `usosHabilidades`.

     ⚠ A RECARGA VIAJA NA CHAVE DA SESSÃO: `cena:` e `rodada:` na frente. A
     sessão zera por prefixo na cena nova e na virada da rodada, sem precisar do
     derive nessa hora (ver `cenaNovaDoGolpe` e `proximaRodada` em
     ficha/ficha-sessao.js). O Descansar continua zerando tudo.

     Chaves: `origem:<id>`, `talento:<id>`, `especializacao:<id>` e
     `opcao:<paiId>:<opcaoId>`, as mesmas do `item()` da Ficha. */
  const valorDeMesa = (expr) => Math.floor(evalNumberDsl(String(expr), ctxTecnica, 0));
  /* As Técnicas da Expansão com os números prontos para a tela: o que soma no
     usuário e o que estende aos aliados. ⚠ SEM o `Math.floor` do `valorDeMesa`:
     o Deslocamento Adicional é 4,5 m, e piso o faria virar 4. As expressões do
     catálogo já arredondam onde a regra manda. */
  const valorExato = (expr) => evalNumberDsl(String(expr), ctxTecnica, 0);
  for (const t of estilo.tecnicas ?? []) {
    t.numeros = t.pessoais.map((p) => ({
      efeitoId: p.efeitoId, nome: p.nome, canal: p.canal, valor: valorExato(p.expr),
    }));
    t.aliadosCalculados = t.aliados.map((a) => ({
      efeitoId: a.efeitoId, rotulo: a.rotulo, valor: valorExato(a.expr),
    }));
    // Números de mesa das modificações (a CD do Punho Divergente).
    t.mesaCalculada = (t.mesa ?? []).map((m) => ({
      efeitoId: m.efeitoId, rotulo: m.rotulo, valor: valorExato(m.expr),
    }));
  }
  const mesa = {};
  /* O contador dos Ataques com Gatilho de cada Técnica da Expansão: "um ataque
     por rodada", então a recarga é a rodada. A chave é a do item da Ficha
     (`estilo:<id>`). A Técnica inválida não ganha contador (DA-07). */
  for (const t of estilo.tecnicas ?? []) {
    if (!t.mecanicamenteValida || !(t.ataquesComGatilho > 0)) continue;
    mesa[`estilo:${t.id}`] = {
      usos: { max: t.ataquesComGatilho, recarga: "rodada", chave: `rodada:estilo:${t.id}` },
      resultados: [],
    };
  }
  /* `usos.rotulo` troca o "Usos" do contador na Ficha ("Doses"), e
     `resultados[].textos` dá NOME ao número (2026-10-12, pacote Vampiro da
     Máscara de Pedra): o valor vira o índice da lista, aparado nas pontas, e a
     Ficha mostra "Patente: Conde" em vez de "Patente: 3". O `valor` segue no
     objeto para quem precisar do número. */
  const registraMesa = (chave, entrada, { semUsos = false } = {}) => {
    const u = semUsos ? null : entrada?.usos;
    const recarga = USOS_RECARGAS.includes(u?.recarga) ? u.recarga : "descanso";
    const usos = u?.expr != null ? {
      max: Math.max(0, valorDeMesa(u.expr)),
      recarga,
      chave: RECARGAS_COM_PREFIXO.includes(recarga) ? `${recarga}:${chave}` : chave,
      ...(String(u.rotulo ?? "").trim() ? { rotulo: String(u.rotulo).trim() } : {}),
    } : null;
    const resultados = (Array.isArray(entrada?.resultados) ? entrada.resultados : [])
      .filter((r) => String(r?.label ?? "").trim() && r?.expr != null)
      .map((r) => {
        const valor = valorDeMesa(r.expr);
        const textos = Array.isArray(r.textos) ? r.textos.map((t) => String(t ?? "")) : [];
        const texto = textos.length ? textos[Math.max(0, Math.min(textos.length - 1, valor))] : "";
        return { label: String(r.label), valor, ...(texto.trim() ? { texto } : {}) };
      });
    if (usos || resultados.length) mesa[chave] = { usos, resultados };
  };
  for (const c of caracteristicasEfetivas(creature)) registraMesa(`origem:${c.id}`, c);
  /* As Características Amaldiçoadas escolhidas também (2026-10-12): a Alma
     Maldita do Vampiro tem "2 vezes por dia", e a Regeneração Vampírica
     Aprimorada, "metade do seu bônus de treinamento". A chave é a do item da
     Ficha. Id que o catálogo não conhece mais é linha morta e fica de fora. */
  for (const id of new Set(Array.isArray(creature?.caracteristicasAmaldicoadas) ? creature.caracteristicasAmaldicoadas : [])) {
    const entrada = getCaracteristicaAmaldicoada(id);
    if (entrada) registraMesa(`caracteristicaAmaldicoada:${id}`, entrada);
  }
  /* O contador da Técnica de pacote com `usos` (2026-10-11, pacote Stark: "Uma
     quantidade de vezes igual ao seu bônus de treinamento"). Mesma chave do item
     da Ficha. A inválida não ganha contador (DA-07), e o do Gatilho, que já mora
     na mesma chave, vence. */
  for (const t of estilo.tecnicas ?? []) {
    if (t.mecanicamenteValida && t.usos && !mesa[`estilo:${t.id}`]) registraMesa(`estilo:${t.id}`, t);
  }
  for (const id of talentos.escolhidas ?? []) registraMesa(`talento:${id}`, getTalento(id));
  for (const id of habilidades.efetivas ?? []) {
    registraMesa(`especializacao:${id}`, getHabilidade(id), { semUsos: true });
  }
  for (const id of altoNivel.lendarias.escolhidas ?? []) {
    registraMesa("altoNivel:len:" + id, getHabilidadeLendaria(id, creature));
  }
  const opcoesDeMesa = (mapa, pegaPai) => {
    for (const [paiId, ids] of Object.entries(mapa ?? {})) {
      const opcoes = pegaPai(paiId)?.escolha?.opcoes ?? [];
      for (const oid of Array.isArray(ids) ? ids : []) {
        const o = opcoes.find((x) => x?.id === oid);
        if (o) registraMesa(`opcao:${paiId}:${oid}`, o);
      }
    }
  };
  opcoesDeMesa(habilidades.escolhas?.mapa, getHabilidade);
  opcoesDeMesa(talentos.escolhas?.mapa, getTalento);
  /* As OPÇÕES das escolhas aninhadas de ORIGEM (2026-10-09): a chave é a mesma
     `opcao:<escolhaId>:<opcaoId>`, com o id da escolha no lugar do pai, porque
     uma característica de origem pode ter várias (`escolhas`). É o contador do
     ARMA!!! do Não-Feiticeiro ("uma vez por combate"). */
  for (const c of caracteristicasEfetivas(creature)) {
    for (const esc of [c.escolha, ...(c.escolhas ?? [])]) {
      if (!esc?.id) continue;
      for (const oid of escolhasOrigem.mapa?.[esc.id] ?? []) {
        const o = (esc.opcoes ?? []).find((x) => x?.id === oid);
        if (o) registraMesa(`opcao:${esc.id}:${oid}`, o);
      }
    }
  }
  // A Habilidade Unica da Ferramenta precisa mostrar o mesmo valor que entra no
  // Motor. O equipamento e carregado antes de os atributos fecharem, mas a
  // expressao permanece viva e e reavaliada aqui com o contexto FINAL. As
  // variaveis proprias do item, como `grau`, continuam sobrescrevendo as da
  // criatura somente para aquela expressao.
  const reavaliarUnica = (efeito) => ({
    ...efeito,
    valor: efeitoUsaDadosDanoFinal(efeito)
      ? null
      : evalNumberDsl(efeito.expr, { ...ctxTecnica, ...(efeito.contextoDsl || {}) }, 0),
  });
  const equipFinal = {
    ...equip,
    efeitosUnica: equip.efeitosUnica.map(reavaliarUnica),
    entradas: equip.entradas.map((entrada) => {
      if (!entrada.fa) return entrada;
      return {
        ...entrada,
        fa: {
          ...entrada.fa,
          habilidadeEfeitos: entrada.fa.habilidadeEfeitos.map(reavaliarUnica),
          segundaHabilidadeEfeitos: entrada.fa.segundaHabilidadeEfeitos.map(reavaliarUnica),
          // A do Aprimoramento do Espinho, pelo mesmo motivo.
          espinhoHabilidadeEfeitos: (entrada.fa.espinhoHabilidadeEfeitos ?? []).map(reavaliarUnica),
        },
      };
    }),
    // Os Acessórios Únicos são editados no card deles, e não na linha do
    // inventário: a Habilidade Única é do ACESSÓRIO, e ele pode nem estar
    // carregado. O editor lê daqui o mesmo valor que o Motor usa.
    acessoriosUnicos: equip.acessoriosUnicos.map((a) => ({
      ...a,
      habilidadeEfeitos: a.habilidadeEfeitos.map(reavaliarUnica),
      segundaHabilidadeEfeitos: a.segundaHabilidadeEfeitos.map(reavaliarUnica),
    })),
  };
  const resolverEfeitosEditaveis = (lista) => (Array.isArray(lista) ? lista : [])
    .map((e) => {
      /* A linha mirada na INVOCAÇÃO (2026-09-15) lê o catálogo do shikigami, e
         não o da criatura: os dois espaços repetem nomes de canal com sentidos
         diferentes, então o `alvoTipo` e a nota do canal errado ofereceriam à
         tela um vocabulário que não é o daquele número. */
      const naInvocacao = e?.escopo === "invocacao";
      const def = naInvocacao
        ? (INV_EFEITO_CANAIS.find((c) => c.id === e?.canal) || null)
        : (EFEITO_CANAIS.find((c) => c.id === e?.canal) || null);
      const expr = String(e?.expr ?? "").trim();
      const valorTardio = efeitoUsaDadosDanoFinal(e);
      const condicaoTardia = efeitoUsaDadosDanoFinal({ expr: e?.quando });
      if (naInvocacao) {
        /* ⚠ SEM VALOR RESOLVIDO AQUI, de propósito. A expressão é avaliada no
           contexto de CADA invocação (grau, atributos, marcadores dela), e a
           linha costuma valer para várias: um número só na tela do editor seria
           o de nenhuma delas. O valor por invocação aparece no card do
           shikigami, que é onde ele tem dono. */
        return {
          canal: e?.canal ?? "", alvo: e?.alvo ?? "", expr,
          quando: e?.quando ?? "", duracao: e?.duracao ?? "permanente",
          escopo: "invocacao",
          ...(e?.invocacaoAlvo ? { invocacaoAlvo: e.invocacaoAlvo } : {}),
          ...(e?.acaoAlvo ? { acaoAlvo: e.acaoAlvo } : {}),
          alvoTipo: def?.alvo ?? null,
          alvoObrigatorio: !!def?.alvo && !def.alvoOpcional,
          nota: def?.nota ?? null,
          valor: null,
          ativo: !!expr,
        };
      }
      return {
        canal: e?.canal ?? "", alvo: normalizarAlvoEfeito(e?.alvo) ?? "", expr,
        quando: e?.quando ?? "", duracao: e?.duracao ?? "permanente",
        // `modo` só existe nas fontes do pool exclusivo que decidem por LINHA
        // se o efeito é passivo ou de bancada (Habilidade Única, Técnica de
        // Estilo Especial). Quem não usa nunca o grava, e ele fica ausente.
        ...(e?.modo ? { modo: e.modo } : {}),
        /* ⚠ E o `semCredito` pelo mesmo motivo do `modo`: o editor LÊ este
           objeto e grava ele de volta em `core.tecnicaEfeitos`, então campo que
           não for copiado aqui se perde na primeira edição, calado. */
        ...(e?.semCredito ? { semCredito: true } : {}),
        // `alvoTipo` diz à UI qual vocabulário oferecer (atributo, perícia, tr...).
        alvoTipo: def?.alvo ?? null,
        /* O canal cujo alvo É o dado ou o gatilho não aceita "todos" (2026-10-07,
           achado M01-UI-01): sem alvo o número cairia em todo tamanho de dado. */
        alvoObrigatorio: !!def?.alvoObrigatorio,
        nota: def?.nota ?? null,
        valor: expr ? (valorTardio ? null : evalNumberDsl(expr, ctxTecnica, 0)) : 0,
        ativo: !e?.quando || condicaoTardia || evalNumberDsl(String(e.quando), ctxTecnica, 0) !== 0,
      };
    });
  const tecnicaEfeitos = resolverEfeitosEditaveis(creature?.core?.tecnicaEfeitos);
  // Um mapa por Funcionamento Básico ADICIONAL, no mesmo formato do principal:
  // cada editor precisa ver o valor e o estado das linhas dele. O principal fica
  // de fora do mapa porque já tem o `tecnicaEfeitos` acima, que meia dúzia de
  // telas lê pelo nome.
  const funcionamentoEfeitos = Object.fromEntries(
    funcionamentosDaFicha(creature)
      .filter((fb) => !fb.principal)
      .map((fb) => [fb.id, resolverEfeitosEditaveis(fb.efeitos)]),
  );
  const passivosEfeitos = Object.fromEntries(
    (Array.isArray(creature?.feiticos) ? creature.feiticos : [])
      .filter((f) => f?.tipo === "passivo")
      .map((f) => [f.id, resolverEfeitosEditaveis(f.efeitosPassivo)]),
  );
  // O editor dos Votos usa o mesmo formato resolvido do Funcionamento Básico:
  // tipo de alvo, valor atual, condição e duração. Entradas acima do BT ficam
  // visíveis para edição, mas a prévia as marca como inativas junto do motor.
  const votosEfeitos = Object.fromEntries(
    votosDaFicha(creature).mecanicos.map((voto, indice) => {
      const dentroDoBt = indice < bt;
      const resolverLado = (lado) => resolverEfeitosEditaveis(lado?.efeitos)
        .map((efeito) => (dentroDoBt ? efeito : { ...efeito, ativo: false }));
      return [voto.id, {
        beneficio: resolverLado(voto.beneficio),
        maleficio: resolverLado(voto.maleficio),
      }];
    }),
  );
  // Um mapa por Técnica de Estilo ESPECIAL, no mesmo formato: o editor do Motor
  // mostra o valor e o estado de cada linha escrita à mão. As de tabela não
  // entram, porque a expressão delas é do catálogo e não é editável.
  const estiloEfeitos = Object.fromEntries(
    estilo.conhecidas
      .filter((t) => t.tipo === "especial")
      .map((t) => [t.id, resolverEfeitosEditaveis(t.efeitos)]),
  );

  // Alma: o teto (100 + Melhoria de Alma) e o multiplicador de PV. Sai aqui, e
  // não lá em cima, porque o canal `almaMax` só existe com os efeitos mesclados.
  //
  // ⚠ NO CRIADOR os dois são o MESMO número, porque a criatura é montada íntegra
  // (o campo de Integridade saiu do formulário em 2026-07-29). EM JOGO não: a
  // fórmula do autor é `HP × (Alma.Atual / 100)`, então uma criatura com a alma
  // em 60 tem 60% do PV máximo, e o número grande da Ficha tem de cair junto. A
  // Ficha Final passa `opcoes.almaAtual`, e sem ele nada muda para o criador.
  /* ⚠ NA FICHA DE JOGADOR A ALMA NÃO É PORCENTAGEM, é uma pilha do tamanho do
     PV. Verbatim do livro: "O valor de Integridade da Alma de um personagem é
     igual ao seu máximo de Pontos de Vida. Sempre que seu máximo de Pontos de
     Vida aumentar, sua Integridade deve ser atualizada."

     Por isso `almaMult` vale 1 no jogador: a Alma dele não multiplica o PV, ela
     o ACOMPANHA. Na criatura ela segue sendo o multiplicador de sempre, com 100
     de base, e é a diferença que o autor descreveu como "igual ao Grimório
     2.5.2", onde `almaMax = hpMax`.

     ⚠ O `almaMax` do jogador não pode ser calculado aqui: ele é o PV, e o PV sai
     20 linhas abaixo. Ele é fechado logo depois do `hp`. O que sai daqui é só o
     BÔNUS, que o jogador soma em pontos e a criatura soma em porcento. */
  /* ⚠ O VERBO `almaComoAfty` DEVOLVE AO JOGADOR A ALMA DA CRIATURA (autor,
     2026-10-12): "100 Máximo + Outros". É a conta inteira, e não só o número da
     barra: com a Alma em 100 e não no PV, só a porcentagem mantém o resto
     coerente, então o canal volta a ser porcento dentro do `almaMult`, o PV
     deixa de seguir a Alma corrente, e a sessão lê o `almaPilha` publicado no
     fim para deixar de descontar a Vida no Dano na Alma. */
  const almaPilha = ehJogador("pvPePorEspecializacao") && !regrasAddon.almaComoAfty;
  const bonusAlma = canal("almaMax");
  const almaMax = almaPilha ? 0 : almaMaxBase + bonusAlma;
  const almaMult = almaPilha
    ? 1
    : (opcoes.almaAtual != null ? almaAtualDsl : almaMax) / 100;

  // Carga: mod de Força já fechado (acessório + efeitos) e o limite já somado do
  // canal `espacosCarga` (Otimização de Espaço, Suporte 2°).
  const carga = resolveCarga(equip.espacosUsados, modFor, canal("espacosCarga"));

  // ---------- HP (+ Treino de Resistência) ----------
  /* ⚠ NA FICHA DE JOGADOR O PV VEM DA CLASSE, e não do Tipo (autor, 2026-08-30).
     A primeira Especialização da lista é a INICIAL e paga o `pvPrimeiro`, e as
     demais dão `pvPorNivel` em todo nível. A ordem da lista é a régua por decisão
     do autor, entre marca explícita e maior nível.

     ⚠ O Mod. de Constituição NÃO entra aqui, e sim no `nd * modHp` logo abaixo,
     que já existia. O livro diz "além de somar novamente seu modificador de
     Constituição" em cada nível e chama isso de retroativo, o que dá
     `N × ModCon`. É exatamente o que a criatura já fazia, então a parcela é a
     mesma nos dois sistemas.

     ⚠ E o Patamar não existe no jogador, então o multiplicador é 1. */
  /* "Metade do seu Nível" é a régua que substitui a escala por Tipo em TODAS as
     fórmulas do jogador. Piso, pela regra geral do sistema. */
  const metadeDoNivel = Math.floor(nd / 2);
  const valoresDoJogador = ehJogador("valoresAdicionais");

  const classesDaFicha = especializacoes.escolhidas ?? [];
  const pvPorClasse = ehJogador("pvPePorEspecializacao");
  const hpBase = pvPorClasse
    ? classesDaFicha.reduce(
      (soma, e, i) => soma + pvDaClasse(e.id, e.nivel, { inicial: i === 0 }), 0)
    : (
      tipo === "combatente" ? 12 + (nd - 1) * 6 :
      tipo === "restringido" ? 12 * nd :
      /* misto | conjurador */ 10 + (nd - 1) * 5);
  const hpPatamarMult = pvPorClasse ? 1 : (HP_PATAMAR_MULT[patamar] ?? 1);

  /* ⚠ O HOVER TEM DE FALAR A LÍNGUA DO SISTEMA. "Base do Tipo (Restringido)"
     numa ficha de jogador nomeia um campo que ela não tem, e o número nem vem
     dali: vem da Classe. No jogador sai uma linha POR CLASSE, com o nível dela,
     que é onde o leitor confere a conta do multiclasse. */
  const linhasBaseDeClasse = (valorDe) => classesDaFicha.map((e, i) => ({
    /* O nome sai do CATÁLOGO e não de um mapa aqui: uma Classe vinda de Addon
       tem nome, e um mapa escrito à mão mostraria o id cru dela. */
    label: `${getEspecializacao(e.id)?.nome ?? e.id} ${e.nivel}${i === 0 ? " (inicial)" : ""}`,
    valor: valorDe(e, i),
  }));
  /* Qual atributo entra no PV. Constituição por padrão, e o canal `hpAtributo`
     TROCA (Addons fase 0, 8.2 do docs/afty-addons.md).

     ⚠ SUBSTITUIÇÃO, e não soma, e vale o MAIOR entre a Constituição e os
     concedidos: é o mesmo desenho do `defesaAtributo`, decidido em 2026-08-08,
     e pelo mesmo motivo. Somar pelo canal `hp` daria o mesmo número e mentiria
     no hover, com "Constituição × ND" e a fonte nova lado a lado se lendo como
     dois atributos somados. E o texto de quem troca sempre diz "você pode
     optar", então ninguém opta por piorar o próprio PV. */
  const atributosHp = ATTR_KEYS.filter((k) => valorCanal(ef, "hpAtributo", k) > 0);
  const attrHp = [...atributosHp, "constituicao"]
    .reduce((melhor, k) => ((modByAttr[k] ?? 0) > (modByAttr[melhor] ?? 0) ? k : melhor), "constituicao");
  const modHp = modByAttr[attrHp] ?? 0;
  // O bônus de item ("os seus pontos de vida máximos aumentam em 10") entra
  // ANTES da Alma e do Patamar (autor, 2026-08-01), junto do treino e do canal
  // `hp` do Motor. Num Beyond, um item de +10 vale 40.
  /* ⚠ NO JOGADOR O CANAL `almaMax` SOMA NO PV TAMBÉM. Autor, 2026-08-30: "Soma
     Pontos direto da alma virando +10 e não +10%. O quê também altera a vida
     aumentando ela em +10 junto no processo." Como a Alma dele é o PV, subir uma
     sobe a outra, e uma Melhoria de +10 vale +10 nas duas. Na criatura o mesmo
     canal continua sendo porcentagem, dentro do `almaMult`. */
  /* O canal `hpMult` (primitiva `pvEPassivas`) multiplica o PV FINAL, depois da
     Alma e do Patamar e ANTES do Dano na Alma, que é descontado do total já
     multiplicado. Piso de 1: sem fonte nenhuma o PV não muda. */
  const hpMult = Math.max(1, canal("hpMult") || 1);
  const hpCheio = Math.round(
    almaMult
    * (hpBase + nd * modHp + canal("hp") + equip.hpMaxBonus + (almaPilha ? bonusAlma : 0))
    * hpPatamarMult
    * hpMult);
  /* E aqui a Alma do jogador fecha, DEPOIS do PV e igual a ele. É a ordem que me
     fez adiar esta parte: calcular a Alma antes do PV seria calcular o PV duas
     vezes ou mentir numa das duas.

     ⚠ O máximo sai do `hpCheio`, e NÃO do `hp` logo abaixo. O máximo da Alma é o
     PV de alma ÍNTEGRA, e o `hp` já desconta o Dano na Alma: amarrar um no outro
     faria a Alma perseguir o próprio dano, mostrando 400 de 400 onde o certo é
     400 de 500, e o dano seria irrecuperável porque o teto desceria junto. */
  /* O Titã lê o PV ÍNTEGRO (`hpCheio`), e não o `hp` mais abaixo: o máximo dele
     não pode encolher com o Dano na Alma, do mesmo jeito que o máximo da Alma
     não encolhe (ver a nota do `almaMaxFinal` logo abaixo). */
  const titaColosso = resolveTita(creature, hpCheio);
  const almaMaxFinal = almaPilha ? hpCheio : almaMax;
  /* ⚠ NO JOGADOR O PV MÁXIMO É A ALMA CORRENTE (autor, 2026-09-18): *"Vida Máxima
     de Jogador é igual a Alma Atual. E Dano na Alma também é Dano na Vida."* Com
     500 de PV e 100 de Dano na Alma, a ficha fica com 400 de 500 de Alma e 400 de
     400 de Vida. A outra metade da regra (o PV CORRENTE cai o mesmo tanto) é da
     sessão, e não daqui: ver `aplicaDanoNaAlma` em `ficha/ficha-sessao.js`.

     Na criatura o desconto não se repete, e não é isenção: lá a Alma é
     PORCENTAGEM e já multiplicou o PV no `almaMult` acima. Descontar de novo aqui
     cobraria a mesma perda duas vezes.

     Sem `opcoes.almaAtual` nada muda, que é a mesma promessa do `almaMult`: o
     criador monta a ficha com a alma íntegra e nunca vê este ramo. */
  const hpAntesMultiplicador = almaPilha && opcoes.almaAtual != null
    ? Math.min(almaAtualDsl, hpCheio)
    : hpCheio;
  /* Multiplicadores finais de Addon não mudam a Integridade nem viram base para
     efeitos que consultam o PV máximo. Eles alteram somente o PV resultante. */
  let hp = Math.round(hpAntesMultiplicador * regrasAddon.multiplicadorPvFinal);
  const danoNaAlma = hpCheio - hpAntesMultiplicador;
  // O máximo do Player só é conhecido depois do PV. Os estados da Alma usam
  // a fração atual desse máximo, inclusive quando o máximo da criatura passa de 100.
  const efeitosAlma = efeitosDaAlmaAtual(
    opcoes.almaAtual == null ? almaMaxFinal : almaAtualDsl,
    almaMaxFinal,
  );
  if (efeitosAlma.length) {
    ef = mesclarEfeitos(ef, aplicarEfeitos(efeitosAlma, montarCtx(attrEff, modByAttr)));
  }

  // O bônus de luta é a jogada normal de Corpo a Corpo, antes do próprio
  // Fluxo (autor, 2026-09-21). Reutilizar o resolver mantém a mesma escala,
  // atributo, treino e fontes da aba Perícias, sem realimentar o acerto.
  if (combate.fluxoInvencivel) {
    const acertoNormal = resolveTestes(creature, {
      restricaoDefinitiva: expandeHerdadas(habilidades.efetivas).includes("res_restricao_definitiva"),
      nd, bt, mods: modByAttr, tecnicaAttr, sistema, efeitos: ef,
    }).ataques.find((a) => a.id === "corpo")?.bonus ?? 0;
    const efeitosFluxo = [
      { canal: "bonusAcerto", expr: String(Math.floor(acertoNormal / 2)) },
      // Dano de ataque: cobre o desarmado e todas as armas, sem conceder
      // dano a Feitiços que só exigem um teste de resistência.
      { canal: "danoBonus", alvo: "basico", expr: String(acertoNormal) },
      { canal: "danoBonus", alvo: "arma", expr: String(acertoNormal) },
    ].map((e) => ({ ...e, origem: "api_fluxo_invencivel",
      nome: "Fluxo Invencível", duracao: "temporaria" }));
    ef = mesclarEfeitos(ef, aplicarEfeitos(efeitosFluxo, montarCtx(attrEff, modByAttr)));
  }

  // ---------- PE (+ Treinos de Compreensão/Controle de Energia/…) ----------
  // UMA pilha só, para todo mundo. O Restringido a chama de Ponto de Estamina
  // (ou vigor) e os outros de Ponto de Energia, mas a abreviação é PE nos dois
  // casos e a conta é a mesma. Por isso a base do Restringido bate na régua com
  // o texto de Restrito pelos Céus: "você inicia com 4 pontos de estamina, e
  // recebe mais 4 a cada nível" = 4 × ND, igual à do Combatente. A habilidade
  // NÃO soma esses 4 × ND de novo (ver res_restrito_pelos_ceus).
  /* ⚠ TAMBÉM POR CLASSE no jogador, somando os níveis de cada uma. Sem o Mod. de
     Técnica, que é parcela da FICHA e entra logo abaixo. */
  const peBase = pvPorClasse
    ? classesDaFicha.reduce((soma, e) => soma + peDaClasse(e.id, e.nivel), 0)
    : (
    tipo === "conjurador" ? 6 * nd :
    tipo === "misto" ? 5 * nd :
    /* combatente | restringido */ 4 * nd);
  // A Quantidade de PE mede a energia amaldiçoada com que se nasce, e o
  // Restringido não tem nenhuma: o seletor some do formulário e a parcela é 0.
  const peQnt = semEnergia ? 0 :
    qntPE === "muito_pouca" ? -nd :
    qntPE === "pouca" ? -Math.floor(nd / 2) :
    qntPE === "grande" ? Math.floor(nd / 2) :
    qntPE === "muito_grande" ? nd : 0;
  /* A Quantidade de PE é campo só de criatura (autor, 2026-08-30), então o
     jogador não tem o ajuste. O +ND do Raio Negro chega pelo canal `pe`, que é
     o mesmo nos dois. */
  const peQntEfetivo = ehJogador("quantidadeDePE") ? 0 : peQnt;
  /* ⚠ UMA ÚNICA VEZ, mesmo com duas classes que dão o benefício. Verbatim do
     livro: "Certas Especializações permitem que um personagem some um
     modificador de atributo uma única vez ao seu total." Lutador e Combatente
     não somam, e na criatura todo Tipo soma. */
  const modTecnicaNoPE = pvPorClasse
    ? (peModTecnicaDaFicha(classesDaFicha.map((e) => e.id)) ? modTecnica : 0)
    : modTecnica;
  /* ⚠ A PASSIVA ENCOLHE O POOL, e é a única parcela do PE que sai da lista de
     Feitiços. Ela entra AQUI, e não pelo canal `pe`, por duas razões. A primeira
     é que o canal é do Motor e esta não é regra de habilidade nenhuma, é regra
     do tipo de Feitiço. A segunda é ordem: `feiticosLista` só nasce umas linhas
     abaixo e `derived.feiticos` bem mais adiante, e o custo POR USO de um
     Feitiço já depende do PE. Ler o cru resolve sem inverter nada, porque o
     dobro do nível não precisa do Feitiço calculado.

     Só na Ficha de Jogador. Ver a divergência `passivaCustaPeMaximo`. */
  // A reserva continua com a Técnica perdida ou fora de campo (autor, 2026-10-03).
  const passivasNoPeBrutas = peMaximoDasPassivas(creature?.feiticos, sistema);
  /* ⚠ DUAS PORTAS PARA A MESMA ISENÇÃO, juntadas no pull de 2026-09-21. Elas
     nasceram em paralelo e fazem a mesma coisa: o `regrasAfty` de Addon ou de
     Voto (`passivasSemCustoPeMaximo`, Regras Grimorio e Santo da Espada) e o
     canal `passivaSemCusto` do Motor (primitiva `pvEPassivas`, Vida Dobrada).
     Qualquer uma isenta TODA Passiva do PE Máximo, e `passivasIsentas` é a
     resposta única que o resto do código lê. */
  const passivasIsentas = passivasSemCustoPeMaximo || canal("passivaSemCusto") > 0;
  const passivasNoPe = passivasIsentas
    ? { total: 0, linhas: [] }
    : passivasNoPeBrutas;
  /* ⚠ SEM PISO, de propósito (autor, 2026-09-09). Passivas caras podem levar o
     PE Máximo abaixo de zero e o criador mostra o número como ele é. Quem apara
     é a pilha CORRENTE da sessão, que é outra coisa e já tinha piso zero. */
  const peAntesMultiplicador = peBase + peQntEfetivo + modTecnicaNoPE + canal("pe") - passivasNoPe.total;
  const multiplicadorPeDosVotos = regrasAddon.ignoraMultiplicadorPeMaximoDeVotos
    ? 1
    : regrasVotos.multiplicadorPeMaximo;
  /* O canal `peMult` (2026-10-11, Voto O Covarde do pacote Stark: ×0,6 com
     medo, ×1,4 depois de superá-lo). As fontes MULTIPLICAM entre si, e cada uma
     sai do detalhamento para o hover dizer de onde veio. */
  const fontesPeMult = detalhesDoCanal(ef, "peMult").filter((d) => Number(d.valor) > 0);
  const peMultMotor = fontesPeMult.reduce((p, d) => p * Number(d.valor), 1);
  const multiplicadorPeMaximo = regrasAddon.multiplicadorPeMaximo * multiplicadorPeDosVotos * peMultMotor;
  const peOriginal = Math.floor(peAntesMultiplicador * multiplicadorPeMaximo);
  const pe = bloodfeast.tem ? 0 : peOriginal;
  if (bloodfeast.tem) hp += peOriginal * 3 - bloodfeast.custoMaximo;
  const efeitosPoderSangue = efeitosPoderDoSangue(bloodfeast, opcoes.vidaAtual, hp);
  if (efeitosPoderSangue.length) ef = mesclarEfeitos(ef, aplicarEfeitos(efeitosPoderSangue, montarCtx(attrEff, modByAttr)));

  /* ⚠ A RESISTÊNCIA PARCIAL SAIU DO AFTY em 2026-09-21, a pedido do autor, nos
     dois sistemas (no jogador ela já não existia). Era +1 por degrau de ND no
     Calamidade e no Beyond, e não tinha fonte no Motor: o canal `resParcial`
     estava declarado e nada o lia. A 2.5.2 continua com a dela. */


  // ---------- Movimento (+ Treino de Agilidade, - sobrecarga) ----------
  /* ⚠ O jogador começa com 9 e mais nada. A criatura soma
     `maior(ModFor, ModDes) × 1,5`, que o livro do jogador não tem: lá o
     Deslocamento sobe por habilidade e equipamento, e não por atributo. */
  const movimentoBase = 9 + (valoresDoJogador ? 0 : maxForDex * 1.5)
    + carga.movimento + canal("movimento");
  const movimentoMult = Math.max(1, canal("movimentoMult") || 1);
  const movimentoSemCondicao = movimentoBase * movimentoMult;
  /* ⚠ AS CONDIÇÕES DE MOVIMENTO NÃO SOMAM, elas TRANSFORMAM o valor final (Lento
     e Enredado pela metade, Caído até 4,5m, Sofrendo -3m, Imóvel zero), e entre
     elas vale o resultado MENOR. Por isso ficam fora do Motor e entram depois do
     multiplicador: "toda forma de movimento é reduzida pela metade". */
  const movimentoCondicao = condicoes.movimento(movimentoSemCondicao);
  const movimento = movimentoCondicao.valor;

  // ---------- Deslocamento de Voo (2026-10-09) ----------
  /* Só existe com fonte (canal `voo`, aberto com a origem Herdeiro Celeste):
     zero é não voar, e a Ficha esconde a linha. Passa pelo mesmo multiplicador e
     pelas mesmas condições do movimento (Lento: "Toda forma de movimento"), e o
     Caído o zera ("Um personagem caído que esteja voando imediatamente perde
     seu deslocamento de voo"). O multiplicador valer no voo é leitura de "Seu
     movimento dobra", registrada em `a-fazer.md`. */
  const vooBase = Math.max(0, canal("voo"));
  const vooCondicao = vooBase > 0
    ? condicoes.movimento(vooBase * movimentoMult, { voo: true })
    : { valor: 0, partes: [], fonte: null };
  const voo = vooCondicao.valor;

  // ---------- RD Geral ----------
  /* ⚠ A BASE zera no jogador, e só ela. Autor, 2026-08-30: "Começa em 0. E é
     recebida por Itens, Especializações, Aptidões e outras fontes." O bônus de
     equipamento e os canais seguem somando, então o jogador não fica sem RD, e
     sim sem RD DE GRAÇA. */
  const rdSemBase = ehJogador("rdBase");
  const rdGeralBase = rdSemBase ? 0 : (
    tipo === "conjurador" ? (nd >= 10 ? Math.floor(nd / 2) : 0) :
    tipo === "misto" ? (nd >= 10 ? nd : Math.floor(nd / 2)) :
    /* combatente | restringido */ (nd >= 10 ? maxAllMods : 0) + nd);
  /* ⚠ FRAGILIZADO ZERA TODA RD (Geral, Específica, Física, a da Alma e a por
     tipo), e não subtrai: "não pode ter sua Redução de Dano aumentada". O zero
     entra no fim de cada uma, e o hover leva a parcela negativa com o nome da
     condição para as fontes fecharem no total. */
  const fragilizado = condicoes.fragilizado;
  /* O canal `rdEscudo` (2026-10-11, Treino de Escudo do pacote Stark: "Seu escudo
     aumenta a RD física dele em 5") soma na RD do escudo, que mora em RD Geral
     na criatura e em RD Física no jogador, igual ao pseudo-canal do encantamento
     Reforçado. Sem escudo equipado ele não vale. */
  const escudoNaMao = equip.entradas.some((e) => e.tipo === "escudo" && e.equipado);
  const rdEscudoMotor = escudoNaMao ? canal("rdEscudo") : 0;
  const pilhaDoEscudo = canalRdEscudo(sistema);
  const rdGeralSemCondicao = rdGeralBase + equip.rdGeralBonus + canal("rdGeral")
    + (pilhaDoEscudo === "rdGeral" ? rdEscudoMotor : 0);
  const rdGeral = fragilizado ? 0 : rdGeralSemCondicao;

  // ---------- RD Específico ----------
  const rdEspecificoSemCondicao = rdSemBase ? canal("rdEspecifico") : (
    tipo === "conjurador" ? modTecnica :
    tipo === "misto" ? (nd >= 10 ? 2 * modTecnica : modTecnica) : 0);
  const rdEspecifico = fragilizado ? 0 : rdEspecificoSemCondicao;

  // ---------- RD a Alma ----------
  // A RD Geral vale para todo tipo de dano EXCETO alma, então o Dano na Alma
  // tem canal próprio (autor, 2026-07-29). Nenhum Tipo nem Patamar concede base:
  // só existe quem tem um poder que dá (hoje o Talento Alma Inquebrável).
  const rdAlmaSemCondicao = canal("rdAlma");
  const rdAlma = fragilizado ? 0 : rdAlmaSemCondicao;
  const ataquesExtras = Math.max(0, Math.trunc(canal("ataquesExtras")));

  // ---------- CD ----------
  // O DIVISOR fica numa constante porque ele é o que a UI mostra como fonte do
  // valor ("Nível ÷ 1,75"), e não o nome da escala.
  const divisorCD =
    tipo === "conjurador" ? 1.25 :
    tipo === "misto" ? 1.5 :
    /* combatente | restringido */ 1.75;
  const cdTipo = INT(nd / divisorCD);
  /* No jogador a escala por Tipo vira a metade do nível. O BT continua, porque
     o texto do livro em afty-schema.js diz "10 + metade do nível + mod de um
     atributo + BT + outros". */
  const cdEscala = valoresDoJogador ? metadeDoNivel : cdTipo;
  const cd = 10 + cdEscala + (modTecnica + bt) + equip.cdBonus + canal("cd");
  /* A CD dos FEITIÇOS: a CD Amaldiçoada mais o canal `cdFeitico` (2026-10-08,
     DA-13), que é onde a Amplificação de Técnica da Expansão escreve. A CD de
     Aptidão e de Habilidade continua sendo a `cd`. */
  const cdFeitico = cd + canal("cdFeitico");

  // ---------- Aba Habilidades: Feitiços + Habilidades Gerais ----------
  // Contador ÚNICO para os dois (autor, 2026-07-26): dobro da Maestria, +2 no
  // Desafio, +4 na Calamidade, triplo da Maestria no Beyond. Substituiu o
  // antigo totalFeiticos(nd). A CD base dos Feitiços é a CD de Feitiçaria da
  // criatura (acima), que já usa o Atributo Principal da Técnica
  // (core.tecnicaAttr) e a Maestria. A criação de cada Feitiço só a desloca.
  // (`gerais` já foi resolvido lá em cima, junto dos outros catálogos.)
  // ⚠ `creature?.` e não `creature.`: era o ÚNICO acesso cru sobrando no
  // arquivo, e `deriveAfty(null)` morria aqui em vez de devolver a ficha vazia.
  // Achado em 2026-08-20 pelos asserts de ficha suja, e é anterior a eles.
  const feiticosLista = Array.isArray(creature?.feiticos) ? creature.feiticos : [];
  /* ⚠ A TÉCNICA MÁXIMA OFICIAL NÃO GASTA VAGA DE FEITIÇO (autor, 2026-10-08): ela
     tem a vaga exclusiva `vagasTecnicaMaxima`, contada em `tecnicasMaximas` lá
     embaixo. A LEGACY (gravada antes, sem a marca) segue no orçamento comum,
     como sempre gastou (DA-02). */
  const feiticosGastos = feiticosLista.filter((f) => !f.variacaoDe && !ehTecnicaMaximaOficial(f)).length;
  // ⚠ A Técnica de Estilo LEGACY gasta o MESMO caixa que o Feitiço (autor,
  // 2026-08-07): "Consome o Contador de Habilidades. E Talentos e coisas do
  // gênero que aumentam isso... só aumentam o contador de habilidades para
  // Estilos." Para efeito de orçamento ela É um Feitiço, inclusive na vaga
  // exclusiva do canal `vagasFeitico`. A regra de 2026-08-07 foi revogada em
  // 2026-10-04 (DA-03) e vale só para as Técnicas `legacy`, que seguem
  // calculando como antes (DA-05). `estilo.gastos` conta só elas.
  //
  // As duas listas não convivem numa ficha bem montada (o Estilo é do Sem
  // Técnica, que não tem Feitiço), mas somar é mais honesto que escolher uma:
  // quem trocou de origem vê o excesso em vez de o excesso sumir calado.
  const criacoesGastas = feiticosGastos + estilo.gastos;
  /* ⚠ AS TÉCNICAS DA EXPANSÃO TÊM PROGRESSÃO PRÓPRIA (autor, 2026-10-04, DA-03):
     2 no Nível 4 e +1 em 7, 10, 13, 16 e 19, sem gastar Habilidade, Talento nem
     slot genérico. A vaga exclusiva `vagasEstilo` ("Técnica de Estilo
     adicional" no texto de todo concessor dela) soma em cima da progressão.

     ⚠ A VAGA EXCLUSIVA É UMA SÓ PARA AS DUAS REGRAS. As Técnicas da Expansão a
     usam primeiro, porque ela é a única pilha que alcança as duas. O que
     sobrar dela segue para as `legacy` exatamente como antes: uma ficha sem
     Técnica da Expansão vê o mesmo número de sempre, byte a byte. */
  // A progressão e a vaga exclusiva já saem fechadas do `resolveEstilos`, que
  // precisa delas ANTES de emitir os efeitos (ver o `estiloCtx`).
  //
  // Vaga EXCLUSIVA de Técnica de Estilo (autor, 2026-08-22). Mais estreita que
  // a de Feitiço, então ela é gasta PRIMEIRO: quem tem as duas usaria a de
  // Estilo numa Técnica de Estilo de qualquer jeito, e deixar a mais larga para
  // o final é o que faz o Feitiço ainda caber nela. Daqui para baixo é só o
  // que as Técnicas da Expansão deixaram.
  const vagasEstilo = estilo.vagasEstiloSobra;
  const estilosNoExclusivo = Math.min(estilo.gastos, vagasEstilo);
  const estiloForaDoExclusivo = estilo.gastos - estilosNoExclusivo;
  // ⚠ O contador comum pode ser MULTIPLICADO pela origem. Só os Gêmeos têm
  // isso hoje: metade com o irmão vivo, uma vez e meia depois da morte dele.
  // Arredonda para baixo, como todo o resto do Afty.
  const contadorBase = contadorHabilidades(bt, patamar);
  const fatorSlots = fatorSlotsHabilidade(creature);
  // `let`: a Segunda Habilidade Única preenchida desconta daqui na criatura.
  let contadorComum = Math.floor(contadorBase * fatorSlots);
  // As fontes do contador, para o hover poder dizer de onde o número veio. Sem
  // isso o Gêmeo vê metade das vagas e nada explicando.
  const partesContador = [
    { label: "Maestria e Patamar", valor: contadorBase },
    ...(fatorSlots !== 1
      ? [{
        label: creature?.core?.origem?.irmaoMorto ? "Gêmeos: irmão morto" : "Gêmeos: irmão vivo",
        texto: `× ${String(fatorSlots).replace(".", ",")}`,
      }]
      : []),
  ];
  // Vagas EXCLUSIVAS de Feitiço (autor, 2026-07-28): "Você fornece um Slot de
  // Habilidade somente para Feitiços, não podendo ser usada em Habilidades
  // Gerais". Hoje só a Lendária Dominância em Técnica concede. Os Feitiços
  // gastam PRIMEIRO as exclusivas, e só o que sobrar cai no contador comum.
  const vagasFeitico = canal("vagasFeitico");
  /* ⚠ NA FICHA DE JOGADOR O FEITIÇO TEM CAIXA PRÓPRIO (autor, 2026-08-31), com a
     progressão por nível do livro. Ver `progressaoDeFeiticos` em afty-sistema.js
     e `totalFeiticosJogador` em afty-feiticos.js.

     ⚠ ELE É UMA TERCEIRA PRÉ-PILHA, e não uma parcela do contador comum. A ordem
     de gasto vai da pilha mais ESTREITA para a mais LARGA, e por isso a nova
     entra entre a de Estilo e a de Feitiço:

       1. vagasEstilo    só Técnica de Estilo
       2. orcamentoFeitico  só Feitiço, e só no jogador
       3. vagasFeitico   Feitiço ou Técnica de Estilo
       4. contador comum  qualquer um dos três, mais as Habilidades Gerais

     Assim os sete concessores de `vagasFeitico` do livro (Afinidade com Técnica,
     Clã Gojo, Nova Habilidade, Dominância em Técnica, Inato, Reversão de Técnica
     e Extração de Potencial) seguem valendo no jogador sem uma linha de código a
     mais: eles viram a sobra do orçamento próprio, em vez de morrer junto com o
     contador único.

     ⚠ Na CRIATURA isto vale ZERO, e a etapa 2 é um `Math.min` com zero. É o que
     mantém o Afty byte a byte como estava. */
  /* ⚠ O PORTÃO ESTÁ NA PRIMEIRA FRASE DA REGRA, e não é invenção minha: "Todo
     usuário de energia amaldiçoada começa com uma certa quantidade de Feitiços".
     O Restringido não é um ("nascem com uma quantidade quase nula de energia"),
     e é a mesma trava que já zera as Aptidões dele lá em cima. Sem isto ele
     derivaria um orçamento de 19 Feitiços que a tela nem mostra, porque o card
     de Feitiços já não é montado para ele.

     ⚠ O SEM TÉCNICA NÃO ENTRA NESTA TRAVA. Ele TEM energia amaldiçoada, só não
     tem técnica, e o que ocupa o lugar dos Feitiços dele é o Estilo das Sombras.
     O número dele é a progressão própria das Técnicas da Expansão (2026-10-04,
     `estilo.progressao` logo acima), igual nos dois sistemas. */
  const feiticoTemCaixaProprio = ehJogador("progressaoDeFeiticos") && !semEnergia;
  /* ⚠ A SEGUNDA HABILIDADE ÚNICA PREENCHIDA CUSTA UM SLOT DE FEITIÇO (autor,
     2026-09-16, Addon Benção do Grão Mestre da Forja): "Eu perco um Slot de
     Feitiço. Já que estou efetivamente colocando Feitiços no objeto". Um por
     item, com o item guardado também, e nos DOIS sistemas. O Slot sai da pilha
     em que o Feitiço daquela ficha gasta: o orçamento próprio no jogador, o
     contador comum na criatura. Cada item vira uma parcela negativa com o nome
     dele, que é o aviso no hover. */
  /* ⚠ "Segunda Única", E NÃO O NOME INTEIRO (2026-09-18). Este rótulo só
     alimenta o hover, e uma ficha com muitos Acessórios Únicos repete o sufixo
     em toda linha: com o nome inteiro, "Anel da Atração em Combate (Segunda
     Habilidade Única)" estourava o teto do painel e empurrava o "−1" para fora
     da borda. O painel agora quebra a linha em vez de vazar (ver `fontes.jsx`),
     e encurtar aqui é o que faz a quebra quase nunca precisar acontecer.
     Mesma abreviação que o card Efeitos Equipados já usa (`NOTA_CURTA`, no
     AftyCreatureBuilder), então os dois lugares falam igual. */
  const partesSegundaUnica = (equip.segundasUnicasPreenchidas ?? [])
    .map((s) => ({ label: `${s.nome} (Segunda Única)`, valor: -1 }));
  const slotsDaSegundaUnica = partesSegundaUnica.length;
  const progressaoFeitico = feiticoTemCaixaProprio
    ? totalFeiticosJogador(nd, {
      conjuracaoAprimorada: habilidades.efetivas.includes(CONJURACAO_APRIMORADA_ID),
    })
    : { total: 0, partes: [] };
  const orcamentoFeitico = feiticoTemCaixaProprio
    ? {
      total: progressaoFeitico.total - slotsDaSegundaUnica,
      partes: [...progressaoFeitico.partes, ...partesSegundaUnica],
    }
    : progressaoFeitico;
  if (!feiticoTemCaixaProprio && slotsDaSegundaUnica) {
    contadorComum -= slotsDaSegundaUnica;
    partesContador.push(...partesSegundaUnica);
  }
  /* O total pode ficar NEGATIVO (dois itens num orçamento de 1), e é o certo:
     as parcelas continuam somando o total, e o medidor fica vermelho. Só a
     conta de quantos Feitiços cabem apara em zero. */
  const vagasVariacao = Math.max(0, Math.trunc(canal("vagasVariacao")));
  const variacoesUsadas = Math.min(vagasVariacao, feiticosLista.filter((f) => !f.variacaoDe && f.variacaoDeTecnica).length);
  const feiticosSemVariacoesExclusivas = feiticosGastos - variacoesUsadas;
  const feiticosNoProprio = Math.min(feiticosSemVariacoesExclusivas, Math.max(0, orcamentoFeitico.total));
  const feiticoForaDoProprio = feiticosSemVariacoesExclusivas - feiticosNoProprio;
  /* A vaga de Feitiço serve às DUAS famílias (a nota do canal diz "Feitiço,
     Estilo das Sombras ou Habilidade Marcial"), então elas a dividem. A Técnica
     de Estilo pega primeiro pela mesma razão que ela pega a de Estilo antes:
     deixar a pilha mais larga para o final é o que faz o Feitiço ainda caber
     nela. Na criatura a soma das duas parcelas dá exatamente o
     `min(criações fora do Estilo, vagasFeitico)` de antes. */
  const estiloNaVagaDeFeitico = Math.min(estiloForaDoExclusivo, vagasFeitico);
  const feiticoNaVagaDeFeitico = Math.min(feiticoForaDoProprio, vagasFeitico - estiloNaVagaDeFeitico);
  const feiticosNoExclusivo = estiloNaVagaDeFeitico + feiticoNaVagaDeFeitico;
  const estiloForaDeTudo = estiloForaDoExclusivo - estiloNaVagaDeFeitico;
  const feiticoForaDeTudo = feiticoForaDoProprio - feiticoNaVagaDeFeitico;
  /* ⚠ NO JOGADOR O FEITIÇO NÃO TRANSBORDA PARA O CONTADOR COMUM. Os dois
     orçamentos são SEPARADOS (autor, 2026-08-31), e deixar o excesso cair no
     comum daria ao Conjurador um segundo orçamento escondido: no jogador não
     existe Habilidade Geral, então o comum não tem outro dono e sobraria inteiro
     para absorver o que o orçamento próprio recusou. O excesso vira AVISO, que é
     o que a regra "só resultado e aviso" pede.

     Na criatura os dois caem no comum, como sempre caíram. */
  const gastosNoComum = estiloForaDeTudo
    + (feiticoTemCaixaProprio ? 0 : feiticoForaDeTudo)
    + gerais.gastos;
  const contadorTotal = contadorComum + vagasFeitico + vagasEstilo + vagasVariacao + orcamentoFeitico.total;
  const contadorGastos = criacoesGastas + gerais.gastos;
  const orcamentoHabilidades = {
    total: contadorTotal,
    comum: contadorComum,
    partesComum: partesContador,
    /* Orçamento PRÓPRIO de Feitiço do jogador, com a progressão do livro. Zero
       na criatura, e a UI usa justamente o zero para saber qual medidor
       desenhar: quem tem caixa próprio não mostra o contador comum, que ali não
       tem dono nenhum. */
    exclusivasVariacao: vagasVariacao,
    exclusivasVariacaoUsadas: variacoesUsadas,
    proprioFeitico: orcamentoFeitico.total,
    /* Se o caixa próprio EXISTE, separado do total: com a Segunda Habilidade
       Única ele pode chegar a zero ou menos, e a UI que perguntava `total > 0`
       trocaria o medidor de Feitiços pelo de Habilidades. */
    proprioFeiticoAtivo: feiticoTemCaixaProprio,
    proprioFeiticoPartes: orcamentoFeitico.partes,
    proprioFeiticoUsado: feiticosNoProprio,
    /* O Feitiço estourou o caixa dele e as vagas exclusivas. Separado do
       `excedeu`, que mede o contador comum: no jogador os dois nunca são a mesma
       pergunta, e um Conjurador tem sempre `excedeu: false` porque não gasta o
       comum. */
    excedeuFeitico: feiticoTemCaixaProprio && (feiticoForaDeTudo > 0 || orcamentoFeitico.total < 0),
    exclusivasFeitico: vagasFeitico,
    exclusivasUsadas: feiticosNoExclusivo,
    exclusivasEstilo: vagasEstilo,
    exclusivasEstiloUsadas: estilosNoExclusivo,
    feiticos: feiticosGastos,
    // Separado do `feiticos` de propósito: os dois gastam o mesmo caixa, mas o
    // card que mostra cada número é outro.
    estilos: estilo.gastos,
    gerais: gerais.gastos,
    gastos: contadorGastos,
    gastosNoComum,
    restante: contadorTotal - contadorGastos,
    // O excesso é medido no contador COMUM: uma vaga exclusiva sobrando não
    // libera Habilidade Geral nenhuma.
    excedeu: gastosNoComum > contadorComum,
  };
  // ⚠ O contexto virou VARIÁVEL porque agora dois caminhos precisam dele: a
  // lista pronta e o `comLiberacao` lá embaixo, que refaz UM Feitiço com as
  // melhorias de Liberação Máxima declaradas na mesa. Duas cópias do objeto
  // divergiriam no primeiro campo novo (e este já tem quinze).
  const ctxFeiticos = {
    nd,
    nivelConjurador,
    cdBase: cdFeitico,
    modTecnica,
    efeitos: ef,
    efeitosLinhaDano,
    contextoDsl: ctxTecnica,
    bonusTreinamento: bt,
    combate,
    habilidades: habilidades.efetivas,
    reducaoSustentacao: habilidades.efetivas.includes("cnj_sustentacao_mestre") ? 1 : 0,
    ultimoFeiticoDanoId: opcoes.ultimoFeiticoDanoId ?? null,
    rituais: opcoes.rituais ?? {},
    usosRitualista: Math.max(0, Math.trunc(Number(opcoes.usosRitualista) || 0)),
    limiteRitualista: Math.floor(bt / 2),
    ritualAtual: opcoes.ritualAtual ?? null,
    rituaisSemTeste: opcoes.rituaisSemTeste ?? {},
    beneficiosRitualDominio,
    amplificacaoDominio,
    passivasSemCustoPeMaximo,
    temEnergiaReversa: aptidoesIds.includes("energia_reversa"),
    invocacoes: Array.isArray(creature?.invocacoes) ? creature.invocacoes : [],
    vidaAtual: opcoes.vidaAtual ?? null,
    /* ⚠ ENTROU EM 2026-09-09, pela Passiva. É o único campo daqui que não é
       número nem lista da ficha, e existe porque o custo em PE Máximo da
       Passiva é divergência: sem ele a linha diria que a criatura paga. */
    sistema,
    passivasIsentas,
    vagasVariacao,
  };
  /* ⚠ A ABA DE FEITIÇOS É DECISÃO DE MOTOR, e não de JSX (2026-09-07). O criador
     ramifica o layout inteiro por origem, e enquanto "quem conjura" era regra
     fixa a trava podia morar lá dentro. Com o `libera: ["feiticosRestritos"]` de
     Addon ela passou a mudar, e uma trava de tela que muda e ninguém mede é
     exatamente a quarta trava do Estilo das Sombras. Ver `mostraCardFeiticos`. */
  const feiticosLiberados = liberacoes.includes("feiticosRestritos");
  let feiticos = {
    nivelMax: acessoFeitico,
    nivelConjurador,
    gastos: feiticosGastos,
    cdBase: cdFeitico,
    /* Os tipos que esta criatura pode criar, e se o card aparece. Vazio quer
       dizer "não cria nenhum": é o Restringido e o Sem Técnica sem o Addon.
       Pela MÃE, então a variação do Sem Técnica também não cria. */
    /* A origem sem Energia Amaldiçoada (2026-10-09) não conjura, como o
       Restringido: só o Addon com `feiticosRestritos` abre os dois tipos dele. */
    tiposPermitidos: tiposFeiticoPermitidos(semEnergiaDaOrigem ? "restringido" : origemMae(core?.origem?.id ?? null), feiticosLiberados),
    liberado: feiticosLiberados,
    mostraCard: mostraCardFeiticos(semEnergiaDaOrigem ? "restringido" : origemMae(core?.origem?.id ?? null), {
      liberado: feiticosLiberados,
      temFeiticos: feiticosLista.length > 0,
    }),
    // Resumo pronto de cada Feitiço, para o Preview só exibir (mesma convenção
    // do `resumoDominios`: a UI não recalcula nada). O card da aba Habilidades
    // segue chamando os `calcularFeitico*` por conta própria, porque ele precisa
    // do objeto INTEIRO do cálculo, e não do resumo.
    lista: resumoFeiticos(creature, ctxFeiticos).map((f) => {
      const original = creature.feiticos?.find((x) => x.id === f.id);
      const t = original?.bloodfeastTecnica;
      if (!bloodfeast.tem) return f;
      const passivaMircalla = bloodfeast.ids.includes("mircalla_passiva") && t?.id === "mircalla";
      const linha = { ...f, bloodfeastTecnica: t, cd: f.cd == null ? f.cd : f.cd + (t?.bonusCD ?? 0),
        conjuracaoTexto: passivaMircalla ? "Ação Livre" : f.conjuracaoTexto,
        custoPETexto: f.custoPE == null ? f.custoPETexto : `${f.custoPE * 3} PV`,
        custoPV: f.custoPE == null ? null : f.custoPE * 3,
        sustentacaoPE: t?.sustentacaoPE == null ? undefined : Math.max(1, t.sustentacaoPE - ctxFeiticos.reducaoSustentacao),
        propriedades: f.propriedades.map((p) => {
          if (p.id === "conjuracao" && passivaMircalla) return { ...p, valor: "Ação Livre" };
          if (p.id === "duracao" && passivaMircalla) return { ...p, valor: "Sustentada" };
          if (p.id === "cd" && t?.bonusCD) return { ...p, valor: (Number(p.valor) || cd) + t.bonusCD };
          return p;
        }),
        duracaoTexto: passivaMircalla ? "Sustentada" : f.duracaoTexto };
      return aprimoraLinhaBloodfeast(linha, bloodfeast.estado.ultima);
    }),
  };

  // ---------- RD Física ----------
  /* Canal separado de RD Geral e RD Específico.

     ⚠ O ESCUDO SAIU DAQUI em 2026-08-01 e VOLTOU no jogador em 2026-08-31. Na
     criatura a RD dele é Geral (ver `rdGeral` acima); no jogador é Física, como
     a tabela de grau do livro escreve. As três parcelas do escudo andam juntas:
     a RD base, a do grau da Ferramenta e o encantamento Reforçado. Quem escolhe
     a pilha é o `resolveEquipamentos`, e aqui só se soma a que ele encheu.
     Ver a divergência `rdEscudoFisico`. */
  const rdFisicoSemCondicao = equip.rdFisicoBonus + canal("rdFisico")
    + (pilhaDoEscudo === "rdFisico" ? rdEscudoMotor : 0);
  const rdFisico = fragilizado ? 0 : rdFisicoSemCondicao;

  /* ---------- Defesas por tipo de dano ----------
     Imunidade, Resistência, RD e Vulnerabilidade, um por tipo. Fica AQUI, e não
     mais acima, porque a RD efetiva contra um tipo junta as três RDs já
     calculadas: a Geral alcança tudo menos alma, a Física soma nos três físicos
     e a da Alma só existe para o dano na alma. Ver ./afty-defesas-dano.js. */
  const defesasDano = resolveDefesasDano({
    manual: sanearDefesasDano(creature?.defesasDano, TIPOS_DANO),
    canalTipo: (c, t) => canal(c, t),
    fontesTipo: (c, t) => detalhesDoCanal(ef, c, t).map((d) => ({ label: d.nome, valor: d.valor })),
    rdGeral, rdFisico, rdAlma,
    // Fragilizado zera a RD por tipo e anula a Resistência (a Imunidade fica).
    fragilizado,
    /* ⚠ O catálogo VIAJA POR PARÂMETRO, e não por import lá dentro: o
       afty-defesas-dano é módulo FOLHA de propósito. A nota no topo dele conta
       qual ciclo isso evita. Aqui é seguro, porque o afty-derive já importa o
       afty-equipamentos e já está depois do afty-habilidades no grafo. */
    categorias: CATEGORIAS_DANO,
    tiposDaCategoria: tiposDeDanoDaCategoria,
  });

  // ---------- Defesa / CA (+ uniforme, - sobrecarga; Treino de Luta ADIADO) ----------
  const divisorDefesa =
    tipo === "conjurador" ? 1.75 :
    tipo === "misto" ? 1.5 :
    /* combatente | restringido */ 1.25;
  const defTipo = INT(nd / divisorDefesa);

  // Qual atributo entra na Defesa. Destreza por padrão, e o canal
  // `defesaAtributo` TROCA (Músculos Desenvolvidos: "você pode optar por somar
  // seu Modificador de Força ao invés de Destreza").
  //
  // ⚠ SUBSTITUIÇÃO, e não soma. Isto era `max(0, mod_forca - mod_destreza)` no
  // canal `defesa`, que dá o mesmo número mas mente no hover: "Destreza +3" e
  // "Músculos Desenvolvidos +2" um embaixo do outro se leem como soma dos dois
  // atributos (autor, 2026-08-08).
  //
  // Vale o MAIOR entre a Destreza e os concedidos, porque a regra diz "você pode
  // OPTAR": ninguém opta por piorar a própria Defesa.
  const atributosDefesa = ATTR_KEYS.filter((k) => valorCanal(ef, "defesaAtributo", k) > 0);
  const attrDefesa = [...atributosDefesa, "destreza"]
    .reduce((melhor, k) => ((modByAttr[k] ?? 0) > (modByAttr[melhor] ?? 0) ? k : melhor), "destreza");
  const modDefesa = modByAttr[attrDefesa] ?? 0;
  /* ⚠ A Defesa do jogador perde a Maestria TAMBÉM, e não só a escala por Tipo:
     "Defesa = 10 + Modificador de Destreza + Metade do seu Nível + Outros
     Bônus", sem BT nenhum. É o que a separa da CD, que mantém o BT. */
  const defEscala = valoresDoJogador ? metadeDoNivel : defTipo;
  const defBt = valoresDoJogador ? 0 : bt;
  const aparar = defesaDeAparar([
    ...armasParaDano.map((a) => ({ ...a, treinada: ehJogador("proficienciaPorArma")
      ? a.treinada : !!creature?.ataquesProf?.[a.ataqueId ?? (a.distancia ? "distancia" : "corpo")] })),
    ...(pugilato ? [{ nome: "Ataque Básico", chaveArma: pugilato.uid ?? pugilato.def.id,
      propriedades: propriedadesBasico, treinada: ataqueIdBasico === "amaldicoado"
        || ehJogador("proficienciaPorArma") || !!creature?.ataquesProf?.corpo }] : []),
  ], opcoes.propriedadesArmas);
  const defesa = (aparar?.valor ?? 0) + 10 + defEscala + modDefesa + defBt + equip.uniformeDefesa + carga.defesa + canal("defesa");

  // ---------- Perícias, Jogadas de Ataque e Testes de Resistência ----------
  // Depende de cdTipo e defTipo: a planilha do autor (2026-07-27) mostra que a
  // CRIATURA não usa o "metade do nível" do livro (essa é a fórmula do JOGADOR).
  // Teste de Resistência usa a MESMA escala por Tipo da CD e da Defesa (Astúcia
  // e Vontade a da CD, Reflexos e Fortitude a da Defesa, Integridade ND/1,5 em
  // todo Tipo), e Jogada de Ataque usa ND/1,5 fixo. Só as Perícias seguem em
  // metade do ND, pendente de fórmula própria. Ver afty-pericias.js.
  //
  // Orçamento de perícias treinadas = 3 + maior mod entre INT e SAB + rank do
  // Grau do Feiticeiro (autor, 2026-07-27).
  /* PENALIDADE DE ARMADURA (canal do Motor, 2026-09-11). O autor pediu o canal
     para habilidades que aumentem ou diminuam a penalidade do uniforme e do
     escudo, e fechou as regras por pergunta:

       • positivo ALIVIA e negativo aumenta, como todo bônus do Motor;
       • o total PARA EM ZERO, e nunca vira bônus (a regra do Polido e do Ajustado);
       • um aumento vale SEMPRE, mesmo sem nada equipado;
       • vale nos dois sistemas.

     As quatro cabem numa conta só: itens mais canal, aparado em zero.

     ⚠ AS PARCELAS SÃO DUAS LISTAS. A da Ficha diz item por item (o hover do
     número na aba Equipamentos, que até aqui abria vazio porque ninguém montava
     a lista). A das perícias junta os itens em "Armadura e Escudo", como sempre
     foi, e cada efeito do Motor entra com o nome dele. Aparada em zero, a
     penalidade não aparece em lugar nenhum, e as listas saem vazias. */
  const penalidadeMotor = detalhesDoCanal(ef, "penalidadeArmadura")
    .map((d) => ({ label: d.nome, valor: d.valor }));
  const penalidadeArmadura = Math.min(0, equip.penalidadeDestreza + valorCanal(ef, "penalidadeArmadura"));
  const partesPenalidade = penalidadeArmadura === 0 ? [] : [...equip.penalidadePartes, ...penalidadeMotor];
  /* ⚠ MARCADAS com `penalidade: true`: o teste de Ritual tira a penalidade
     inteira da Prestidigitação quando troca para Inteligência, e ele achava a
     parcela pelo RÓTULO. Com o Motor, uma parcela entra com o nome da
     habilidade, e o rótulo deixou de dizer o que ela é. */
  const partesPenalidadePericia = penalidadeArmadura === 0 ? [] : [
    ...(equip.penalidadeDestreza ? [{ label: "Armadura e Escudo", valor: equip.penalidadeDestreza }] : []),
    ...penalidadeMotor,
  ].map((p) => ({ ...p, penalidade: true }));

  const testes = resolveTestes(creature, {
    restricaoDefinitiva: expandeHerdadas(habilidades.efetivas).includes("res_restricao_definitiva"),
    semblanteCativante: configuracaoEspecializacao.semblante,
    valorPresenca: attrEff.presenca,
    nd, bt, mods: modByAttr, tecnicaAttr, grauRank: grau.rank,
    sistema,
    /* ⚠ `undefined` na criatura, e o objeto (mesmo nulo) no jogador. É a
       diferença entre "este sistema não tem pacote de Classe" e "tem, e está
       vazio porque a ficha não escolheu Classe nenhuma". O `resolveTestes`
       distingue as duas com `!== undefined`. */
    /* ⚠ `periciaAtributo` NÃO VIAJA MAIS para cá desde 2026-08-31: o orçamento
       do jogador passou a usar o maior mod entre INT e SAB, como o da criatura.
       Ver a nota em `resolveTestes`. Os dois saem de antes do `montarCtx`. */
    ...(ehJogador("pacoteDaClasseInicial") ? { pacoteInicial, trDaClasse } : {}),
    escalaCD: cdTipo, escalaDefesa: defTipo,
    divisorCD, divisorDefesa,
    bonusVagas: canal("vagasPericia"),
    efeitos: ef,   // bonusPericia / bonusTR / bonusAcerto / proficienciaPericia
    /* ⚠ QUATRO CAMINHOS TROCAM O ATRIBUTO DE UMA PERÍCIA, E A ORDEM AQUI É A
       PRECEDÊNCIA. Espalhar objeto sobrescreve, então quem vem por último
       vence, e isso é decisão e não acaso:

         1. o catálogo do livro          (`p.atributo`, o padrão, lá no resolve)
         2. característica de ORIGEM     (uma regra que a ficha ganhou)
         3. TREINAMENTO                  (idem, e mais específica que a origem)
         4. a troca MANUAL da aba        (o ato explícito da pessoa)

       O manual vence os três porque ele é o único que alguém digitou. Se um
       Treinamento concede "Feitiçaria com Força" e a pessoa põe Inteligência
       por cima, ela quis Inteligência: o contrário faria o controle não
       responder em algumas linhas, sem dizer por quê.

       ⚠ E ele é o ESCAPE HATCH declarado (autor, 2026-09-05): *"muita gente
       precisa disso por N fontes diferentes como Treinos Próprios e etc, que o
       sistema não comporta sem Addon e eu não vou fazer addon pra todo
       mundo"*. Uma fonte de mesa que o catálogo não conhece não tem como entrar
       pelos caminhos 2 e 3. */
    atributosPericia: {
      ...atributosDePericiaDaOrigem(creature, escolhasOrigem),
      ...atributosDePericiaDeTreino(creature),
      ...atributosDePericiaManuais(creature),
    },
    // Penalidade de armadura e escudo, cumulativa, em testes de perícia que
    // usam Destreza. Voltou a valer em 2026-08-01, e desde 2026-09-11 soma o
    // canal `penalidadeArmadura` do Motor. Ver o bloco logo acima.
    penalidadeDestreza: penalidadeArmadura,
    penalidadePartes: partesPenalidadePericia,
  });
  /* FALHA AUTOMÁTICA (Paralisado e Inconsciente, em Reflexos). O número do TR
     continua o mesmo, porque a regra não o muda: a linha só ganha a marca, com
     o nome de quem a impôs, e a tela diz que a rolagem não vale. */
  if (Object.keys(condicoes.falhas).length) {
    testes.resistencias = (testes.resistencias ?? []).map((r) => (condicoes.falhas[r.value]
      ? { ...r, falhaAutomatica: condicoes.falhas[r.value] }
      : r));
  }

  // O teste de Conjuração em Ritual parte de Prestidigitação. Naturalidade com
  // Rituais abre uma escolha por uso, então a ficha guarda o atributo escolhido
  // na configuração daquele Feitiço em vez de trocar Destreza por Inteligência
  // silenciosamente. Ritualista soma +2 em qualquer uma das duas versões.
  const prestidigitacao = (testes.pericias ?? []).find((p) => p.id === "prestidigitacao") ?? null;
  const temNaturalidadeRitual = habilidades.efetivas.includes("cnj_naturalidade_com_rituais");
  const temRitualista = habilidades.efetivas.includes("cnj_ritualista");
  const partesPrestidigitacao = prestidigitacao?.partes ?? [];
  const parteAtributoPrest = partesPrestidigitacao[0] ?? { label: "Destreza", valor: modDes };
  /* Toda parcela da Penalidade de Armadura, dos itens e do Motor, pela marca
     `penalidade`. Ela só existe quando a Prestidigitação usa Destreza, e sai
     INTEIRA quando o Ritual troca para Inteligência. */
  const penalidadePrest = partesPrestidigitacao
    .filter((p) => p.penalidade)
    .reduce((s, p) => s + (p.valor || 0), 0);
  const bonusRitualista = temRitualista ? 2 : 0;
  /* O teste de Conjuração em Ritual entra DEPOIS do `resumoFeiticos`, porque
     depende da perícia de Prestidigitação, que só fecha aqui embaixo.

     ⚠ Virou FUNÇÃO NOMEADA (2026-08-10) porque dois caminhos precisam dela: a
     lista pronta e o `comLiberacao`. Um Feitiço pode ser Ritual E Liberação
     Máxima no mesmo uso, e sem isto a versão liberada voltaria da mesa sem o
     teste de ritual, ou seja, o jogador perderia a rolagem por ter declarado a
     Liberação. */
  const comTesteDeRitual = (f) => {
    {
      if (!f.ritual) return f;
      const config = opcoes.rituais?.[f.id] ?? {};
      const usaInteligencia = temNaturalidadeRitual && config.atributoRitual === "inteligencia";
      const bonusPrestBase = prestidigitacao?.bonus ?? 0;
      const bonusAtributo = usaInteligencia
        ? bonusPrestBase - (parteAtributoPrest.valor || 0) - penalidadePrest + modInt
        : bonusPrestBase;
      const partesAtributo = usaInteligencia
        ? [
          { label: "Inteligência", valor: modInt },
          ...partesPrestidigitacao.slice(1).filter((p) => !p.penalidade),
        ]
        : partesPrestidigitacao;
      return {
        ...f,
        ritual: {
          ...f.ritual,
          atributoRitual: usaInteligencia ? "inteligencia" : "destreza",
          permiteInteligencia: temNaturalidadeRitual,
          teste: f.ritual.exigeTeste ? {
            bonus: bonusAtributo + bonusRitualista,
            cd: f.ritual.cd,
            partes: [
              ...partesAtributo,
              ...(bonusRitualista ? [{ label: "Ritualista", valor: bonusRitualista }] : []),
            ],
          } : null,
        },
      };
    }
  };
  /* A Técnica Inata bloqueada (DA-07): cada Feitiço continua na lista, marcado
     com o motivo, e a tela o desenha indisponível. Nada é apagado. */
  const marcaBloqueio = (f) => (tecnicaInata.bloqueada ? { ...f, bloqueado: tecnicaInata.motivo }
    : exaustaoTecnica ? { ...f, bloqueado: exaustaoTecnica.motivo } : f);
  /* A TÉCNICA MÁXIMA (autor, 2026-10-08). A vaga EXCLUSIVA (`vagasTecnicaMaxima`,
     1 pela Aptidão) contra as Técnicas Máximas oficiais, e a validação de cada
     uma: vaga, natureza permitida e os requisitos da Aptidão (Mestre em
     Feitiçaria e acesso ao Nível 4, DA-09). Fica AQUI, depois dos Testes, porque
     o Mestre em Feitiçaria só existe depois deles. A escala de cada uma não
     depende disto: o `calcularFeitico` a tira do acesso. */
  const aptidaoTecnicaMaxima = getAptidao("tecnica_maxima");
  const ctxRequisitoTecnicaMaxima = {
    nivelFeiticoMax: feiticos.nivelMax,
    periciaProf: Object.fromEntries((testes.pericias ?? []).map((p) => [p.id, p.prof ?? null])),
  };
  const tecnicasMaximas = resolveTecnicasMaximas(feiticosLista, {
    vagas: canal("vagasTecnicaMaxima"),
    partesVagas: detalhesDoCanal(ef, "vagasTecnicaMaxima").map((x) => ({ label: x.nome, valor: x.valor })),
    acesso: feiticos.nivelMax,
    temAptidao: aptidoesIds.includes("tecnica_maxima"),
    requisitosFalhos: (aptidaoTecnicaMaxima?.requisitos ?? [])
      .map((r) => avaliarRequisitoAptidao(r, ctxRequisitoTecnicaMaxima))
      .filter((r) => r.verificavel && !r.ok)
      .map((r) => r.label),
  });
  /* A RECARGA (DA-05): 6 − piso(BT / 2), mais o canal `recargaTecnicaMaxima`
     (o Manual de Técnica tira 1), com piso 0. Igual para toda Técnica Máxima da
     ficha, oficial ou LEGACY: a recarga é regra da Aptidão, e não da escala. */
  const recargaTecnicaMaxima = recargaDaTecnicaMaxima(bt, canal("recargaTecnicaMaxima"));
  const partesRecargaTecnicaMaxima = [
    { label: "6 Menos Metade do Bônus de Treinamento", valor: 6 - Math.floor(bt / 2) },
    ...detalhesDoCanal(ef, "recargaTecnicaMaxima").map((x) => ({ label: x.nome, valor: x.valor })),
  ];
  const marcaTecnicaMaxima = (f) => {
    if (!tecnicasMaximas.porId[f.id]) return f;
    const info = {
      ...tecnicasMaximas.porId[f.id],
      ...(f.tecnicaMaxima ?? {}),
      recarga: recargaTecnicaMaxima,
      partesRecarga: partesRecargaTecnicaMaxima,
    };
    // Erro e aviso da Técnica Máxima entram no triângulo de avisos da linha.
    const textos = (info.validacao ?? []).map((v) => v.texto);
    return { ...f, tecnicaMaxima: info, avisos: [...(f.avisos ?? []), ...textos] };
  };
  feiticos = {
    ...feiticos,
    tecnicaInata,
    tecnicasMaximas,
    lista: (feiticos.lista ?? []).map(comTesteDeRitual).map(marcaBloqueio).map(marcaTecnicaMaxima),
    /* ⚠ FUNÇÃO, e não valor. A Liberação Máxima é escolhida na HORA DA
       CONJURAÇÃO, então ela não tem como estar na lista pré-calculada: o jogador
       declara as melhorias na mesa e a Ficha pede a versão liberada daquele
       Feitiço. Continua valendo que a UI não recalcula regra nenhuma, ela só
       pergunta de novo com a escolha em mãos.

       Passa pelo `comTesteDeRitual` pelo mesmo motivo que a lista: os dois
       sistemas convivem no mesmo uso. */
    comLiberacao: (id, melhorias) => {
      const linha = resumoDeUmFeitico(creature, id, { ...ctxFeiticos, liberacao: { melhorias } });
      return linha ? comTesteDeRitual(linha) : null;
    },
  };

  // ---------- Dano (planilha do autor, 2026-07-27) ----------
  // Uma linha por FONTE: o Ataque Básico e mais uma para cada arma equipada.
  // Todas usam a MESMA conta, e o dano listado na tabela da arma é ignorado. Da
  // arma vêm o Alcance, as Propriedades e o grau da Ferramenta Amaldiçoada.
  // Faixas e Manoplas não viram linha própria: são o Ataque Básico (grupo
  // "pugilato"). O Nível de Aptidão em Controle e Leitura entra na conta, daí
  // depender do `aptidao` já resolvido lá em cima.
  /* O TREINO NA ARMA "CASO JÁ SEJA" (canal `treinoArmaCasoJa`, 2026-10-09, o
     Grão Mestre em Arma): a arma alvo passa a somar o Bônus de Treinamento, e se
     ela já somava, o valor da linha entra no Acerto e no Dano dela. O canal não
     soma sozinho: aqui ele vira treino (no jogador) ou linhas comuns de
     `acertoArma` e `danoBonus`, com o nome da fonte, antes do dano.
     Na criatura o treino é pelo TIPO de ataque: tipo treinado já soma o BT, e
     tipo sem treino ganha o BT como Acerto daquela arma. */
  const armasDoDano = (() => {
    if (!(ef?.detalhes ?? []).some((x) => x.canal === "treinoArmaCasoJa")) return { armas: armasParaDano, efeitos: [] };
    // Por arma: as linhas com o id dela e as sem alvo (que valem para todas).
    const porArma = (id) => detalhesDoCanal(ef, "treinoArmaCasoJa", id);
    const extras = [];
    const armas = armasParaDano.map((a) => {
      const minhas = porArma(a.id);
      if (!minhas.length) return a;
      const ataqueId = a.ataqueId ?? (a.distancia ? "distancia" : "corpo");
      const tipoTreinado = !!testes.ataques?.find((x) => x.id === ataqueId)?.treinado;
      const jaSoma = ehJogador("proficienciaPorArma") ? (!!a.treinada || tipoTreinado) : tipoTreinado;
      if (!jaSoma) {
        if (ehJogador("proficienciaPorArma")) return { ...a, treinada: true };
        extras.push({ canal: "acertoArma", alvo: a.id, expr: String(bt), origem: "treinoArma", nome: `${minhas[0].nome} (Treino)` });
        return a;
      }
      for (const m of minhas) {
        extras.push({ canal: "acertoArma", alvo: a.id, expr: String(m.valor), origem: "treinoArma", nome: m.nome });
        extras.push({ canal: "danoBonus", alvo: a.id, expr: String(m.valor), origem: "treinoArma", nome: m.nome });
      }
      return a;
    });
    return { armas, efeitos: extras };
  })();
  if (armasDoDano.efeitos.length) ef = mesclarEfeitos(ef, aplicarEfeitos(armasDoDano.efeitos, montarCtx(attrEff, modByAttr)));
  let dano = resolveDano(creature, {
    nd, patamar, mods: modByAttr, aptidaoCL: aptidao.efetivo.cl,
    sistema,
    /* ⚠ TODO PERSONAGEM É TREINADO EM ATAQUE DESARMADO (livro, trazido pelo
       autor em 2026-09-16): *"Todo personagem é treinado em Ataques Desarmados"*.
       Até aqui o treino vinha só da Manopla ou da Faixa equipada e treinada, e
       sem uma delas ninguém somava o Bônus de Treinamento no soco, nem o
       Lutador. Só a ficha de jogador lê este campo (divergência
       `proficienciaPorArma`): a criatura treina pelo tipo de ataque. */
    treinadaBasico: true,
    efeitos: ef, armas: armasDoDano.armas, grauBasico, acertoGrauBasico,
    fontesAcertoBasico, escoposBasicoExtra, finezaBasico, ataqueIdBasico,
    propriedadesBasico, criticoExtraDadosBasico,
    chaveArmaBasico: pugilato?.uid ?? "basico",
    avisosPropriedadesBasico: pugilato?.def?.avisosPropriedades ?? [],
    /* ⚠ O DADO DO GOLPE DESARMADO DA FICHA DE JOGADOR (autor, 2026-08-31):
       "Golpe Desarmado segue o cálculo de Lutador ou Arma Natural." Sem nenhum
       dos dois, vale o básico do livro por nível (1d4, 1d6, 1d8, 1d10 e 1d12), e
       o Restringido segue a escada do Lutador (2026-09-16).

       Ele é lido da FICHA, e não de canal: as três fontes escrevem um dado
       ABSOLUTO por faixa de nível ("se torna 1d8... 1d10, 1d12, 2d8 e 2d12"), e
       nenhuma dessas progressões é uniforme na escada (o Corpo Treinado salta
       quatro degraus do 2d8 para o 2d12). Ver `dadoDesarmado`.

       ⚠ O nível do Corpo Treinado é o de LUTADOR, e não o do personagem, e é o
       de ESCALONAMENTO (real mais metade da outra classe), e não o real (autor,
       2026-09-01): *"um Lutador 10 com Combatente 20 contaria como um Lutador
       Nível 20 para o cálculo de Corpo Treinado."* É o mesmo `esc_lutador` que a
       linha de escada do Motor usa em afty-efeitos-conteudo.js, e as duas TÊM de
       ler o mesmo nível: elas são a mesma regra escrita para os dois sistemas, e
       ler níveis diferentes fazia a criatura e o jogador divergirem calados numa
       multiclasse. O nível REAL segue valendo para o pré-requisito, que é quem
       decide se a habilidade chega. */
    ...(() => {
      const d = dadoDesarmado({
        nivel: nd,
        nivelLutador: nivelEspec.lutador?.escalonamento ?? 0,
        /* "Caso seja um Restringido, ele segue o mesmo aumento de um Lutador." O
           `semEnergia` é quem já responde "esta ficha é Restringida" nos dois
           sistemas (Especialização no jogador, Tipo na criatura). */
        /* ⚠ A VARIAÇÃO DO RESTRINGIDO NÃO RECEBE A ESCADA (autor, 2026-09-28, sobre
           a Restrição Intelectual: "por não ser um restringido focado em força").
           É conteúdo do Restringido do livro, e a variação herda identidade. */
        restringido: semEnergia && !variacaoDoRestringido,
        nivelRestringido: nivelEspec.restringido?.escalonamento ?? nd,
        tem: (id) => habilidades.efetivas.includes(id) || aptidoesIds.includes(id),
      });
      return { dadoBasico: d.dado, fonteDadoBasico: d.fonte ?? "Golpe Desarmado" };
    })(),
    efeitosLinhaDano: efeitosLinhaDano.filter((e) => !efeitosConcentrados.includes(e)),
    contextoDsl: ctxTecnica,
    origensDaFonte: (id) => expandeHerdadas([id]),
    tecnicasCombate: { ...tecnicasCombate, bt },
    // Os Ataques já resolvidos, para cada linha fechar o Acerto dela: o ataque
    // da categoria mais o grau da arma daquela linha.
    ataques: testes.ataques,
    alcanceCorpo: tamanho.espacoAlcance,
    alcanceMult: combate.invencivelSobOSol
      || combate.postura === "ceu" || combate.postura2 === "ceu" ? 2 : 1,
    // O Bônus em Ataque Permutativo que perde Margem, aplicado arma a arma.
    permutasDeMargem: auxiliaresAtivos.permutasDeMargem,
  });
  dano = {
    ...dano,
    entradas: (dano.entradas ?? []).map((entrada) => (
      dadosAuxiliaresNaLinha(entrada, auxiliaresAtivos.dados)
    )),
  };
  dano = aplicarImbuicaoNoDano(
    dano,
    creature,
    combate,
    habilidades.efetivas,
    feiticos.lista,
  );
  // Antes das Aptidões: é o `aplicarAptidoesNoDano` que fecha fórmula e hover.
  dano = aplicarSintonizadaNoDano(dano, sintonizadas, !!combate?.[ESTADO_SINTONIZADA]);
  dano = aplicarAptidoesNoDano(dano, creature, combate, {
    aptidoesIds,
    au: aptidao.efetivo?.au ?? 0,
    cl: aptidao.efetivo?.cl ?? 0,
    // O Canalizar Energia Reversa gasta pontos iguais ao bônus de treinamento.
    bt,
    modTecnica,
    cd,
  });
  dano = aplicarAtaqueConcentradoNoDano(dano, {
    efeitos: efeitosConcentrados, contexto: ctxTecnica, jaAplicado: ef.aplicado,
    vezes: combate.ataqueConcentrado,
  });
  dano = aplicarPropriedadesNoDano(dano, {
    estado: opcoes.propriedadesArmas, atributos: attrEff, bt, tipos: TIPOS_DANO,
  });
  const temEscudoEquipado = equip.entradas.some((e) => e.tipo === "escudo" && e.equipado);
  if (talentos.escolhidas.includes("tal_tecnicas_ofensivas_de_escudo") && temEscudoEquipado) {
    const modForca = Math.trunc(Number(modByAttr.forca) || 0);
    const dadosEscudo = Math.max(0, modForca);
    const linhaEscudo = comFormulasDeDano({
      id: "tal_tecnicas_ofensivas_de_escudo",
      nome: "Empurrão com Escudo",
      fonte: "talento",
      tipoDano: "im",
      tipoDanoLabel: TIPOS_DANO.im ?? "Impacto",
      margemCritico: null,
      gruposDano: [{
        nome: "Técnicas Ofensivas de Escudo",
        dados: dadosEscudo,
        faces: 6,
        fixo: modForca,
        momento: "apos",
        multiplica: false,
        naPartes: true,
      }],
      partes: [
        { label: "Técnicas Ofensivas de Escudo", texto: `${dadosEscudo}d6`, categoria: "naoCritavel" },
        { label: "Modificador de Força", valor: modForca, categoria: "fixo" },
      ],
    });
    dano = { ...dano, entradas: [...(dano.entradas ?? []), linhaEscudo] };
  }

  // ---------- Cura (2026-08-03) ----------
  // Uma linha por FONTE, igual ao Dano, mas o número vem todo do Motor: cada
  // poder escreve a rolagem dele no próprio texto, e não há fórmula única que
  // as cubra. Ver afty-cura.js.
  //
  // ⚠ Roda DEPOIS do dano e do PV: as fontes que espelham ("uma rolagem do seu
  // dano desarmado") copiam a linha do Ataque Básico, e os dois itens que curam
  // uma fração do PV precisam do PV já fechado.
  const cura = resolveCura({
    efeitos: ef,
    // O `semEnergia` já zera as aptidões, então o Restringido não ganha linha de
    // Energia Reversa por engano.
    aptidoes: aptidoesIds,
    // Com as herdadas: o `requer` das curas cita o id do livro (Ainda de Pé).
    habilidades: expandeHerdadas(habilidades.efetivas),
    itens: equip.entradas,
    hp: hpAntesMultiplicador,
    danoBasico: dano.entradas.find((e) => e.id === "basico") ?? null,
    /* As linhas que as entradas ADQUIRIDAS declaram (`fonteCura`, 2026-10-07). O
       número de cada uma vem pelos canais de cura mirando o id dela. */
    fontesDeclaradas: [
      ...habilidades.efetivas.map((id) => fonteCuraDeclarada(getHabilidade(id), "habilidade")),
      ...(talentos.escolhidas ?? []).map((id) => fonteCuraDeclarada(getTalento(id), "talento")),
      ...aptidoesIds.map((id) => fonteCuraDeclarada(getAptidao(id), "aptidao")),
    ].filter(Boolean),
  });

  // ---------- Empolgação (Lutador) ----------
  // Só a parte DERIVADA: a tabela de dados e o nível em que o combate começa.
  // O nível atual é estado de combate e a ficha não o guarda (autor, 2026-07-28).
  const empolgacao = resolveEmpolgacao(habilidades.efetivas, {
    maxima: canal("empolgacaoMaxima"),
    bonusInicial: canal("empolgacaoInicial"),
  });

  // ---------- Atenção = 10 + bônus de Percepção (Percepção passiva) ----------
  const atencao = testes.atencao + canal("atencao");

  // ---------- PV Temporário ----------
  // Casca por cima do PV, não PV máximo: some quando o efeito acaba. Hoje só a
  // simulação de combate produz (Fluxo, Brutalidade Aprimorada e Eliminar e
  // Continuar).
  const pvTemporario = canal("pvTemporario");

  // ---------- PE Temporário ----------
  /* Irmão do de cima, e ele faltava desde julho. ⚠ A forma é DIFERENTE: o PV
     temporário é um número só, e este sai POR FONTE, porque a regra da mesma
     fonte é "topa, não acumula". Sem o nome da fonte, o Completo do Treino de
     Controle de Energia ("no começo de toda rodada você ganha metade do BT")
     viraria uma pilha infinita na rodada 10.

     O ALVO é o GATILHO: `combate` entrega uma vez quando a cena começa, e
     `rodada` reenche no começo de cada rodada. Quem aplica é a sessão da Ficha
     (`aplicaPeTemporario` em ficha-sessao.js), não o derivado: aqui só se diz o
     que a criatura TEM direito de receber.

     Copiado em desenho do `applyRoundStartResources` da 2.5.2
     (src/components/fm-automation-entities.js), que resolveu isto primeiro. */
  const peTemporario = (() => {
    /* ⚠ A CHAVE leva o gatilho junto, e o nome sozinho NÃO serve. O Treino de
       Controle de Energia emite nos dois gatilhos (4 na cena pela 2ª etapa,
       metade do BT por rodada pelo Completo) e o `efeitosDeTreino` carimba o
       nome da LINHA nos dois. Com o nome como chave, os dois viravam a mesma
       fonte e a regra do "topa, não acumula" comia um deles: a rodada 1 dava 4
       em vez de 7. São dois benefícios diferentes da mesma linha. */
    const porGatilho = (gatilho) => detalhesDoCanal(ef, "peTemporario", gatilho)
      .map((d) => ({
        chave: `${gatilho}:${d.nome}`,
        nome: d.nome,
        valor: Math.max(0, Math.trunc(d.valor) || 0),
      }))
      .filter((d) => d.valor > 0);
    const combate = porGatilho("combate");
    const rodada = porGatilho("rodada");
    return { combate, rodada, tem: combate.length > 0 || rodada.length > 0 };
  })();

  // ---------- Recursos de especialização ----------
  // Pontos de Preparo (Combatente). Zero para quem não tem a habilidade dona, e
  // o Preview esconde. A Estamina do Restringido NÃO mora aqui: é o próprio PE
  // com outro nome, então tudo que a alimenta usa o canal `pe`.
  const pontosPreparo = canal("pontosPreparo");
  // A casca por rodada (Postura do Céu). Quem a entrega é a sessão, a cada
  // rodada: ver `proximaRodada` em ficha/ficha-sessao.js.
  const preparoTemporario = Math.max(0, Math.trunc(canal("preparoTemporario")));

  // ---------- Regeneração ----------
  // Cura no INÍCIO do turno, em dados + fixo, igual às linhas de dano.
  // Sobrevivente (Lutador 4°) rola d6 e Corpo de Aço (Restringido 6°) rola d8:
  // o canal do DADO carrega as faces, e vale a maior das fontes.
  // ⚠ O dado é MÁXIMO, não soma: `canal()` somaria 6 + 8 = 14 faces.
  const facesRegen = detalhesDoCanal(ef, "regeneracaoFaces").map((x) => x.valor);
  const regeneracao = {
    dados: Math.max(0, canal("regeneracaoDados")),
    dado: `d${Math.max(6, ...facesRegen)}`,
    fixo: canal("regeneracaoFixa"),
  };

  // ---------- Integridade da Alma ----------
  // O `atual` é estado da ficha e o máximo é 100, elevável pela Melhoria de
  // Alma. É o teto: passar dele é o que faz o multiplicador de PV subir de 1.

  // ---------- Iniciativa (autor, 2026-07-27) ----------
  // INT(Maestria / 2) + Mod. Destreza. Não usa o ND direto nem escala por Tipo.
  /* "Iniciativa = Modificador de Destreza + Outros Bônus". A criatura soma
     `metade da Maestria` por cima, e o jogador não. */
  const iniciativa = (valoresDoJogador ? 0 : INT(bt / 2)) + modDes + canal("iniciativa");

  // ---------- Orçamentos (budgets do builder) ----------
  // Orçamento de Níveis de Aptidão. Só entram aqui os pontos LIVRES: os
  // limiares de ND, o +1 de Qnt.PE Muito Grande e as concessões de treino
  // "à sua escolha". As concessões DIRECIONADAS a uma trilha são grátis e
  // não passam pelo orçamento (ver resolveNiveisAptidao).
  //
  // ⚠ O +1 de Qnt.PE Muito Grande NÃO é o Raio Negro. A planilha rotulava
  // essa célula de "Raio Negro" e o autor confirmou (2026-07-16) que são
  // efeitos SEPARADOS: Qnt.PE Muito Grande dá +1 no orçamento e nada mais,
  // enquanto a aptidão Raio Negro dá +ND de PE e +1 DIRECIONADO em Aura.
  // Os dois somam. O efeito do Raio Negro ainda NÃO é aplicado (o motor não
  // lê aptidões escolhidas): fica para a passada de efeitos, quando o
  // catálogo fechar. Ver docs/afty-status.md.
  const aptidaoThresholds = [[2,1],[4,1],[6,1],[8,1],[10,2],[12,1],[14,1],[16,1],[18,1],[20,2]];
  // Só o Grimório Afty prolonga o orçamento depois do ND 20. Na Ficha de
  // Player, o último marco de nível que dá pontos é o 20. As demais fontes do
  // canal `pontosAptidao` continuam somando normalmente nos dois sistemas.
  const aptidaoAlem20 = ehJogador("aptidaoApos20") && !regrasAddon.aptidaoApos20
    ? 0 : Math.max(0, Math.floor((nd - 20) / 2));
  const rotuloMarcoAptidao = rotuloDoNivel(sistema);
  const partesAptidaoND = [
    ...aptidaoThresholds
      .filter(([limiar]) => nd >= limiar)
      .map(([limiar, valor]) => ({ label: `${rotuloMarcoAptidao} ${limiar}`, valor })),
    ...Array.from({ length: aptidaoAlem20 }, (_, i) => ({ label: `${rotuloMarcoAptidao} ${22 + i * 2}`, valor: 1 })),
  ];
  // ⚠ `canal("pontosAptidao")`, e não `treino.aptidao`: o orçamento vinha só do
  // estágio MONTANTE (Treinamentos e Habilidades Gerais), então uma HABILIDADE
  // que concedesse ponto de aptidão era descartada calada. O Elevar Aptidão do
  // Conjurador ("você aumenta um dos seus Níveis de Aptidão em 1") foi quem
  // expôs isso. O `ef` já traz o montante mesclado, então não dobra.
  const totalAptidao = semEnergia ? 0 : (
    partesAptidaoND.reduce((s, parte) => s + parte.valor, 0) +
    /* ⚠ O +1 DA QUANTIDADE DE PE MUITO GRANDE SAIU DAQUI em 2026-08-30. Ele era
       o Raio Negro cobrado no campo errado, e agora vem da Aptidão Raio Negro,
       pelo canal `pontosAptidao` (autor: "Quantidade de PE fica só para
       criaturas, e só mexe em PE"). Uma criatura Muito Grande SEM a Aptidão
       perde este nível, e é a intenção. */
    canal("pontosAptidao"));

  // Quantas Aptidões Amaldiçoadas a criatura PODE ter: canal vagasAptidao,
  // incluindo a Habilidade Geral Aptidão e o Treinamento para Aptidão.
  // O ND não dá nenhuma à criatura (regra 4 em afty-gerais.js).
  // Segue separado e independente do orçamento de NÍVEIS de aptidão
  // (totalAptidao, os limiares de ND), que não mudou.
  /* ⚠ NO JOGADOR VEM DO NÍVEL: "1 por Nível a partir do Nível 2. Logo Nível 20
     eu teria 19 Aptidões Amaldiçoadas. Independente de qual Especialização, com
     exceção de Restringido" (autor, 2026-08-30).

     ⚠ E É O NÍVEL DO PERSONAGEM, não o de cada Classe. Difere de propósito da
     vaga de Habilidade, que desconta o primeiro nível de CADA classe: aqui o
     autor disse "independente de qual Especialização", então o desconto é um só.

     O Restringido continua zerado pelo `semEnergia`, que é a mesma trava de
     sempre e a exceção que o autor nomeou. */
  const totalAptidoesAmaldicoadas = semEnergia ? 0 : (
    (ehJogador("vagasPorNivelDeClasse") ? Math.max(0, nd - 1) : 0)
    + canal("vagasAptidao"));

  /* Quanto o pré-requisito de NÍVEL de toda Aptidão desce. Quem lê é o
     `avaliarRequisitoAptidao`, na aba, e não este arquivo: o requisito é
     pergunta de tela, e não um stat. Segue o `semEnergia` como todo o resto da
     Aptidão, senão um Restringido carregaria um número que não usa. */
  const reduzNivelAptidao = semEnergia ? 0 : Math.max(0, canal("reduzNivelAptidao"));
  /* As trilhas cujo requisito de nível deixa de travar Aptidões de OUTRA trilha
     (canal `ignoraRequisitoTrilha`, 2026-10-11), com o nome de cada fonte para o
     hover do requisito. Quem lê é o `avaliarRequisitoAptidao`, na aba. */
  const requisitoTrilhaDispensado = semEnergia ? {} : Object.fromEntries(
    APTIDAO_TRILHAS.map((t) => [t.key, detalhesDoCanal(ef, "ignoraRequisitoTrilha", t.key)
      .filter((d) => d.alvo === t.key && d.valor > 0).map((d) => d.nome)])
      .filter(([, fontes]) => fontes.length),
  );

  /* Pool de Características Amaldiçoadas (Anatomia Amaldiçoada, addon Maldição
     - Era de Ouro): mesma forma da Aptidão, uma vaga por canal, sem trilha.
     Não segue o `semEnergia`: a característica é da Origem, não da Energia, e
     um Restringido de Origem Maldição (se algum addon algum dia permitir)
     continuaria com o corpo que a Origem descreve. */
  /* O `attrEff` entra para o requisito de atributo (nenhuma característica de
     hoje pede, mas o requisito é o da Aptidão e ele o lê). O `reduzNivelAptidao`
     NÃO entra de propósito: o canal fala em "pré-requisitos de nível" das
     Aptidões, e uma Característica não é Aptidão. */
  const caracteristicasAmaldicoadas = {
    ...resolveCaracteristicasAmaldicoadas(creature, {
      nd, attrEff, vagas: Math.max(0, canal("vagasCaracteristicaAmaldicoada")),
    }),
    /* O nome que a origem dá ao pool, e de onde vem cada vaga (2026-10-12). O
       Vampiro soma quatro fontes (Físico Amaldiçoado e três Patentes), e o hover
       fixo "1 no 1° nível, +1 a cada 5 níveis" mentia para ele. */
    rotulo: rotuloCaracteristicasDaOrigem(creature),
    partes: detalhesDoCanal(ef, "vagasCaracteristicaAmaldicoada")
      .filter((x) => x.valor)
      .map((x) => ({ label: x.nome, valor: x.valor })),
  };

  // ⚠ Especializações, Talentos, Habilidades, Alto Nível, Aptidão e o MOTOR DE
  // AUTOMAÇÃO subiram para o topo desta função (logo depois dos atributos
  // base), porque os efeitos precisam alcançar os stats. Ver o bloco
  // "CATÁLOGOS ESCOLHIDOS + MOTOR DE AUTOMAÇÃO" lá em cima.

  // Invocações: a invocação lê valores do DONO (ND, BT = maestria(ND) e o Nível
  // de Controlador, o lado da multiclasse). Resolvidas aqui só para a UI e a
  // validação lerem de um lugar só. NÃO alimentam nenhum stat do dono.
  /* ⚠ "NÍVEL DO CONTROLADOR" É O ND, e não o nível da Especialização (autor,
     2026-09-04: *"Nível do Controlador é o ND e não o Nível da Especialização
     Controlador"*).

     Até aqui era o nível de ESCALONAMENTO da Especialização (o real, mais metade
     da outra classe na multiclasse). Num Controlador puro os dois batem, e por
     isso a diferença só aparece em duas fichas:

       Controlador 6 / Lutador 14 no ND 20   valia 13, agora vale 20
       Lutador 20, com zero Controlador       valia  0, agora vale 20

     O segundo caso é o que muda mais, e o autor confirmou que vale: um
     shikigami de Feitiço ou de clã, num dono que nunca pegou a Especialização,
     passa a receber metade do ND em todo teste.

     ⚠ Isto NÃO é o nível de pré-requisito. Quem decide se a ficha PODE pegar
     uma Habilidade de Controlador continua sendo o nível REAL da
     Especialização, em `avaliarAcessoHabilidade`. O ND diz o quanto ela escala,
     e não se ela existe. */
  /* ⚠ DOIS NÍVEIS DE CONTROLADOR, com nomes que não se confundem (decisão do
     autor, 2026-09-30):
       nivelEscalonamentoControlador  o ND, o que os efeitos e o roster escalam
                                      (decisão de 2026-09-04, abaixo)
       nivelControladorReal           o nível REAL na Especialização, para
                                      pré-requisito escrito como nível de classe
                                      ("5 níveis em Controlador", "nível 17")
     O `nivelControlador` de sempre continua sendo o de escalonamento. */
  const nivelEscalonamentoControlador = nd;
  const nivelControladorReal = nivelEspec.controlador?.real ?? 0;
  const nivelControlador = nivelEscalonamentoControlador;
  // Efeitos estáticos das Habilidades de Controlador escolhidas, aplicados a
  // TODAS as invocações do dono (via Motor de Automação, ver afty-habilidades.js).
  const escolhasMapa = habilidades.escolhas?.mapa ?? {};
  /* ⚠ ORIGEM, CLÃ E TALENTO TAMBÉM CHEGAM NA INVOCAÇÃO desde 2026-08-31. Até
     aqui só Habilidade de Controlador tinha como tocar num shikigami, e por
     isso um clã que dissesse "seus shikigamis recebem +1 Ação" não tinha por
     onde entrar, no raw ou por Addon. Elas declaram no campo `efeitosInvocacao`
     da própria entrada, que é separado do `efeitos` de propósito: os dois
     espaços de canal repetem nomes (`pv`, `defesa`, `rd`) com sentidos
     diferentes. Ver `efeitosInvocacaoDeEntradas`. */
  const efeitosInvoc = [
    ...efeitosInvocacaoControlador(habilidades.efetivas, escolhasMapa),
    ...efeitosInvocacaoDeEntradas([
      ...caracteristicasEfetivas(creature),
      ...talentos.escolhidas.map((id) => getTalento(id)),
    ]),
    // Linha de Treinamento (2026-09-14): a quarta fonte, ao lado de Habilidade
    // de Controlador, Talento e Característica de Origem. Ver
    // `efeitosInvocacaoDeTreino` em afty-treinamentos.js.
    ...efeitosInvocacaoDeTreino(creature),
    /* O que o JOGADOR escreve (2026-09-15): Técnica, Funcionamentos
       adicionais, Addon, Feitiço Passivo e buff de mesa, quando a linha se
       marca com `escopo: "invocacao"`. As quatro fontes acima são catálogo, e
       até aqui nada escrito à mão alcançava um shikigami. Ver
       `efeitosInvocacaoEscritos` em afty-invocacoes.js. */
    ...semTecnicaBloqueada(efeitosInvocacaoEscritos(creature)),
  ];
  // MARCADORES: uma Habilidade que vale só para ALGUMAS invocações (Concentrar
  // Poder, as 4 Melhorias, Fantoche Supremo, Companheiro, Econômicas) entra por
  // marcador. O limite sai de uma expressão da DSL avaliada no contexto do dono.
  const ctxDono = { nd, bt, nivel_controlador: nivelControlador };
  /* Tudo que a ficha POSSUI e que um marcador de `requerId` pode citar. Um
     marcador de Addon costuma vir de um clã ou de um talento, e não de uma
     Habilidade de Controlador. Ver `marcadorDisponivel`. */
  const temIds = new Set([
    ...habilidades.efetivas,
    ...talentos.escolhidas,
    ...(origemId ? [origemId] : []),
    ...(creature?.core?.origem?.cla ? [creature.core.origem.cla] : []),
  ]);
  const marcadores = resolveMarcadoresInvocacao({
    escolhidasIds: habilidades.efetivas, escolhasMapa, ctxDono, temIds,
  });
  // Roster do Controlador: invocações iniciais, limite em campo, comandos e
  // hordas. É de REFERÊNCIA (mostra, não valida).
  const controle = resolveControleInvocacoes({
    escolhidasIds: habilidades.efetivas, escolhasMapa, nivelControlador,
  });
  // Feitiço de Criação de Shikigamis: o nível do Feitiço manda no grau, no
  // orçamento e no custo da invocação que ele referencia.
  // O ctx leva as duas peças que o `linhaDoFeitico` também junta na hora de
  // aplicar as reduções de custo: o repertório inteiro e as escolhas da ficha.
  const overridesPorInvocacao = overridesShikigami(feiticosLista, {
    ...ctxFeiticos,
    feiticos: feiticosLista,
    reducoesCustoFeitico: creature?.reducoesCustoFeitico,
    linhasEscolhaFeiticos: linhasComEscolhaFeiticos(creature),
    treinoEscolhaFeiticos: creature?.treinoEscolhaFeiticos,
  });
  const donoInvoc = {
    nd, bt, nivelControlador, nivelControladorReal,
    /* As invocações em campo agora (mesa), ou `null` no criador. Ver o
       `invocacoesEmCampo` lá em cima e a condição do Concentrar Poder. */
    invocacoesEmCampo,
    /* Controle Aprimorado (E-04, 2026-09-30): "você pode utilizar Aptidões
       Amaldiçoadas das categorias Controle e Leitura a partir de suas Invocações
       [...] entretanto, não é possível utilizar Punho Divergente e Emoção da
       Pétala Decadente". A lista sai para a ficha da invocação mostrar. */
    aptidoesPelaInvocacao: controle.controleAprimorado
      ? aptidoesIds
        .map((id) => getAptidao(id))
        .filter((a) => a?.categoria === "controle_leitura"
          && a.id !== "punho_divergente" && a.id !== "emocao_da_petala_decadente")
        .map((a) => ({ id: a.id, nome: a.nome }))
      : [],
    efeitos: efeitosInvoc,
    marcadores,
    overridesPorInvocacao,
    /* A redução ampla de PE, já com o alvo da Invocação resolvida. Vai PRONTA
       porque o `afty-invocacoes.js` não importa o `afty-efeitos.js`. */
    reducaoCustoPe: detalhesDeCustoPe(ef, "invocacao")
      .map((d) => ({ label: d.nome, valor: d.valor })),
    membroQuartoGrauGratis: controle.membroQuartoGrauGratis,
    otimizacaoEnergia: controle.otimizacaoEnergia,
    autonomia: controle.autonomia,
    resistenciaSobrecarregada: controle.resistenciaSobrecarregada,
    margemCritico: controle.margemCritico,
    criticoBrutal: controle.criticoBrutal,
    /* O estilo escolhido no Apogeu (Concentrado / Disperso / Sintonizado). Ele
       vira variável de DSL no contexto da invocação, e sem ele não dava para
       escrever a cláusula do Ápice do Controle, que depende de a invocação JÁ
       poder ser trazida como Ação Livre. */
    apogeuEstilo: controle.estilo ?? null,
    apice: controle.apice ?? false,
    /* Os tipos de dano a que algum FEITIÇO PASSIVO do dono dá Resistência. É o
       requisito da Característica Resistência da invocação (Adicionais: "Possuir
       um Feitiço Passivo que garante Resistência, a resistência deve ser a mesma
       da passiva"). O Feitiço é do dono (decisão do autor, 2026-09-30). */
    /* As armas em que o dono é treinado: o requisito da Forma de Arma da invocação
       (Adicionais: "o invocador ser Treinado na arma escolhida", 2026-09-30). */
    armasTreinadas: ARMAS.filter((a) => armaTreinadaPor(a, treinamentosEquipamento.armas)).map((a) => a.id),
    resistenciasDePassiva: [...new Set(semTecnicaBloqueada(efeitosDosPassivos(creature))
      .filter((e) => e.canal === "resistenciaDano" && e.alvo)
      .map((e) => e.alvo))],
    /* Os números do dono que os tipos especiais leem (2026-09-30, Etapa 8): o
       grau dele (a refeição do Corpo Biológico, "considerando a BT de seu
       Criador"), o CL (a duração do Corpo, PV-01), o mod de Presença (o Nível de
       Aptidão da Maldição) e os TRs (a Marionete manda Vontade e Astúcia ao
       invocador). `fundamentos` conta as Técnicas marcadas, para o aviso. */
    grauRankDono: grau.rank,
    /* Os compostos (2026-10-01, Etapa 9): o limite em campo (o teto de membros de
       uma Horda), a Hoste Amaldiçoada, os núcleos (que não compõem Horda) e o
       tamanho do dono, que já existe (PV-19), para o Mecha "maior que o
       Controlador". */
    limiteCampo: controle.ativo ? controle.limiteCampo : undefined,
    hosteAmaldicoada: habilidades.efetivas.includes("ctr_hoste_amaldicoada"),
    nucleosIds: idsDeNucleos(creature?.multiplosNucleos),
    tamanhoDono: tamanho.value,
    clControlador: aptidao.efetivo?.cl ?? 0,
    modPresenca: modByAttr.presenca ?? 0,
    trsDoDono: Object.fromEntries((testes.resistencias ?? [])
      .map((r) => [r.value, { bonus: r.bonus, prof: r.prof ?? null }])),
    fundamentos: tecnicaInata.fundamentoIds.length,
    /* O estado de MESA de cada invocação (em campo, auxílios ligados). Vem por
       `opcoes` e nunca pela criatura, pela mesma razão da concessão: é sessão,
       e o rascunho automático do criador não pode gravá-lo na ficha. */
    sessaoInvocacoes: opcoes.invocacoes,
  };
  const invocacoes = {
    ...resolveInvocacoesList(creature?.invocacoes, donoInvoc), controle,
    emCampo: invocacoesEmCampo,
    // Os dois níveis de Controlador, com nomes distintos (DA-13, 2026-09-30).
    nivelControladorReal, nivelEscalonamentoControlador,
    // A Hoste Amaldiçoada, para o criador oferecer o par de hordas (Etapa 9).
    hosteAmaldicoada: donoInvoc.hosteAmaldicoada,
  };
  const hordas = {
    ...resolveHordasList(creature?.hordas, creature?.invocacoes, donoInvoc),
    emCampo: hordasEmCampo,
  };
  const quimeras = resolveQuimerasList(creature?.quimeras, creature?.invocacoes, donoInvoc);
  /* Os Corpos de Múltiplos Núcleos e o Mecha (2026-10-01, Etapa 9). O Mecha é da
     SESSÃO (a linha `mecha`), e só existe com a mesa. */
  const multiplosNucleos = resolveMultiplosNucleosList(creature?.multiplosNucleos, creature?.invocacoes, donoInvoc);
  const linhaMecha = opcoes.invocacoes?.mecha;
  const mecha = linhaMecha?.estado === "ativa" ? resolveMecha(linhaMecha, invocacoes.lista) : null;

  // Focos de interlúdio (orçamento de Treinamento) = ND + Outros.
  // "Outros" = bônus de poderes que concedem treinos (sistema futuro),
  // lido de creature.focosBonus (0 por ora), mais a Habilidade Geral
  // Treinamentos (metade do ND por pega).
  /* ⚠ NO JOGADOR O NÚMERO É DIGITADO. Autor, 2026-08-30: "É o mestre que decide
     quando um Personagem de Jogador ganha Focos de Interlúdios, e não algo
     mecânico." O canal continua somando por cima, para uma habilidade ou Addon
     ainda poder conceder Foco. */
  const focosLivres = Math.max(0, Math.trunc(Number(creature?.focosLivres) || 0));
  /* ⚠ A CARTEIRA SUBSTITUI A BASE, e não soma nela: somar cobraria o mesmo
     Interlúdio duas vezes, uma pelo ND e outra pela anotação. O canal `focos`
     segue por cima nos três casos, que é como uma habilidade ou outro addon
     ainda concede Foco. Ver a nota de `carteiraFocos` em `LIBERACOES`. */
  const baseFocos = carteiraAlimentaFocos
    ? carteira.interludios
    : (ehJogador("focosLivres")
      ? (regrasAddon.focosPorNivel == null ? focosLivres : Math.floor(nd * regrasAddon.focosPorNivel))
      : nd);
  const focosTotais = baseFocos + canal("focos");

  // (Pontos de atributo agora vêm do método + pool de nível — ver afty-atributos.js.)

  // ---------- FONTES DE CADA VALOR (hover da UI) ----------
  // Uma parcela por origem, na ordem em que a fórmula soma. `texto` substitui o
  // número quando a parcela não é uma soma (multiplicadores do HP).
  // Parcelas do Motor entram nomeadas pela habilidade/treino que as gerou.
  const rotulo = ATTR_LABEL;
  // `suplantado` viaja junto para o hover poder mostrar o perdedor do pool
  // exclusivo apagado, em vez de escondê-lo. Sem isso o jogador veria o +5 do
  // Shikigami simplesmente sumir da ficha, sem nada dizendo por quê.
  const doMotor = (id, alvo = null) =>
    detalhesDoCanal(ef, id, alvo, true).map((d) => ({
      label: d.nome, valor: d.valor,
      ...(d.suplantado ? { suplantado: true } : {}),
    }));
  /* As parcelas de RD do equipamento que caem NESTE canal, já nomeadas pelo
     `resolveEquipamentos`. Vazia quando não há escudo equipado. */
  const rdPartesDe = (canal) =>
    (equip.rdPartes ?? []).filter((p) => p.canal === canal).map((p) => ({ label: p.label, valor: p.valor }));
  const TIPO_LABEL = { combatente: "Combatente", misto: "Misto", conjurador: "Conjurador", restringido: "Restringido" };
  const PATAMAR_LABEL = { comum: "Comum", desafio: "Desafio", calamidade: "Calamidade", beyond: "Beyond" };
  const divTexto = (d) => String(d).replace(".", ",");
  /* A parcela que o Fragilizado tira de uma RD, para o hover fechar em zero. */
  const zeradaPorCondicao = (v) => (fragilizado && v ? [{ label: fragilizado, valor: -v }] : []);

  const partes = {
    totalAptidao: semEnergia
      ? [{ label: "Sem energia amaldiçoada", valor: 0 }]
      : [...partesAptidaoND, ...doMotor("pontosAptidao")],
    // Só o Motor: os pontos de nível moram no `resumoAtributos`, que é da aba.
    pontosAtributoExtra: doMotor("pontosAtributo"),
    // A Penalidade de Armadura item por item, mais o Motor. Ver o bloco dela.
    penalidadeDestreza: partesPenalidade,
    hp: [
      ...(bloodfeast.tem ? [{ label: "Bloodfeast: energia convertida", valor: peOriginal * 3 },
        ...bloodfeast.passivas.filter((p) => p.custoPV).map((p) => ({ label: p.nome, valor: -p.custoPV }))] : []),
      ...(pvPorClasse
        ? linhasBaseDeClasse((e, i) => pvDaClasse(e.id, e.nivel, { inicial: i === 0 }))
        : [{ label: `Base do Tipo (${TIPO_LABEL[tipo] ?? tipo})`, valor: hpBase }]),
      // O atributo TROCADO aparece com o nome dele, e não somado por baixo de
      // uma "Constituição" que não está mais na conta. Mesmo desenho da Defesa.
      /* "× ND" é vocabulário de criatura. O jogador tem Nível, e a soma é a
         mesma: o livro manda somar o Mod. de Constituição em todo nível e chama
         isso de retroativo, o que dá N × ModCon. */
      { label: attrHp === "constituicao"
          ? `Constituição × ${pvPorClasse ? "Nível" : "ND"}`
          : `${rotulo[attrHp] ?? attrHp} × ${pvPorClasse ? "Nível" : "ND"} (no lugar da Constituição)`,
        valor: nd * modHp },
      ...detalhesDoCanal(ef, "hpAtributo", attrHp)
        .map((d) => ({ label: d.nome, texto: "substitui" })),
      ...doMotor("hp"),
      /* ⚠ O CANAL `almaMax` SOMA NO PV DO JOGADOR, e até 2026-09-18 ele somava
         CALADO: a Consciência Absoluta da Alma levava o PV de 162 para 187 e o
         hover continuava listando 162, com as parcelas sem fechar com o total.
         Quem ganhou Alma precisa ver de onde ela veio, pelo nome da fonte.

         Só no jogador. Na criatura o mesmo canal é porcentagem, entra pelo
         `almaMult` e já tem a linha "Integridade da Alma ×N" logo abaixo. */
      ...(almaPilha ? doMotor("almaMax") : []),
      ...(equip.hpMaxBonus ? [{ label: "Equipamento", valor: equip.hpMaxBonus }] : []),
      ...(almaMult !== 1 ? [{ label: "Integridade da Alma", texto: `×${divTexto(almaMult)}` }] : []),
      ...(hpPatamarMult !== 1 ? [{ label: `Patamar (${PATAMAR_LABEL[patamar] ?? patamar})`, texto: `×${hpPatamarMult}` }] : []),
      ...doMotor("hpMult").map((fonte) => ({
        ...fonte,
        valor: undefined,
        texto: `× ${fonte.valor}`,
      })),
      /* A perda que a Alma ferida impõe ao teto, por último e NEGATIVA, porque é
         descontada do total já arredondado. Sem esta linha o jogador vê o PV
         máximo menor e não tem onde ler o motivo. */
      ...(danoNaAlma ? [{ label: "Dano na Alma", valor: -danoNaAlma }] : []),
      ...regrasAddon.fontesMultiplicadorPvFinal.map((fonte) => ({
        label: fonte.nome,
        texto: `×${divTexto(fonte.valor)}`,
      })),
    ],
    pe: [
      ...(bloodfeast.tem ? [{ label: "Bloodfeast: convertido em Vida", valor: -peOriginal }] : []),
      ...(pvPorClasse
        ? linhasBaseDeClasse((e) => peDaClasse(e.id, e.nivel))
        : [{ label: `Base do Tipo (${TIPO_LABEL[tipo] ?? tipo})`, valor: peBase }]),
      /* ⚠ `peQntEfetivo`, e não `peQnt`. Com o cru, o hover do jogador listava
         "Quantidade de PE +7" numa ficha que nem tem o campo, e as parcelas
         somavam 80 contra um total de 73. Número certo com detalhamento errado
         é bug, e é a mesma regra do `defesaAtributo`. */
      ...(peQntEfetivo ? [{ label: "Quantidade de PE", valor: peQntEfetivo }] : []),
      /* ⚠ `modTecnicaNoPE`, e não `modTecnica`. Lutador e Combatente não somam o
         modificador, e uma ficha sem Classe nenhuma também não: com o valor cheio
         o hover mostrava a parcela numa conta que não a tem, e as parcelas não
         fechavam com o total. Mesmo bug da Quantidade de PE, mesma regra. */
      ...(modTecnicaNoPE ? [{ label: `Mod. da Técnica (${rotulo[tecnicaAttr] ?? tecnicaAttr})`, valor: modTecnicaNoPE }] : []),
      ...doMotor("pe"),
      /* ⚠ UMA LINHA POR PASSIVA, com o nome dela. Um "Passivas -12" só diria
         quanto sumiu e não de onde, e a ficha que tem quatro delas é justamente
         a que precisa saber qual sai caro. Mesma regra da `Fonte com nome`. */
      ...passivasNoPe.linhas.map((l) => ({ label: `${l.nome} (Passiva)`, valor: -l.custo })),
      ...(passivasSemCustoPeMaximo && passivasNoPeBrutas.total
        ? [...regrasAddon.fontesPassivasSemCusto, ...regrasVotos.fontesPassivasSemCusto]
          .map((fonte) => ({ label: fonte.nome, texto: "Passivas sem custo de PE Máximo" }))
        : []),
      ...regrasAddon.fontesMultiplicadorPeMaximo.map((fonte) => ({
        label: fonte.nome,
        texto: `×${divTexto(fonte.valor)}`,
      })),
      ...fontesPeMult.map((fonte) => ({ label: fonte.nome, texto: `×${divTexto(fonte.valor)}` })),
      ...(!regrasAddon.ignoraMultiplicadorPeMaximoDeVotos
        ? regrasVotos.fontesMultiplicadorPeMaximo.map((fonte) => ({
          label: fonte.nome,
          texto: `×${divTexto(fonte.valor)}`,
        }))
        : regrasAddon.fontesIgnoraMultiplicadorPeVotos.map((fonte) => ({
          label: fonte.nome,
          texto: "ignora a redução de PE Máximo dos Votos",
        }))),
    ],
    defesa: [
      { label: "Base", valor: 10 },
      { label: valoresDoJogador ? "Metade do Nível" : `Nível ÷ ${divTexto(divisorDefesa)}`,
        valor: defEscala },
      // O atributo TROCADO aparece com o nome dele, e não somado por baixo de
      // uma "Destreza" que não está mais na conta. Quem trocou vem junto no
      // rótulo, senão o jogador vê "Força" e não sabe de onde saiu.
      { label: attrDefesa === "destreza"
          ? "Destreza"
          : `${rotulo[attrDefesa] ?? attrDefesa} (no lugar da Destreza)`,
        valor: modDefesa },
      ...detalhesDoCanal(ef, "defesaAtributo", attrDefesa)
        .map((d) => ({ label: d.nome, texto: "substitui" })),
      /* ⚠ Some no jogador, e não vira zero: a fórmula dele não tem Maestria, e
         uma linha "Maestria 0" diria que tem e que está zerada. */
      ...(valoresDoJogador ? [] : [{ label: "Maestria", valor: bt }]),
      ...(equip.uniformeDefesa ? [{ label: "Uniforme", valor: equip.uniformeDefesa }] : []),
      ...(carga.defesa ? [{ label: "Sobrecarga", valor: carga.defesa }] : []),
      ...doMotor("defesa"),
      ...(aparar ? [aparar] : []),
    ],
    cd: [
      { label: "Base", valor: 10 },
      { label: valoresDoJogador ? "Metade do Nível" : `Nível ÷ ${divTexto(divisorCD)}`,
        valor: cdEscala },
      { label: `Mod. da Técnica (${rotulo[tecnicaAttr] ?? tecnicaAttr})`, valor: modTecnica },
      { label: "Maestria", valor: bt },
      ...(equip.cdBonus ? [{ label: "Equipamento", valor: equip.cdBonus }] : []),
      ...doMotor("cd"),
    ],
    /* ⚠ O EQUIPAMENTO ENTRA PARCELA A PARCELA, e não mais como uma linha
       "Equipamento" que somava tudo. O livro lista a coluna de RD do escudo e a
       tabela de grau da Ferramenta como fontes separadas, e a aba de Resistências é
       onde se consulta de onde a RD veio. O `rdPartesDe` filtra pelo canal
       porque a MESMA parcela cai na RD Geral na criatura e na Física no jogador
       (divergência `rdEscudoFisico`). */
    rdGeral: [
      ...(rdSemBase ? [] : [{ label: `Base do Tipo (${TIPO_LABEL[tipo] ?? tipo})`, valor: rdGeralBase }]),
      ...rdPartesDe("rdGeral"),
      ...doMotor("rdGeral"),
      ...(pilhaDoEscudo === "rdGeral" && escudoNaMao ? doMotor("rdEscudo") : []),
      ...zeradaPorCondicao(rdGeralSemCondicao),
    ],
    rdEspecifico: [
      ...(rdSemBase ? [] : [{ label: `Base do Tipo (${TIPO_LABEL[tipo] ?? tipo})`, valor: rdEspecificoSemCondicao - canal("rdEspecifico") }]),
      ...doMotor("rdEspecifico"),
      ...zeradaPorCondicao(rdEspecificoSemCondicao),
    ],
    rdAlma: [...doMotor("rdAlma"), ...zeradaPorCondicao(rdAlmaSemCondicao)],
    ataquesExtras: doMotor("ataquesExtras"),
    rdFisico: [
      ...rdPartesDe("rdFisico"),
      ...doMotor("rdFisico"),
      ...(pilhaDoEscudo === "rdFisico" && escudoNaMao ? doMotor("rdEscudo") : []),
      ...zeradaPorCondicao(rdFisicoSemCondicao),
    ],
    movimento: [
      { label: "Base", valor: 9 },
      ...(valoresDoJogador ? [] : [{ label: "Maior de Força e Destreza × 1,5", valor: maxForDex * 1.5 }]),
      ...(carga.movimento ? [{ label: "Sobrecarga", valor: carga.movimento }] : []),
      ...doMotor("movimento"),
      ...doMotor("movimentoMult").map((fonte) => ({
        ...fonte,
        valor: undefined,
        texto: `× ${fonte.valor}`,
      })),
      // Por último, porque transforma o valor final. Ver `movimentoCondicao`.
      ...movimentoCondicao.partes,
    ],
    // O voo, com as mesmas três camadas do movimento: fontes, multiplicador e condição.
    voo: vooBase > 0 ? [
      ...doMotor("voo"),
      ...doMotor("movimentoMult").map((fonte) => ({
        ...fonte,
        valor: undefined,
        texto: `× ${fonte.valor}`,
      })),
      ...vooCondicao.partes,
    ] : [],
    iniciativa: [
      ...(valoresDoJogador ? [] : [{ label: "Maestria ÷ 2", valor: INT(bt / 2) }]),
      { label: "Destreza", valor: modDes },
      ...doMotor("iniciativa"),
    ],
    pvTemporario: doMotor("pvTemporario"),
    pontosPreparo: doMotor("pontosPreparo"),
    preparoTemporario: doMotor("preparoTemporario"),
    /* Os três canais da MESMA rolagem, cada um com a parcela dele. As faces
       valem a maior, então só viram linha quando há disputa ou quando vêm de
       uma fonte que não deu dado nenhum: com uma fonte só, a linha de dados já
       mostra o dado final. O d6 de base entra quando ninguém chega nele. */
    regeneracao: regeneracao.dados > 0 ? (() => {
      const faces = Math.max(6, ...facesRegen);
      const dados = doMotor("regeneracaoDados");
      const fontesFaces = detalhesDoCanal(ef, "regeneracaoFaces", null, true);
      const nomesDados = new Set(dados.map((p) => p.label));
      const mostraFaces = fontesFaces.length > 1 || fontesFaces.some((d) => !nomesDados.has(d.nome));
      return [
        ...dados.map((p) => ({
          label: p.label, texto: `${p.valor}${regeneracao.dado}`,
          ...(p.suplantado ? { suplantado: true } : {}),
        })),
        ...(facesRegen.some((v) => v >= 6) ? [] : [{ label: "Dado Base", texto: "d6" }]),
        ...(mostraFaces ? fontesFaces.map((d) => ({
          label: d.nome, texto: `d${d.valor}`,
          ...(d.suplantado || d.valor < faces ? { suplantado: true } : {}),
        })) : []),
        ...doMotor("regeneracaoFixa"),
      ];
    })() : [],
    /* Médio mais os degraus do canal `tamanho`. A última linha só aparece
       quando a soma passou da menor ou da maior categoria e foi aparada. */
    tamanho: [
      { label: "Base", texto: tamanhoPorDegraus(0).label },
      ...detalhesDoCanal(efSemTamanho, "tamanho", null, true).map((d) => ({
        label: d.nome,
        texto: `${d.valor > 0 ? "+" : ""}${d.valor} ${Math.abs(d.valor) === 1 ? "Categoria" : "Categorias"}`,
        ...(d.suplantado ? { suplantado: true } : {}),
      })),
      ...(tamanho.passo !== degrausTamanho ? [{ label: "Limite", texto: tamanho.label }] : []),
    ],
    maestria: [{ label: valoresDoJogador ? `Nível ${nd}` : `ND ${nd}`, valor: bt }],
    atencao: [
      { label: "Base", valor: 10 },
      ...(testes.atencaoPartes ?? [{ label: "Percepção", valor: testes.atencao - 10 }]),
      ...doMotor("atencao"),
    ],
    /* ⚠ OS DOIS FICAM VAZIOS NA FICHA DE JOGADOR, onde a Guarda é `null`. O
       `guardaAtual` logo abaixo já se protegia assim, e estes não: eles seguiam
       montando uma linha "Patamar (...)" para explicar um número que não existe.
       Passou despercebido até 2026-08-31 porque a linha citava o MESMO patamar
       nos dois sistemas e o assert do clone via dois hovers idênticos. Com o
       Patamar neutralizado no jogador os rótulos passaram a divergir, e o assert
       apontou o resto. */
    guardaBonus: guarda ? [
      { label: rotuloGuarda(), valor: guardaBonusBase },
      ...doMotor("guardaBonus"),
    ] : [],
    guardaVida: guarda ? [
      // A conta escrita como o autor a deu: 5 × ND ou 10 × ND. Uma linha só,
      // porque o multiplicador sem o ND ao lado não se lê.
      { label: `${rotuloGuarda()}, ${patamarGuarda === "beyond" ? 10 : 5} × ND`, valor: guardaVidaBase },
      ...doMotor("guardaVida"),
    ] : [],
    /* O bônus CORRENTE, que é o que a Defesa e os TRs recebem agora. A primeira
       linha é o teto da rodada e a segunda é o desgaste, escrita como perda para
       o hover fechar a conta: sem ela o leitor soma 5 e vê 1 na tela. */
    guardaAtual: guarda ? [
      { label: "Teto da Rodada", valor: guarda.bonusMax },
      ...(guarda.golpes > 0 && guarda.noAr
        ? [{ label: `Golpes Sofridos (${guarda.golpes})`, valor: guarda.bonus - guarda.bonusMax }]
        : []),
      ...(guarda.motivo ? [{ label: guarda.motivo, valor: -guarda.bonusMax }] : []),
    ] : [],
  };

  // ---------- FONTES DE CADA ATRIBUTO E DE CADA LIMITE ----------
  // Dois hovers por linha da tabela de Atributos: um no valor efetivo e um no
  // limite. As parcelas do Motor entram NOMEADAS pela habilidade, talento ou
  // treino que as gerou, que é o que o `detalhes` do agregado carrega.
  //
  // A ordem é a da fórmula, e a última linha é a PERDA no limite, quando existe.
  // Ela é o que fecha a conta para o jogador: sem ela o hover soma 24 e o número
  // grande diz 20, sem explicação.
  const METODO_LABEL = { pontos: "Compra por Pontos", fixos: "Valores Fixos", rolagem: "Rolagem" };
  const partesAtributo = {};
  const partesLimite = {};
  for (const k of ATTR_KEYS) {
    const perdido = perdaNoLimite[k] || 0;
    partesAtributo[k] = [
      { label: `Base (${METODO_LABEL[creature?.attrMethod || "pontos"]})`, valor: a[k] ?? 10 },
      ...(atributosAddon.fontes[k] ?? []).filter((f) => f.bonusBase).map((f) => ({ label: f.nome, valor: f.bonusBase })),
      ...(nivelAlloc[k] ? [{ label: "Pontos de Nível", valor: nivelAlloc[k] }] : []),
      ...(attrBonus[k] ? [{ label: "Origem", valor: attrBonus[k] }] : []),
      ...(desenvValor[k] ? [{ label: "Desenvolvimento Inesperado", valor: desenvValor[k] }] : []),
      ...(equip.attrBonus[k] ? [{ label: "Equipamento", valor: equip.attrBonus[k] }] : []),
      ...doMotor("atributo", k),
      ...(perdido ? [{ label: `Perdido no limite ${tetoAplicado[k] ?? attrLimiteEfetivo[k]}`, texto: `−${perdido}` }] : []),
      ...(apiceDelta[k] ? [{ label: "Talismã do Ápice", valor: apiceDelta[k] }] : []),
    ];
    const daOrigem = Math.max(limBase[k] ?? ATTR_LIMITE_PADRAO, limOrigem[k] ?? 0) - ATTR_LIMITE_PADRAO;
    const partesDoLimite = [
      { label: "Limite padrão", valor: ATTR_LIMITE_PADRAO },
      ...(daOrigem ? [{ label: tipo === "restringido" && !variacaoDoRestringido ? "Ápice Corporal Humano" : "Origem", valor: daOrigem }] : []),
      ...(desenv[k] ? [{ label: "Desenvolvimento Inesperado", valor: desenv[k] }] : []),
      ...(limPool[k] ? [{ label: "Bônus em Atributo", valor: limPool[k] }] : []),
      ...doMotor("limiteAtributo", k),
      ...(atributosAddon.fontes[k] ?? []).filter((f) => f.limiteExtra).map((f) => ({ label: f.nome, valor: f.limiteExtra })),
    ];
    /* O LIMITE TEM O PRÓPRIO TETO, e o hover dele precisava da mesma linha de
       fechamento que o valor já tinha. Duas fontes de +5 num atributo comum
       somam 30 e a soma bate; três somam 35, o número grande diz 30 e o hover
       ficava com 5 sem dono. É o mesmo defeito do lado do valor, só que no
       teto do SISTEMA em vez do limite do atributo. */
    const somaDoLimite = partesDoLimite.reduce((soma, x) => soma + (Number(x.valor) || 0), 0);
    const acimaDoTeto = somaDoLimite - attrLimiteEfetivo[k];
    const fonteFixa = (atributosAddon.fontes[k] ?? []).find((f) => f.limiteFixo === attrLimiteEfetivo[k]);
    partesLimite[k] = fonteFixa
      ? [...partesDoLimite, { label: fonteFixa.nome, valor: -acimaDoTeto }]
      : acimaDoTeto > 0
      ? [...partesDoLimite, { label: `Teto do sistema ${attrLimiteEfetivo[k]}`, texto: `−${acimaDoTeto}` }]
      : partesDoLimite;
  }

  // ---------- FONTES DE CADA NÍVEL DE APTIDÃO ----------
  // Os pontos alocados e cada concessão pelo nome, das DUAS etapas que o nível
  // lê (o montante e o pré-contexto, onde mora a Expansão de Domínio). O que o
  // teto da trilha cortou fecha a conta na última linha. Sem energia não há
  // trilha nenhuma, e a concessão que ficou nos detalhes não vira linha.
  const partesAptidao = {};
  if (!semEnergia) {
    for (const { key } of trilhasOrigem) {
      const efetivo = aptidao.efetivo?.[key] ?? 0;
      const linhas = [
        ...(aptidao.alocado?.[key] ? [{ label: "Pontos Alocados", valor: aptidao.alocado[key] }] : []),
        ...[efMontante, efPreContexto]
          .flatMap((res) => detalhesDoCanal(res, "nivelAptidao", key))
          .filter((d) => d.alvo === key)
          .map((d) => ({ label: d.nome, valor: d.valor })),
      ];
      const soma = linhas.reduce((s, x) => s + (Number(x.valor) || 0), 0);
      if (soma !== efetivo) linhas.push({ label: `Limite da Trilha ${aptidao.limite?.[key] ?? efetivo}`, valor: efetivo - soma });
      partesAptidao[key] = linhas;
    }
  }

  /* ============================================================ */
  /* REQUISITOS REAVALIADOS COM A FICHA INTEIRA                    */
  /* ============================================================ */
  /* ⚠ O `inacessiveis` NASCIA CEGO, e a Ficha Final acusava pré-requisito não
     atendido em coisa que estava atendida. Achado em 2026-09-09 pelo autor, no
     Revestimento Constante (Conjurador 8°, pede a Aptidão Cobrir-se) com a
     Cobrir-se na ficha.

     A causa: o `resolveHabilidades` monta o ctx dele com quatro campos
     (`niveisPorEspec`, `escolhidas`, `escolhasHabilidade`, `almaLivre`), e o
     avaliador pergunta por outros cinco que não estão lá. Um requisito de
     Aptidão faz `(ctx.aptidoes || []).includes(...)` contra uma lista que é
     `undefined`, e a resposta é SEMPRE falsa. O mesmo vale para atributo,
     perícia, TR e Ofício. O criador nunca teve o problema porque ele monta o
     ctx com o `derived` PRONTO, que é exatamente o que falta aqui.

     ⚠ NÃO DÁ PARA SÓ ENCHER O CTX LÁ EM CIMA, e é por isso que a reavaliação
     mora aqui embaixo. `attrEff` e as perícias nascem DEPOIS das habilidades, e
     têm de nascer: habilidade concede perícia. Perguntar por elas antes seria
     inverter uma dependência real. A saída é a do criador, feita uma vez só e
     no motor: com a ficha fechada, reavaliar o que ficou de fora.

     ⚠ É REPORTE, e não remoção. Nada é tirado da ficha por causa desta lista,
     e por isso recalculá-la no fim é seguro: ninguém a leu antes daqui. Os
     outros dois `inacessiveis` do derivado NÃO precisam disto e ficaram como
     estavam: as Gerais só perguntam ND, e as Lendárias só ND e nível de classe.
     Medido, não suposto. */
  const periciaProfMapa = Object.fromEntries((testes.pericias ?? []).map((p) => [p.id, p.prof ?? null]));
  const resistenciaProfMapa = Object.fromEntries(
    (testes.resistencias ?? []).map((r) => [r.id ?? r.value, r.prof ?? null]),
  );
  const periciaOficiosMapa = Object.fromEntries(
    (testes.pericias ?? []).filter((p) => ehPericiaOficio(p.id)).map((p) => [p.id, p.oficios ?? []]),
  );
  /* O MESMO ctx que o criador monta. Se os dois divergirem, a Ficha volta a
     discordar da tela onde a escolha foi feita, que é o bug de origem. */
  const ctxRequisitos = {
    nd,
    origemId,
    origensQualificadas: origensQuali,
    claId: creature?.core?.origem?.cla ?? null,
    niveisPorEspec: habilidades.niveisPorEspec,
    escolhidas: habilidades.canonicas ?? habilidades.efetivas,
    nivelPorHabilidade: habilidades.nivelPorHabilidade,
    imitadas: habilidades.imitadas,
    escolhasHabilidade: habilidades.escolhas?.mapa,
    almaLivre: habilidades.almaLivre,
    attrEff,
    aptidoes: aptidoesIds,
    periciaProf: periciaProfMapa,
    resistenciaProf: resistenciaProfMapa,
    periciaOficios: periciaOficiosMapa,
    feiticos: creature?.feiticos,
    limitesAtributo: limitesAtributoBase,
  };
  /* ⚠ OS QUATRO ORÇAMENTOS DE ESCOLHA FECHAM DE NOVO AQUI, com o agregado
     FINAL (autor, 2026-10-02: *"Vagas de Talento em Feitiço não está
     funcionando"*). `vagasHabilidade`, `vagasTalento`, `vagasMelhoria` e
     `vagasLendaria` eram lidos só do montante, lá em cima, porque o orçamento
     fecha antes dos efeitos. Feitiço Passivo, Funcionamento Básico, Buff de Mesa
     e Habilidade Única entram depois, no bolo comum: a vaga aparecia no hover do
     efeito ("1 de 1 ativos") e o contador não mexia. É o mesmo defeito do Talento
     que dava vaga de Talento, consertado em 2026-09-02 por um passe à parte.

     Refechar no fim é seguro porque as vagas só CONTAM: nenhuma escolha sai ou
     entra por causa delas, e o primeiro fechamento não alimenta nada além dos
     contadores. O agregado já traz o montante e o Talento, então o valor final
     SUBSTITUI o de cima, e não soma nele. */
  const habilidadesFinal = {
    ...habilidades,
    ...contaOrcamentoHabilidades({
      gastosHabilidade: habilidades.gastosHabilidade,
      talentos: habilidades.talentosGastos,
      comum: canal("vagasHabilidade") + vagasHabilidadePorClasse,
      exclusivasTalento: canal("vagasTalento"),
    }),
    inacessiveis: (habilidades.efetivas ?? [])
      .filter((id) => !avaliarAcessoHabilidade(getHabilidade(id), ctxRequisitos).ok),
    // A vaga de escolha aninhada também só conta, e refecha pelo mesmo motivo.
    escolhas: refecharVagasEscolha(habilidades.escolhas, ef.porAlvo?.vagasEscolha || {}),
  };
  const altoNivelFinal = comVagasDeCanal(altoNivel, {
    vagasMelhoria: canal("vagasMelhoria"),
    vagasLendaria: canal("vagasLendaria"),
  });
  /* O Talento já recebia `attrEff` e `aptidoes` na chamada, e ficava cego só
     para os três de treino. Reavaliar os dois pelo mesmo ctx evita a pergunta
     "qual dos dois estava certo" na próxima vez. */
  const talentosFinal = {
    ...talentos,
    inacessiveis: (talentos.escolhidas ?? [])
      .filter((id) => !avaliarAcessoTalento(getTalento(id), { ...ctxRequisitos, talentos: talentos.escolhidas })
        .ok),
  };

  // ---------- overrides de valor final (aba Cálculos) ----------
  const calc = { hp, pe, defesa, cd, rdGeral, rdEspecifico, rdAlma, movimento, atencao, iniciativa };
  const stats = {};
  for (const k of OVERRIDABLE) stats[k] = ov[k] != null ? ov[k] : calc[k];
  const isOverridden = (k) => ov[k] != null;

  return {
    ...stats,
    beneficiosTreinamento: beneficiosDeTreinoNaFicha(creature, { atencao: stats.atencao }),
    // O Deslocamento de Voo, em metros. Zero é não voar (2026-10-09).
    voo,
    /* LINHA MORTA: o que a ficha cita e o mundo não tem. Lista vazia é o caso
       normal. Quem mostra é a Ficha e o criador, e ela nunca impede nada de
       abrir (decisão 4 do autor). Ver afty-addons.js. */
    addonProblemas: problemasDeAddon(creature),
    armasTransformaveis: armasTransformaveis(creature, catalogoDoTipo("arma", creature), bt),
    /* O que o mestre concedeu NESTA SESSÃO, já com nome resolvido e com `morta`
       marcada quando o catálogo não conhece mais o id. Vazio é o caso normal, e
       é a lista que as duas telas de jogo mostram. Ver afty-concessao.js. */
    concedido: concessoesDaSessao(opcoes.concedido),
    /* As primitivas de Addon que ESTA criatura enxerga, pelo `permite` dos
       pacotes dela. Vazio é o caso normal, e é o que mantém a tela de quem só
       usa o raw exatamente como era. Ver `PRIMITIVAS` em afty-addons.js. */
    bloodfeast: bloodfeast.tem ? { ...bloodfeast, modCon, peOriginal, hpMax: hp } : { tem: false },
    primitivas: primitivasDaCriatura(creature),
    // O extrato da Loja de Catarse: saldo, gasto, compras e as vagas que elas
    // abriram. A tela lê daqui, e os efeitos já entraram no Motor lá em cima.
    catarse,
    /* O extrato do Espinho: Almas, cada item com quantidade e teto, os
       Equipamentos marcados e os avisos (os de nível entram aqui, e não no
       resolver). Os efeitos já entraram no Motor lá em cima. */
    espinho: { ...espinho, avisos: avisosEspinho },
    /* Os Pontos de Atributo que o Motor dá por cima dos pontos de nível (canal
       `pontosAtributo`, Espinho). A aba de Atributos soma no pool dela. */
    pontosAtributoExtra: canal("pontosAtributo"),
    // O extrato da Carteira: XP, dinheiro e Interlúdios anotados, o que saiu e
    // os totais. A aba lê daqui, e o `alimentaFocos` diz se os Interlúdios dela
    // são o orçamento de Focos da aba Interlúdios.
    carteira,
    adaptacoes: resumoAdaptacoes(creature, opcoes.adaptacoes),
    dharma: { ativo: temDharma(creature) },
    /* Os da ORIGEM entram na mesma lista (2026-09-29, Forma de Raposa): as três
       telas que desenham o interruptor leem só daqui, e o estado é o mesmo
       `treinosAtivos`. O nome ficou "Treino" por isso, e não por ser só dele.
       Mesmo id nas duas fontes vira um interruptor só, como entre duas Linhas. */
    gatilhosTreino: [
      ...new Map([...gatilhosDeTreino(creature), ...gatilhosDeOrigem(creature)]
        .map((gatilho) => [gatilho.id, gatilho])).values(),
    ].map((gatilho) => ({
      ...gatilho,
      ativo: !!opcoes.treinosAtivos?.[gatilho.id],
    })),
    /* O que os Addons desta criatura DESTRAVAM. Vazio é o caso normal. Ao
       contrário das `primitivas`, isto MUDA REGRA. Ver `LIBERACOES`. */
    liberacoes,
    /* A base da Defesa, para a trava do Feitiço Permutativo que perde Defesa:
       "caso a sua Defesa caia para um valor menor que a base (10 + Mod. de
       Destreza), o Feitiço não pode ser usado". O atributo é o que a Defesa de
       fato usa, então o `defesaAtributo` vale aqui também (ASSUNÇÃO). */
    defesaBase: 10 + modDefesa,
    // metadados / valores não sobrescrevíveis
    calc,                 // valores calculados (antes do override)
    isOverridden,
    maestria: bt,
    ataquesExtras,
    /* O sistema desta FICHA, já resolvido pelo `sistemaDaFicha`. Sai daqui porque
       quem só tem o derivado em mão (a sessão, por exemplo) não tem como
       perguntar, e a lei do projeto é que o sistema venha da ficha e nunca da
       rota. Ver o cabeçalho de `afty-sistema.js`. */
    sistema,
    regrasAfty: {
      multiplicadorPeMaximo,
      multiplicadorPvFinal: regrasAddon.multiplicadorPvFinal,
      passivasSemCustoPeMaximo,
      ignoraMultiplicadorPeMaximoDeVotos: regrasAddon.ignoraMultiplicadorPeMaximoDeVotos,
      focosPorNivel: sistema === "player" ? regrasAddon.focosPorNivel : null,
      nivelJogadorSemTeto: sistema === "player" && regrasAddon.nivelJogadorSemTeto,
      aptidaoApos20: sistema === "player" && regrasAddon.aptidaoApos20,
    },
    almaMult,
    /* ⚠ O que sai é o `almaMaxFinal`: na criatura é `100 + Melhoria de Alma`, e
       no jogador é o PV, porque a Integridade da Alma dele é igual ao máximo de
       Pontos de Vida. O nome do campo não muda, senão todo leitor mudaria. */
    almaMax: almaMaxFinal,
    /* O regime da Alma, já resolvido: `true` é a pilha do tamanho do PV, e
       `false` é a porcentagem da criatura. Sai daqui porque a sessão só tem o
       derivado em mão, e o sistema sozinho não responde mais: o jogador com o
       verbo `almaComoAfty` tem a Alma da criatura. */
    almaPilha,
    modTecnica,
    tecnicaAttr,
    totalAptidao,               // orçamento de NÍVEIS de aptidão (Afty continua a cada 2 ND depois do 20)
    totalAptidoesAmaldicoadas,  // quantas pode ter (progressão do jogador e canal vagasAptidao)
    caracteristicasAmaldicoadas, // { lista, catalogo, escolhidas, vagas, usadas, excedeu } (afty-caracteristicas-amaldicoadas.js)
    reduzNivelAptidao,          // quanto o pré-requisito de NÍVEL de cada Aptidão desce (0 no normal)
    requisitoTrilhaDispensado,  // { trilha: [fontes] } cujo requisito não trava Aptidão de outra trilha
    aptidao,              // níveis por trilha: { alocado, concedido, efetivo, gastos, limite }
    // As Aptidões Amaldiçoadas EFETIVAS (escolhidas + concedidas por nome pela
    // origem), para o `requerAptidao` da bancada saber quais linhas mostrar.
    // Segue a trava do semEnergia, igual ao motor.
    aptidoesEscolhidas: aptidoesIds,
    // Só as CONCEDIDAS, para a aba poder marcá-las como travadas: elas não são
    // escolha, e não podem ser desmarcadas nem cobrar orçamento.
    aptidoesConcedidas,
    aptidoesConcedidasOrigem,
    aptidoesConcedidasEspecializacao,
    // As do Addon vêm com a FONTE (o item que as dá, ou o pacote), porque a tela
    // escreve de onde a Aptidão veio, e "Origem" seria mentira para elas.
    aptidoesConcedidasAddon,
    // E as do Talento, com o nome dele na `fonte`, pela mesma razão.
    aptidoesConcedidasTalento,
    // As que a origem não deixa escolher na aba, para a aba travá-las.
    aptidoesVetadas: [...vetadasDaOrigem],
    dominios: resumoDominios,
    // A Exaustão de Técnica corrente (DA-16), para o aviso da Ficha. `null` sem ela.
    exaustaoTecnica,
    /* Proficiência RESOLVIDA (a escolhida na ficha mais a concedida pelo Motor).
       É o que os requisitos de treino conferem, e desde 2026-09-01 eles valem
       para Habilidades e Talentos também, e não só para as Aptidões.

       ⚠ SÃO TRÊS MAPAS, e não um. `periciaProf` e `resistenciaProf` respondem a
       faixa, e `periciaOficios` responde o NOME de cada vaga de Ofício, que é o
       que separa "Treinado em Ferramentas de Médico" de "Treinado em dois
       Ofícios": o primeiro pergunta qual ofício, o segundo pergunta quantos. */
    periciaProf: periciaProfMapa,
    resistenciaProf: resistenciaProfMapa,
    periciaOficios: periciaOficiosMapa,
    feiticos,             // { nivelMax, gastos, cdBase } — o orçamento é o de baixo
    // A Técnica Inata e o Fundamento (DA-07): bloqueio, motivo e a perda a gravar.
    tecnicaInata,
    // ⚠ O contexto CRU do DSL, exposto para o seletor de variáveis do Motor
    // (`vocabularioDsl` em afty-dsl-vocabulario.js). Sai cru de propósito: o
    // agrupamento custa uma varredura das ~663 chaves, e o `deriveAfty` roda por
    // combatente e por estado de combate. Quem monta a lista é a UI, num memo.
    contextoDsl: ctxTecnica,
    estilo,               // Novo Estilo da Sombra: { disponivel, conhecidas, gastos, vagas, gastoVagas, estados, avisos }
    dominioSimples,       // { tem, sustenta, area, custoErguer, custoSustentar, custoSustentarEstilo, + as partes de cada hover }
    estiloEfeitos,        // Motor resolvido por Técnica de Estilo Especial, para o editor mostrar cada linha
    tecnicaEfeitos,       // Funcionamento Básico resolvido, para o editor mostrar o valor de cada linha
    funcionamentoEfeitos, // o mesmo, por Funcionamento Básico ADICIONAL, chaveado pelo id
    passivosEfeitos,      // Motor resolvido por Feitiço Passivo / Característica
    votosEfeitos,         // Benefício e Malefício resolvidos pelo mesmo editor completo
    motorLinhaDano: { efeitos: efeitosLinhaDano, contexto: ctxTecnica },
    gerais,               // { escolhidas, gastos, ganhos, destravado, maxVezes, acesso, inacessiveis }
    efeitos: ef,          // Motor de Automação: { porCanal, porAlvo, detalhes, avisos }
    olhinhosLu: resolveOlhinhosLu({ tem: temOlhinhosLu, ...olhosLu, cl: aptidao.efetivo?.cl ?? 0 }),
    testes: aplicarOscilanteNosTestes(testes, opcoes.propriedadesArmas),
    dano,                 // { entradas: [{ id, nome, fonte, texto, alcance, propriedades, partes }] }
    tecnicasCombate,
    auxiliaresAtivos,
    cura,                 // { linhas: [{ id, nome, grupo, alcance, texto, fixo, usos, unidade, partes }] }
    dedicadas,            // Armas Dedicadas: { ativa, escolhidas, elegiveis, max, restante }
    /* As armas que a ORIGEM manda escolher (2026-10-09, a Arma Masterizada do
       Não-Feiticeiro): `[{ id, nome, armaId }]`, com `armaId` nulo quando a marcada
       saiu da ficha. O card de Dano do criador desenha o seletor. */
    armasDaOrigem: armasEscolhidasDaOrigem(creature).map((x) => ({
      ...x, armaId: armasParaDano.some((a) => a.id === x.armaId) ? x.armaId : null,
    })),
    // A origem tira a Energia Amaldiçoada (`semEnergia`): o criador monta a aba como a do Restringido.
    origemSemEnergia: semEnergiaDaOrigem,
    empolgacao,           // Lutador: { ativa, aprimorada, inicial, max, tabela }
    combate: combateExibicao, // simulação: estado já aparado nos tetos da ficha, e com o custo em PE reduzido
    manipulacaoCeu,
    vislumbre,            // Vislumbre Celeste: { tem, cl, descoberto, visao, reducaoPe, fadiga, ... }
    olhosAgulha,
    passivasIsentas,      // canal `passivaSemCusto` ligado: nenhuma Passiva tira PE Máximo
    pvTemporario,         // casca de PV vinda da simulação (Fluxo, Brutalidade Aprimorada)
    peTemporario,         // casca de PE POR FONTE: { combate:[], rodada:[], tem } — a sessão aplica
    regeneracao,          // cura no início do turno: { dados, dado, fixo }
    tetoPERDaCura,        // PER gastáveis de uma vez na Energia Reversa, o mesmo da linha de Cura e do Fluxo Constante
    pontosPreparo,        // recurso do Combatente (Artes do Combate), 0 sem ela
    preparoTemporario,    // casca de Preparo por rodada (Postura do Céu), que a sessão topa
    usosHabilidades,      // { [habId]: { max, recarga } } das habilidades com contador de usos
    configuracaoEspecializacao,
    mesa,                 // { [chave]: { usos, resultados } } de origem, talento, habilidade e opção (2026-09-28)
    golpeEspecial,        // { disponivel, autossuficiente } para o montador da Ficha
    recursoLabel,         // "Estamina" no Restringido, "Energia" no resto — mesmo PE
    partes,               // fontes de cada stat, para o hover da UI
    orcamentoHabilidades, // contador ÚNICO da aba: Feitiços + Habilidades Gerais
    origem: escolhasOrigem, // { porEscolha, mapa } — escolhas aninhadas de Origem e Clã
    /* `semRequisito` (2026-10-07): as Especializações de multiclasse cujo
       requisito de atributo a ficha não atende, pelos atributos PERMANENTES. Vazio
       na criatura, pela divergência `requisitoMulticlasse`. */
    especializacoes: {
      ...especializacoes,
      semRequisito: regraDo(sistema, "requisitoMulticlasse") === "player"
        ? multiclassesSemRequisito(especializacoes.escolhidas, attrPermanente)
        : [],
    },
    treinamentosEquipamento,
    treinoEscudo,
    /* ⚠ OS DOIS SAEM DA VERSÃO REAVALIADA, e não da que o resolver devolveu. A
       única diferença entre elas é o `inacessiveis`, que lá em cima nasce cego
       para cinco tipos de requisito. Ver o bloco "REQUISITOS REAVALIADOS". */
    habilidades: habilidadesFinal,  // { escolhidas, total, gastos, restante, excedeu, inacessiveis, niveisPorEspec }
    talentos: talentosFinal,        // { escolhidas, gastos, inacessiveis } — gasto já somado em habilidades.gastos
    altoNivel: altoNivelFinal, // { ativo, melhorias, lendarias, escolhas, apiceId } — orçamentos próprios
    imitacao,
    invocacoes,           // { lista, total, custoTotal, temWarnings }
    hordas,               // { lista, total, custoTotal } (líder + membros escalados)
    quimeras,             // { lista, total, custoTotal } (fusão de 2 a 4 invocações)
    multiplosNucleos,     // { lista, total } (dois núcleos de Corpo, uma entidade na mesa)
    mecha,                // a ficha do Mecha formado na mesa, ou null
    titaColosso,          // { ativo, membros, dobro, cabecaMax, membroMax, nomes } (afty-tita.js)
    focosTotais,          // orçamento de Focos de interlúdio = ND + bônus de poderes
    treino,               // contribuições agregadas dos Treinamentos (hp/pe/movimento/aptidao/defesa)
    nd, tipo, patamar,
    // Categoria de tamanho DERIVADA: Médio mais o que o Motor mover. A ficha não
    // a escolhe (autor, 2026-08-08). `tamanhoDegraus` é quanto o Motor moveu, e
    // vale para a UI dizer de onde veio.
    tamanho: tamanho.value,
    tamanhoLabel: tamanho.label,
    tamanhoDegraus: degrausTamanho,
    tamanhoEspacoAlcance: tamanho.espacoAlcance,
    mods: { forca: modFor, destreza: modDes, constituicao: modCon, inteligencia: modInt, sabedoria: modSab, presenca: modPre },
    attrEff,              // valor EFETIVO por atributo (base + efeitos, aparado no limite)
    attrPermanente,       // o que os PRÉ-REQUISITOS enxergam (sem os efeitos temporários)
    attrLimiteEfetivo,    // limite por atributo (padrão + Origem + Desenvolvimento + Motor, teto 30)
    /* O teto que cada atributo usou de fato, com a folga do acessório e o que a
       linha ATIVA levantou. Difere do de cima só enquanto um Feitiço Auxiliar
       de Atributo está no ar. */
    attrTetoAplicado: tetoAplicado,
    attrDesenv: desenvValor, // o que o Desenvolvimento Inesperado soma no VALOR (vazio no jogador)
    attrDesenvLimite: desenv, // o que ele soma no LIMITE, nos dois sistemas
    desenvolvimentoSoLimite: desenvSoLimite, // jogador Derivado: o quadro é só de limite
    attrNivelExtra: nivelExtraDesenv, // pontos de nível a mais (o Desenvolvimento do jogador)
    attrBonus,            // bônus de atributo da origem (efetivo)
    attrBonusBaseAddon: Object.fromEntries(ATTR_KEYS.map((k) => [k, atributosAddon.bonus(k)])),
    attrEquip: equip.attrBonus, // acessórios de atributo (passam o limite, param em 30)
    attrPerda: perdaNoLimite,   // ponto de bônus desperdiçado no limite, por atributo
    // Quanto o Motor soma em cada atributo. O builder RESERVA este espaço no pool
    // de nível, pela mesma convenção do bônus de origem: a concessão tem
    // prioridade e o ponto alocado volta ao pool, em vez de sumir no teto.
    //
    // ⚠ Só o estágio PERMANENTE entra. Um efeito de atributo temporário (nenhum
    // existe hoje, mas o estágio 1b existe para eles) encolheria o pool de nível
    // do criador por causa de um estado ligado na bancada de simulação, e o
    // jogador perderia pontos de ficha ao ligar Brutalidade.
    attrMotor: Object.fromEntries(ATTR_KEYS.map((k) => [k, valorCanal(efAttrPerm, "atributo", k)])),
    partesAtributo,       // fontes de cada atributo, para o hover da UI
    partesLimite,         // fontes de cada limite, para o hover da UI
    partesAptidao,        // fontes do Nível de Aptidão de cada trilha, para o hover da UI
    // ---------- Equipamentos ----------
    trilhasAptidao: trilhasOrigem,  // as que a ORIGEM tem (a Maldição não tem `er`)
    grauFeiticeiro: grau,  // { value, label, ordem, rank, ndMin } derivado do ND
    equip: equipFinal,     // parcelas do equipamento (entradas, custoGasto, avisos...)
    carga,                 // { espacosUsados, cargaLimite, cargaMaxima, sobrecarregado... }
    rdFisico,              // RD Física. O escudo entra aqui no JOGADOR, e na RD Geral na criatura.
    /* Defesas por tipo de dano: { linhas, porTipo, ativas, conflitos, avisos }.
       A `rd` de cada linha já é a EFETIVA contra aquele tipo (Geral + Física ou
       Alma + a do tipo), que é o número que se usa na mesa. */
    defesasDano,
    penalidadeDestreza: penalidadeArmadura, // uniforme + escudos + canal penalidadeArmadura, aparado em zero
    /* Guarda Inabalável: { ativa, bonusMax, vidaMax, passoPorGolpe }. O corrente
       (quantos golpes já levou, se ainda está de pé) é SESSÃO, e quem resolve é
       o `resolveGuarda` em ficha-sessao.js. */
    guarda,
    /* As CONDIÇÕES em cima da criatura, resolvidas: cada uma com o que faz e
       com a marca do que perdeu a disputa. Os números já entraram lá em cima, e
       isto é o que a aba Buffs e a bancada do criador desenham. */
    condicoes: {
      lista: marcaMovimentoNasLinhas(condicoes.ativas, movimentoCondicao.nome),
      falhas: condicoes.falhas,
      fragilizado,
      movimento: movimentoCondicao.fonte,
    },
  };
}

