        aptidoesAmaldicoadas: [...outras, ...Array(n).fill(id)],
        aptidaoOpcoesRepetidas: mapa,
      };
    });
  const setAptidaoOpcaoRepetida = (id, indice, valor) =>
    setDraft((d) => {
