  const setTreinoInstance = (lineId, alvo, prog) =>
    setDraft((d) => {
      const cur = treinosObj(d);
      const list = Array.isArray(cur[lineId]) ? cur[lineId] : [];
      const key = String(alvo).trim().toLowerCase();
