  const invocacoesArr = (d) => (Array.isArray(d.invocacoes) ? d.invocacoes : []);
  /* ---------- Equipamentos ---------- */
  // Uma entrada por linha do inventário. Equipar não é exclusivo (dá para
  // carregar duas armas equipadas), com uma exceção: o livro só deixa vestir
