  const equipArr = (d) => (Array.isArray(d.equipamentos?.itens) ? d.equipamentos.itens : []);
  const setEquipArr = (d, itens) => ({ ...d, equipamentos: { ...(d.equipamentos || {}), itens } });

  const addEquipamento = (tipo, refId) =>
    setDraft((d) => {
