      {!aberto && ativas.length > 0 && (
        <div className="flex flex-wrap gap-1 mt-1.5 pl-[22px]">
          {ativas.map((id) => (
            <span key={id} className="text-[10px] px-2 py-0.5 rounded bg-purple-950/40 border border-purple-800 text-purple-300">
